window.BANCO['CIEN']["9º Ano"] = [
  {"id": 1, "uid": "CIEN-9-001", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Regra do Octeto e Estabilidade", "dificuldade": "Fácil", "enunciado": "Os átomos da maioria dos elementos químicos ligam-se uns aos outros para atingir estabilidade eletrônica semelhante à dos gases nobres. De acordo com a Regra do Octeto, essa estabilidade é alcançada quando o átomo atinge:", "alternativas": {"A": "2 elétrons na camada K ou 8 elétrons na sua camada de valência mais externa.", "B": "18 prótons dentro do núcleo atômico.", "C": "Zero elétrons em todas as suas camadas eletrônicas.", "D": "Apenas números ímpares de elétrons em seus orbitais.", "E": "32 nêutrons em sua camada de valência."}, "resposta_correta": "A", "justificativa": "A Regra do Octeto estabelece que átomos tendem a ganhar, perder ou compartilhar elétrons para adquirir configuração eletrônica estável de gás nobre, com 8 elétrons na camada de valência (ou 2 elétrons na camada K, como o hélio).", "possui_imagem": true},
  {"id": 2, "uid": "CIEN-9-002", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligação Iônica: Conceito", "dificuldade": "Fácil", "enunciado": "A ligação iônica ocorre tipicamente entre átomos com grande diferença de eletronegatividade (metais e ametais). Nesse tipo de ligação química ocorre:", "alternativas": {"A": "Compartilhamento mútuo e igualitário de pares de elétrons.", "B": "Transferência definitiva de elétrons do metal (que vira cátion positivo) para o ametal (que vira ânion negativo), gerando atração eletrostática.", "C": "Fusão dos núcleos atômicos com liberação de energia nuclear.", "D": "Destruição de elétrons que se transformam em luz visível.", "E": "Formação de moléculas isoladas de baixa massa."}, "resposta_correta": "B", "justificativa": "Na ligação iônica, o metal de baixa energia de ionização doa elétrons de valência formando cátions, e o ametal de alta afinidade eletrônica recebe elétrons formando ânions; a ligação é mantida pela forte atração eletrostática entre íons de cargas opostas.", "possui_imagem": true},
  {"id": 3, "uid": "CIEN-9-003", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligação Covalente: Conceito", "dificuldade": "Fácil", "enunciado": "A ligação covalente ocorre preponderantemente entre ametais e ametais, ou entre ametais e o hidrogênio. A característica definidora da ligação covalente é o:", "alternativas": {"A": "Compartilhamento de pares de elétrons entre os átomos participantes.", "B": "Deslocamento de íons livres através de um solvente aquoso.", "C": "Abandono total de elétrons livres formando um mar de elétrons.", "D": "Rompe de prótons do núcleo em nêutrons livres.", "E": "Transporte de cargas por gravidade atômica."}, "resposta_correta": "A", "justificativa": "Na ligação covalente, como ambos os átomos participantes possuem alta eletronegatividade (tendência a atrair elétrons), nenhum deles cede elétrons integralmente; a estabilidade é alcançada pelo compartilhamento de pares eletrônicos.", "possui_imagem": true},
  {"id": 4, "uid": "CIEN-9-004", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligação Metálica: O Mar de Elétrons", "dificuldade": "Fácil", "enunciado": "Pedaços de ferro, cobre e alumínio são unidos por ligação metálica. O modelo físico clássico que explica as propriedades dos metais (como condutividade elétrica e maleabilidade) é o:", "alternativas": {"A": "Modelo do octeto rígido sem elétrons livres.", "B": "Modelo do 'mar de elétrons' (ou nuvem eletrônica deslocalizada), onde cátions metálicos fixos são envolvidos por elétrons livres em trânsito.", "C": "Modelo de compartilhamento de moléculas isoladas gasosas.", "D": "Modelo de atração magnética pura sem cargas elétricas.", "E": "Modelo de repulsão atômica de nêutrons."}, "resposta_correta": "B", "justificativa": "Nos metais, os elétrons de valência desprendem-se com facilidade dos átomos e movem-se livremente por toda a rede cristalina (mar de elétrons deslocalizados), cimentando os cátions metálicos e conferindo condutividade elétrica e ductilidade.", "possui_imagem": true},
  {"id": 5, "uid": "CIEN-9-005", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Propriedades dos Compostos Iônicos", "dificuldade": "Fácil", "enunciado": "O cloreto de sódio (NaCl, sal de cozinha) é um clássico composto iônico. Entre as propriedades físicas típicas dos compostos iônicos à temperatura ambiente, destaca-se:", "alternativas": {"A": "Serem líquidos voláteis com baixíssimo ponto de ebulição.", "B": "Serem sólidos cristalinos duros e quebradiços com elevados pontos de fusão e ebulição.", "C": "Serem gases inflamáveis incolores com cheiro de enxofre.", "D": "Conduzirem eletricidade com facilidade no estado sólido.", "E": "Serem maleáveis como massinha de modelar plástica."}, "resposta_correta": "B", "justificativa": "A forte atração eletrostática tridimensional entre íons no retículo cristalino iônico exige imensa energia térmica para ser rompida, conferindo altos pontos de fusão (>800 ºC no NaCl), dureza superficial e fragilidade mecânica sob impacto.", "possui_imagem": true},
  {"id": 6, "uid": "CIEN-9-006", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Condutibilidade Elétrica de Compostos Iônicos", "dificuldade": "Fácil", "enunciado": "O sal de cozinha sólido (cristal seco) NÃO conduz corrente elétrica. No entanto, ao dissolver esse sal em água ou ao fundi-lo (derretê-lo) em alta temperatura, o sistema passa a conduzir eletricidade com facilidade. Isso acontece porque:", "alternativas": {"A": "A água queima os elétrons do sal transformando-os em luz.", "B": "No estado sólido os íons estão presos no retículo cristalino; ao dissolver ou fundir, os íons (Na+ e Cl-) tornam-se livres para se mover e transportar cargas elétricas.", "C": "O sal de cozinha se transforma em cobre metálico na água.", "D": "A água líquida perde todos os seus prótons para o ar.", "E": "O sal atrai raios de tempestade para dentro do copo."}, "resposta_correta": "B", "justificativa": "A condução de corrente elétrica exige portadores de carga móveis. No retículo sólido, os íons estão imobilizados; a dissolução aquosa (dissociação) ou a fusão térmica libera os cátions e ânions no meio, viabilizando o transporte eletrolítico de corrente.", "possui_imagem": true},
  {"id": 7, "uid": "CIEN-9-007", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Exemplo de Composto Covalente Molecular", "dificuldade": "Fácil", "enunciado": "Qual das seguintes substâncias químicas é formada exclusivamente por ligações covalentes moleculares?", "alternativas": {"A": "Cloreto de sódio (NaCl).", "B": "Óxido de cálcio (CaO).", "C": "Água (H2O).", "D": "Ferro metálico (Fe).", "E": "Fluoreto de magnésio (MgF2)."}, "resposta_correta": "C", "justificativa": "A molécula de água (H2O) é formada pela união de hidrogênio e oxigênio (ametais) através de duas ligações covalentes simples por compartilhamento de elétrons.", "possui_imagem": true},
  {"id": 8, "uid": "CIEN-9-008", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligação Covalente Simples, Dupla e Tripla", "dificuldade": "Fácil", "enunciado": "Na molécula de gás oxigênio (O2), que respiramos, e na molécula de gás nitrogênio (N2), que compõe 78% do ar, os átomos unem-se por compartilhamento de elétrons, formando, respectivamente:", "alternativas": {"A": "Uma ligação iônica e uma ligação metálica.", "B": "Uma ligação covalente dupla (dois pares de elétrons) e uma ligação covalente tripla (três pares de elétrons).", "C": "Duas ligações simples e quatro ligações iônicas.", "D": "Apenas atrações de gravidade sem elétrons envolvidos.", "E": "Uma ligação metálica dupla e uma ponte de sal."}, "resposta_correta": "B", "justificativa": "O oxigênio (família 16, 6 elétrons de valência) precisa de 2 elétrons e forma ligação dupla (O=O); o nitrogênio (família 15, 5 elétrons de valência) precisa de 3 elétrons e forma ligação tripla (N≡N).", "possui_imagem": true},
  {"id": 9, "uid": "CIEN-9-009", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ductilidade e Maleabilidade dos Metais", "dificuldade": "Fácil", "enunciado": "Os metais podem ser facilmente transformados em fios compridos finos (como fios elétricos de cobre) ou conformados em lâminas finas (como papel-alumínio de cozinha). Essas propriedades tecnológicas são chamadas, respectivamente, de:", "alternativas": {"A": "Eletronegatividade e ionização.", "B": "Ductilidade (formação de fios) e maleabilidade (formação de lâminas).", "C": "Fragilidade e clivagem iônica.", "D": "Sublimação e decantação mecânica.", "E": "Oxidação e corrosão ácida."}, "resposta_correta": "B", "justificativa": "Ductilidade é a capacidade mecânica de um material de ser deformado plasticamente em fios sob tração; maleabilidade é a capacidade de ser deformado em folhas delgadas sob compressão sem fratura, explicadas pelo deslizamento de planos de cátions no mar de elétrons metálico.", "possui_imagem": true},
  {"id": 10, "uid": "CIEN-9-010", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Fórmula Iônica do Cloreto de Magnésio", "dificuldade": "Fácil", "enunciado": "O magnésio (Mg, família 2) possui 2 elétrons de valência e tende a formar o cátion Mg^2+. O cloro (Cl, família 17) possui 7 elétrons e tende a formar o ânion Cl^-. Pela neutralidade elétrica das cargas, a fórmula mínima do cloreto de magnésio é:", "alternativas": {"A": "MgCl.", "B": "MgCl2.", "C": "Mg2Cl.", "D": "Mg2Cl3.", "E": "Mg7Cl2."}, "resposta_correta": "B", "justificativa": "Para que a soma algébrica das cargas elétricas seja nula no composto iônico neutro: 1 íon Mg^2+ (+2) requer 2 íons Cl^- (-1 cada, totalizando -2), resultando na proporção estequiométrica MgCl2.", "possui_imagem": true},
  {"id": 11, "uid": "CIEN-9-011", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Eletronegatividade na Tabela Periódica", "dificuldade": "Fácil", "enunciado": "A eletronegatividade é a tendência que um átomo possui de atrair para si o par de elétrons compartilhado em uma ligação química. O elemento químico mais eletronegativo de toda a Tabela Periódica é o:", "alternativas": {"A": "Sódio (Na).", "B": "Frâncio (Fr).", "C": "Flúor (F).", "D": "Ferro (Fe).", "E": "Hélio (He)."}, "resposta_correta": "C", "justificativa": "O flúor (F), localizado no canto superior direito da Tabela Periódica (grupo 17, período 2), possui o menor raio atômico entre os elementos ávidos por elétrons e a mais alta eletronegatividade na escala de Pauling (3,98).", "possui_imagem": true},
  {"id": 12, "uid": "CIEN-9-012", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Gases Nobres e Inércia Química", "dificuldade": "Fácil", "enunciado": "Elementos como hélio (He), neônio (Ne) e argônio (Ar) são chamados de gases nobres e raramente formam ligações químicas na natureza com outros átomos. Essa inércia química decorre do fato de que:", "alternativas": {"A": "Eles não possuem prótons em seus núcleos atômicos.", "B": "Já possuem a camada de valência completamente preenchida e estável (octeto completo ou dupleto no hélio).", "C": "São substâncias exclusivamente radioativas artificiais.", "D": "Estão sempre na temperatura do zero absoluto no vácuo.", "E": "Não são matéria e não possuem massa mensurável."}, "resposta_correta": "B", "justificativa": "Gases nobres possuem camadas eletrônicas externas saturadas (s2p6 no octeto ou 1s2 no dupleto do hélio), apresentando elevadíssima energia de ionização e afinidade eletrônica praticamente nula, conferindo grande estabilidade monoatômica espontânea.", "possui_imagem": false},
  {"id": 13, "uid": "CIEN-9-013", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligas Metálicas no Cotidiano", "dificuldade": "Fácil", "enunciado": "O aço comum utilizado na construção civil e o bronze de medalhas esportivas não são elementos químicos puros, mas sim misturas homogêneas sólidas formadas principalmente por metais, conhecidas como:", "alternativas": {"A": "Compostos iônicos moleculares.", "B": "Ligas metálicas.", "C": "Ácidos inorgânicos concentrados.", "D": "Bases hidróxidas solúveis.", "E": "Sais minerais neutros."}, "resposta_correta": "B", "justificativa": "Ligas metálicas são materiais formados pela união de dois ou mais metais (ou metais com ametais, como o ferro com carbono no aço), unidas por ligações metálicas e desenvolvidas para otimizar propriedades mecânicas e resistência à corrosão.", "possui_imagem": false},
  {"id": 14, "uid": "CIEN-9-014", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Fórmula Estrutural de Lewis da Água", "dificuldade": "Fácil", "enunciado": "Na representação por fórmula eletrônica de Lewis para a molécula de água (H2O), os elétrons de valência são indicados por pontos ao redor dos símbolos dos elementos. Ao redor do átomo central de oxigênio na água encontram-se:", "alternativas": {"A": "Apenas dois elétrons sem nenhuma ligação.", "B": "Dois pares de elétrons compartilhados com os hidrogênios e dois pares de elétrons livres (não ligantes).", "C": "Cem elétrons em rotação atômica contínua.", "D": "Zero elétrons livres na camada externa.", "E": "Oito prótons desprendidos no citoplasma."}, "resposta_correta": "B", "justificativa": "O oxigênio (Z=8) possui 6 elétrons na camada de valência: utiliza 2 elétrons para formar duas ligações covalentes simples com dois átomos de hidrogênio (2 pares ligantes) e conserva 4 elétrons livres organizados em 2 pares não ligantes (geometria angular).", "possui_imagem": true},
  {"id": 15, "uid": "CIEN-9-015", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Substância Simples vs. Composta", "dificuldade": "Fácil", "enunciado": "A molécula de gás oxigênio (O2) e a molécula de dióxido de carbono (CO2) são classificadas, respectivamente, como:", "alternativas": {"A": "Substância composta e substância simples.", "B": "Substância simples (formada por átomos de um único elemento) e substância composta (formada por átomos de elementos químicos diferentes).", "C": "Ambas são substâncias simples puras.", "D": "Ambas são misturas heterogêneas de minerais.", "E": "Composto iônico e composto metálico puro."}, "resposta_correta": "B", "justificativa": "Substâncias simples são constituídas por átomos de um único elemento químico (como O2, N2, Fe); substâncias compostas contêm átomos de dois ou mais elementos químicos distintos combinados em proporções fixas (como CO2, H2O, NaCl).", "possui_imagem": false},
  {"id": 16, "uid": "CIEN-9-016", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Cátions e Ânions: Definição", "dificuldade": "Fácil", "enunciado": "Um átomo neutro que perde um ou mais elétrons passa a ter excesso de cargas positivas e é chamado de cátion. Já um átomo neutro que ganha elétrons passa a ter excesso de cargas negativas e é chamado de:", "alternativas": {"A": "Próton livre.", "B": "Ânion.", "C": "Molécula covalente.", "D": "Nêutron excitado.", "E": "Gás nobre denso."}, "resposta_correta": "B", "justificativa": "Íons são espécies químicas com carga elétrica líquida: cátions possuem carga positiva resultante da perda de elétrons (ex: Na+, Ca2+); ânions possuem carga negativa resultante do ganho de elétrons (ex: Cl-, O2-).", "possui_imagem": false},
  {"id": 17, "uid": "CIEN-9-017", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Pontos de Fusão e Ebulição: Comparação", "dificuldade": "Fácil", "enunciado": "Ao comparar o cloreto de sódio (composto iônico) com a água e o álcool etílico (compostos moleculares covalentes), constata-se que o ponto de fusão do cloreto de sódio é de cerca de 801 ºC, enquanto o da água é 0 ºC. Essa disparidade expressiva de temperatura deve-se a:", "alternativas": {"A": "O cloreto de sódio ser mais pesado que a água líquida.", "B": "As forças de atração eletrostática entre íons no retículo iônico serem imensamente mais fortes do que as forças intermoleculares que unem moléculas vizinhas em substâncias covalentes.", "C": "A água ter sido criada sem ligações químicas internas.", "D": "O sal de cozinha absorver radiação nuclear do ambiente.", "E": "As moléculas de água serem feitas de ferro derretido."}, "resposta_correta": "B", "justificativa": "Para fundir um composto iônico, é necessário romper as poderosíssimas ligações iônicas intramoleculares em rede do retículo cristalino; para fundir a água molecular, rompem-se apenas atrações intermoleculares (ligações de hidrogênio), mantendo as moléculas de H2O intactas.", "possui_imagem": false},
  {"id": 18, "uid": "CIEN-9-018", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Polaridade das Ligações Covalentes: Apolar vs. Polar", "dificuldade": "Médio", "enunciado": "Na molécula de gás hidrogênio (H2), os dois átomos possuem eletronegatividades idênticas e atraem os elétrons com a mesma força, formando uma ligação covalente apolar. Já na molécula de cloreto de hidrogênio (HCl), a ligação é covalente polar porque:", "alternativas": {"A": "O hidrogênio perde seu elétron e vira metal puro.", "B": "O cloro é muito mais eletronegativo que o hidrogênio, atraindo com maior força o par de elétrons compartilhado e gerando uma densidade de carga negativa parcial (δ-) sobre o cloro e positiva (δ+) sobre o hidrogênio.", "C": "O hidrogênio e o cloro explodem quando se tocam.", "D": "A ligação se transforma em ligação metálica de cobre.", "E": "O cloro doa seus prótons para o oxigênio do ar."}, "resposta_correta": "B", "justificativa": "A diferença de eletronegatividade entre átomos ligados covalentemente gera distribuição assimétrica da densidade da nuvem eletrônica compartilhada, estabelecendo um momento dipolar elétrico permanente (polo positivo δ+ no H e polo negativo δ- no Cl).", "possui_imagem": false},
  {"id": 19, "uid": "CIEN-9-019", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Geometria Molecular: Linear, Angular e Tetraédrica", "dificuldade": "Médio", "enunciado": "De acordo com a Teoria da Repulsão dos Pares Eletrônicos da Camada de Valência (VSEPR), os pares de elétrons ao redor do átomo central repelem-se mutuamente no espaço. As moléculas de dióxido de carbono (CO2) e de água (H2O) possuem, respectivamente, geometrias espaciais:", "alternativas": {"A": "Ambas são rigorosamente esféricas tridimensionais.", "B": "Linear (pois o carbono central não tem pares de elétrons livres) e Angular (pois o oxigênio central possui dois pares de elétrons livres que empurram as ligações O-H para baixo).", "C": "Tetraédrica e piramidal trigonal plana.", "D": "Cúbica e cilíndrica oca.", "E": "Plana triangular sem ângulos definidos."}, "resposta_correta": "B", "justificativa": "No CO2 (O=C=O), há duas nuvens eletrônicas e nenhum par livre no carbono, resultando em geometria linear (ângulo de 180º). Na H2O, há quatro nuvens (duas ligações e dois pares livres no oxigênio); a repulsão dos pares isolados deforma o arranjo tetraédrico para geometria angular (ângulo de ~104,5º).", "possui_imagem": false},
  {"id": 20, "uid": "CIEN-9-020", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Forças Intermoleculares: Ligações de Hidrogênio", "dificuldade": "Médio", "enunciado": "A água (H2O) possui ponto de ebulição surpreendentemente alto (100 ºC ao nível do mar) quando comparada a moléculas de massa molar semelhante como o gás metano (CH4, que ferve a -161 ºC). O fator intermolecular responsável por manter as moléculas de água fortemente unidas no estado líquido é:", "alternativas": {"A": "A presença de ligações metálicas entre o hidrogênio e o oxigênio.", "B": "A ocorrência de intensas Ligações de Hidrogênio (pontes de hidrogênio), uma atração intermolecular forte que ocorre quando átomos de hidrogênio ligados covalentemente a átomos pequenos e muito eletronegativos (F, O, N) atraem os pares livres de moléculas vizinhas.", "C": "A queima contínua de oxigênio dentro do copo de água.", "D": "A atração gravitacional provocada pelo peso da água líquida.", "E": "A ausência total de elétrons nas moléculas de água potável."}, "resposta_correta": "B", "justificativa": "Ligações de hidrogênio são interações dipolo-dipolo de excepcional intensidade que ocorrem quando H está covalentemente ligado a elementos de alta eletronegatividade e pequeno raio (F, O, N). Essa rede de pontes na água exige considerável energia térmica para separação molecular na vaporização.", "possui_imagem": false},
  {"id": 21, "uid": "CIEN-9-021", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Retículo Cristalino e Fragilidade dos Cristais Iônicos", "dificuldade": "Médio", "enunciado": "Embora um cristal de sal de cozinha (NaCl) seja muito duro e resista a riscos, se ele for golpeado com um martelo ele se quebra e esfarela em pequenas fatias planas cúbicas (comportamento quebradiço). Essa quebra mecânica dos compostos iônicos é explicada pelo fato de que:", "alternativas": {"A": "O martelo queima os átomos de sódio com calor instantâneo.", "B": "A força mecânica do golpe desloca as camadas de íons no retículo cristalino; com o deslocamento, íons de mesma carga (+ com + ou - com -) passam a ficar alinhados lado a lado, gerando forças violentas de repulsão eletrostática que partem o cristal ao longo de planos de clivagem.", "C": "O sal de cozinha é oco por dentro e contém gás carbônico comprimido.", "D": "Os elétrons do martelo são atraídos pelo ar da sala.", "E": "O cloreto de sódio evapora espontaneamente quando tocado por metal."}, "resposta_correta": "B", "justificativa": "A distorção mecânica do retículo iônico move planos de íons por apenas uma distância interatômica; ao alinhar cargas de mesmo sinal em posições adjacentes, a atração converte-se em violenta repulsão coulômbica ao longo do plano, fraturando o cristal em planos de clivagem lisos.", "possui_imagem": false},
  {"id": 22, "uid": "CIEN-9-022", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Condutividade Térmica e Elétrica dos Metais", "dificuldade": "Médio", "enunciado": "Os metais são amplamente empregados como panelas de cozimento e condutores em fiações elétricas devido à sua excepcional capacidade de conduzir calor e eletricidade. No nível microscópico da ligação metálica, a condução de calor e eletricidade é realizada com facilidade porque:", "alternativas": {"A": "Os elétrons livres deslocalizados possuem alta mobilidade na rede cristalina, transportando rapidamente energia cinética térmica por choques e corrente elétrica quando submetidos a uma diferença de potencial.", "B": "Os metais produzem novas moléculas de água quando são aquecidos.", "C": "Os prótons dos núcleos atômicos se movem livremente pelo fio elétrico.", "D": "As panelas absorvem luz solar diretamente do teto da cozinha.", "E": "Os átomos de ferro se quebram em pequenas baterias químicas."}, "resposta_correta": "A", "justificativa": "O gás de elétrons livres (mar de elétrons) do modelo de Drude-Lorentz move-se com altíssima velocidade e liberdade entre os sítios da rede catiônica; quando há gradiente térmico ou ddp externa, os elétrons livres transportam momento e energia cinética com resistência mínima.", "possui_imagem": false},
  {"id": 23, "uid": "CIEN-9-023", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Fórmula de Lewis do Gás Carbônico (CO2)", "dificuldade": "Médio", "enunciado": "O carbono (família 14) possui 4 elétrons na camada de valência e o oxigênio (família 16) possui 6 elétrons. Para que todos os átomos atinjam a estabilidade com 8 elétrons segundo a Regra do Octeto, a molécula de dióxido de carbono (CO2) estabelece:", "alternativas": {"A": "Duas ligações simples entre o carbono e cada oxigênio.", "B": "Duas ligações covalentes duplas (O = C = O), de modo que o átomo central de carbono compartilha dois pares de elétrons com cada átomo de oxigênio.", "C": "Uma ligação tripla com um oxigênio e uma iônica com o outro.", "D": "Uma transferência definitiva de quatro elétrons para cada oxigênio.", "E": "Uma ligação metálica pura sem elétrons compartilhados."}, "resposta_correta": "B", "justificativa": "Para atingir o octeto: o C necessita de 4 elétrons e cada O necessita de 2 elétrons. O átomo central de carbono compartilha dois pares de elétrons com cada oxigênio, formando duas ligações covalentes duplas estáveis (O=C=O) com geometria linear e octetos completos.", "possui_imagem": false},
  {"id": 24, "uid": "CIEN-9-024", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Substâncias Covalentes Moleculares vs. Covalentes Covalentes de Rede (Covalentes Atômicas)", "dificuldade": "Médio", "enunciado": "O diamante e o gelo seco (CO2 sólido) são substâncias formadas por ligações covalentes. No entanto, enquanto o gelo seco sublima a -78 ºC com facilidade, o diamante é o material natural mais duro conhecido e funde a mais de 3.500 ºC. Essa diferença monumental de propriedades ocorre porque:", "alternativas": {"A": "O diamante é um metal nobre condutor e o gelo seco é um ácido mineral.", "B": "O gelo seco é uma substância molecular (onde moléculas isoladas de CO2 são unidas apenas por fracas forças de dispersão), enquanto o diamante é um sólido covalente de rede (cristal gigante tridimensional onde todos os átomos de carbono são unidos entre si por fortíssimas ligações covalentes contínuas).", "C": "O diamante foi fabricado em laboratório sem átomos de carbono.", "D": "O gelo seco é composto exclusivamente de oxigênio líquido.", "E": "O diamante derrete se for colocado dentro de água fria."}, "resposta_correta": "B", "justificativa": "Sólidos moleculares (como CO2 ou sacarose) fundem com facilidade porque apenas forças intermoleculares fracas são rompidas. Em sólidos covalentes atômicos em rede (como diamante, grafite e quartzo SiO2), a fusão requer a quebra de infinitas ligações covalentes intramoleculares primárias de altíssima energia.", "possui_imagem": false},
  {"id": 25, "uid": "CIEN-9-025", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Alotropia do Carbono: Grafite vs. Diamante", "dificuldade": "Médio", "enunciado": "O grafite (usado na ponta de lápis) e o diamante são substâncias simples formadas unicamente pelo mesmo elemento químico: o carbono (fenômeno da alotropia). O grafite é macio, quebradiço e conduz eletricidade, enquanto o diamante é extremamente duro e isolante elétrico. Essas propriedades tão distintas decorrem de:", "alternativas": {"A": "O grafite conter ferro misturado e o diamante conter ouro puro.", "B": "Diferentes arranjos espaciais e hibridizações dos átomos de carbono: no diamante os carbonos formam uma rede tetraédrica tridimensional rígida com todas as ligações fixadas; no grafite os carbonos formam lâminas hexagonais planas paralelas unidas por forças fracas, com elétrons pi deslocalizados livres para conduzir corrente.", "C": "O diamante ser um composto iônico e o grafite ser um metal puro.", "D": "O grafite ser formado por bactérias vivas e o diamante por minerais marinhos.", "E": "O diamante perder todos os seus elétrons quando entra em contato com o ar."}, "resposta_correta": "B", "justificativa": "A alotropia do carbono expressa como geometrias reticulares geram propriedades díspares: no diamante (hibridização sp3), cada C liga-se tetraedricamente a quatro C em rede 3D tridimensional indeformável; no grafite (sp2), anéis hexagonais formam planos esfoliáveis com elétrons pi livres que conferem condutividade elétrica.", "possui_imagem": false},
  {"id": 26, "uid": "CIEN-9-026", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Solubilidade: Regra do 'Semelhante Dissolve Semelhante'", "dificuldade": "Médio", "enunciado": "Ao tentar limpar uma mancha de óleo de cozinha ou graxa das mãos, a água pura não consegue remover a sujeira, mas a aplicação de solventes orgânicos ou detergentes remove a graxa com facilidade. Esse comportamento é explicado pelo princípio químico da solubilidade que dita que:", "alternativas": {"A": "Todos os líquidos se misturam com qualquer substância sólida.", "B": "'Semelhante dissolve semelhante': a água é uma substância altamente polar e dissolve preferencialmente solutos polares e iônicos, enquanto óleos e gorduras são substâncias apolares que se dissolvem em solventes apolares.", "C": "A água congela o óleo tornando-o impossível de dissolver.", "D": "A graxa é um ácido forte que destrói as moléculas de água.", "E": "Solutos pesados só se dissolvem na presença de ar quente."}, "resposta_correta": "B", "justificativa": "Interações soluto-solvente ditam a miscibilidade termodinâmica: substâncias polares interagem favoravelmente com solutos polares e iônicos por solvatação e dipolo-dipolo; substâncias hidrofóbicas apolares (lipídios/hidrocarbonetos) interagem entre si por forças de dispersão de London, repelindo a rede de pontes de hidrogênio da água.", "possui_imagem": false},
  {"id": 27, "uid": "CIEN-9-027", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ação dos Tensoativos (Detergentes e Sabões)", "dificuldade": "Médio", "enunciado": "Como vimos, a água (polar) e o óleo (apolar) são imiscíveis. Ao adicionar detergente ou sabão a essa mistura e agitar, forma-se uma emulsão estável que permite a remoção da gordura pela água. A molécula de sabão consegue realizar essa proeza porque possui estrutura anfifílica (anfipática), que consiste em:", "alternativas": {"A": "Dois átomos de ouro que quebram as moléculas de gordura.", "B": "Uma longa cauda apolar hidrofóbica (que interage com as gorduras) e uma cabeça polar hidrofílica (que interage fortemente com as moléculas de água), formando micelas esféricas que aprisionam as gotículas de óleo em seu interior.", "C": "Apenas cargas elétricas positivas que evaporam com o vapor d'água.", "D": "Ácido clorídrico concentrado que queima a gordura em frações de segundo.", "E": "Uma carapaça sólida de calcário que esmaga os lipídios."}, "resposta_correta": "B", "justificativa": "Moléculas tensoativas são anfifílicas: a cadeia hidrocarbônica apolar lipofílica interage com a gota de óleo e as extremidades polares ionizadas hidrofílicas (carboxilatos/sulfonatos) voltam-se para a água circundante, organizando micelas coloidais estáveis carreadas pelo fluxo de lavagem.", "possui_imagem": false},
  {"id": 28, "uid": "CIEN-9-028", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligação de Coordenação (Covalente Dativa)", "dificuldade": "Médio", "enunciado": "Em certas moléculas e íons poliatômicos (como no gás monóxido de carbono CO ou no cátion amônio NH4+), ocorre uma ligação covalente de coordenação (antigamente chamada de dativa). Esse tipo especial de ligação covalente caracteriza-se por:", "alternativas": {"A": "A perda definitiva de um elétron para o vácuo.", "B": "O par de elétrons compartilhado ser fornecido integralmente por um único átomo da ligação (que possui par de elétrons livre), enquanto o outro átomo que recebe o compartilhamento apenas entra com o orbital vazio para se estabilizar.", "C": "A fusão de dois núcleos atômicos em um único elemento químico.", "D": "A quebra espontânea da molécula em menos de um milissegundo.", "E": "Uma ligação que ocorre exclusivamente entre metais nobres no espaço."}, "resposta_correta": "B", "justificativa": "Na ligação covalente coordenada, a natureza mecanoquímica da ligação é idêntica a uma ligação covalente comum (compartilhamento de par eletrônico), mas a origem dos elétrons difere: ambos os elétrons do par ligante provêm do par isolado do átomo doador para o orbital aceptor vazio do ligante.", "possui_imagem": false},
  {"id": 29, "uid": "CIEN-9-029", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Propriedades Térmicas e Densidade da Água no Congelamento", "dificuldade": "Médio", "enunciado": "Na maioria das substâncias químicas, o sólido é mais denso que o líquido e afunda quando colocado em seu próprio líquido fundido. A água apresenta um comportamento anômalo: o gelo flutua na água líquida. Esse fenômeno é explicado pela geometria molecular e pelas ligações de hidrogênio da água porque:", "alternativas": {"A": "O gelo é mais leve porque absorve bolhas de hélio do ar ao congelar.", "B": "Ao solidificar abaixo de 4 ºC, as ligações de hidrogênio fixam as moléculas de H2O em uma rede cristalina hexagonal aberta e espaçosa com grandes vazios internos, aumentando o volume e tornando a densidade do gelo menor que a da água líquida desordenada.", "C": "O gelo perde metade de seus átomos de hidrogênio quando congela.", "D": "A água líquida empurra o gelo para cima por atração magnética pura.", "E": "As moléculas de gelo transformam-se em vapor sob a superfície."}, "resposta_correta": "B", "justificativa": "O comportamento anômalo da água atinge densidade máxima a 3,98 ºC. No congelamento a 0 ºC, a maximização de 4 pontes de hidrogênio por molécula impõe um retículo cristalino hexagonal rígido com cavidades abertas, expandindo o volume em ~9% e tornando o gelo menos denso que a água líquida (~0,92 g/cm³ vs 1,00 g/cm³), viabilizando a vida aquática sob lagos congelados.", "possui_imagem": false},
  {"id": 30, "uid": "CIEN-9-030", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ligas com Memória de Forma (Nitinol)", "dificuldade": "Médio", "enunciado": "Na engenharia de materiais de ponta e na medicina (stents cardíacos e fios ortodônticos), utilizam-se ligas metálicas com 'memória de forma', como o Nitinol (liga de níquel e titânio). Quando um fio de Nitinol dobrado e deformado é ligeiramente aquecido com água morna, ele retorna espontaneamente à sua forma original projetada. Essa propriedade mecânica decorre de:", "alternativas": {"A": "Reações nucleares que fundem o níquel em chumbo.", "B": "Uma transformação de fase cristalina reversível no estado sólido entre duas estruturas cristalinas distintas (fase martensita em baixa temperatura e fase austenita em alta temperatura) sem que haja quebra de ligações químicas metálicas permanentes.", "C": "A combustão controlada de oxigênio dentro do metal.", "D": "A evaporação de água contida no interior da liga metálica.", "E": "A atração gravitacional do chão sobre os átomos de titânio."}, "resposta_correta": "B", "justificativa": "O efeito de memória de forma (Shape Memory Effect) do Nitinol baseia-se na transição de fase displaciva termoelástica no estado sólido entre a fase martensítica deformável por maclação em baixa temperatura e a fase austenítica de simetria cúbica altamente ordenada quando aquecida acima da temperatura de transição Af.", "possui_imagem": false},
  {"id": 31, "uid": "CIEN-9-031", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Raio Atômico e Energia de Ionização ao Longo da Tabela", "dificuldade": "Médio", "enunciado": "Ao analisar a Tabela Periódica, constata-se que o raio atômico e a primeira energia de ionização variam em sentidos opostos ao longo de um mesmo período (linha horizontal). À medida que caminhamos da esquerda para a direita em um período:", "alternativas": {"A": "O raio atômico cresce e a energia de ionização cai para zero.", "B": "O número atômico aumenta, elevando a carga nuclear efetiva (mais prótons atraindo os mesmos níveis eletrônicos), o que reduz o raio atômico e aumenta fortemente a energia de ionização necessária para remover um elétron de valência.", "C": "O número de camadas eletrônicas dobra a cada elemento vizinho.", "D": "Todos os átomos se transformam em metais nobres pesados.", "E": "A gravidade atômica do núcleo desaparece progressivamente."}, "resposta_correta": "B", "justificativa": "Ao longo de um período, elétrons sucessivos são adicionados à mesma camada principal (blindagem eletrônica quase constante), enquanto a carga nuclear Z cresce continuamente; a maior atração coulombiana nuclear contrai a nuvem eletrônica (menor raio) e aprisiona os elétrons mais fortemente (maior energia de ionização).", "possui_imagem": false},
  {"id": 32, "uid": "CIEN-9-032", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Eletrólise Ígnea vs. Aquosa", "dificuldade": "Médio", "enunciado": "Na obtenção industrial de metais alcalinos puros como o sódio metálico (Na), realiza-se a eletrólise do cloreto de sódio. No entanto, é obrigatório realizar a eletrólise com o sal fundido a mais de 800 ºC (eletrólise ígnea) e nunca em solução aquosa de salmoura. A razão química para essa exigência é:", "alternativas": {"A": "O cloreto de sódio não se dissolver em água em nenhuma temperatura.", "B": "Na eletrólise aquosa, os íons H+ provenientes da autoionização da água possuem maior facilidade de descarga do que os íons Na+, de modo que descarregaria gás hidrogênio (H2) no cátodo em vez de produzir sódio metálico.", "C": "A água pura queimar os eletrodos de platina da cuba eletrolítica.", "D": "O sal fundido custar cem vezes mais barato que a água de torneira.", "E": "A eletrólise aquosa só funcionar com corrente elétrica alternada."}, "resposta_correta": "B", "justificativa": "Em solução aquosa, há competição catódica entre cátions: como a ddp de redução do H+ (2 H+ + 2e- -> H2, Eº = 0,00 V) é muito mais favorável que a do sódio (Na+ + e- -> Na, Eº = -2,71 V), a água reduz preferencialmente produzindo H2 gasoso. A obtenção de sódio metálico zero exige meio anidro de sal fundido (eletrólise ígnea).", "possui_imagem": false},
  {"id": 33, "uid": "CIEN-9-033", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Diferença entre Substâncias Iônicas, Covalentes e Metálicas em Teste Cego", "dificuldade": "Médio", "enunciado": "Um químico recebe três substâncias sólidas desconhecidas (X, Y e Z) e realiza testes laboratoriais de fusão e condutividade elétrica:\n- Substância X: ponto de fusão = 80 ºC; não conduz eletricidade no estado sólido nem dissolvida em água.\n- Substância Y: ponto de fusão = 1.085 ºC; conduz eletricidade com facilidade tanto no estado sólido quanto no estado líquido fundido.\n- Substância Z: ponto de fusão = 770 ºC; não conduz eletricidade no sólido, mas conduz perfeitamente quando dissolvida em água.\nAs substâncias X, Y e Z são classificadas, respectivamente, como:", "alternativas": {"A": "Metálica, iônica e covalente molecular.", "B": "Covalente molecular, metálica e iônica.", "C": "Iônica, covalente molecular e metálica.", "D": "Todas são compostos iônicos de diferentes famílias.", "E": "Todas são ligas metálicas com impurezas."}, "resposta_correta": "B", "justificativa": "A substância X tem baixo ponto de fusão e é isolante em qualquer estado (composto covalente molecular); Y tem alto ponto de fusão e conduz no estado sólido (metal puro); Z tem alto ponto de fusão e só conduz em solução aquosa (composto iônico clássico).", "possui_imagem": false},
  {"id": 34, "uid": "CIEN-9-034", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Grafeno: O Material do Futuro", "dificuldade": "Médio", "enunciado": "O grafeno consiste em uma única folha bidimensional de espessura atômica formada por átomos de carbono organizados em anéis hexagonais perfeitos. Descoberto em 2004 (rendendo o Nobel de Física de 2010), o grafeno é cerca de 200 vezes mais resistente que o aço estrutural e conduz eletricidade melhor que o cobre. Essas propriedades mecânicas e elétricas excepcionais decorrem de:", "alternativas": {"A": "Ser composto por ferro fundido em aceleradores nucleares.", "B": "As fortes ligações covalentes sp2 no plano bidimensional formarem uma malha hexagonal contínua sem defeitos com altíssima energia de ligação, associada a elétrons pi deslocalizados que se movem como partículas relativísticas livres (sem massa efetiva) com mobilidade recorde.", "C": "Ser um composto iônico que atrai elétrons por gravidade magnética.", "D": "Ser feito inteiramente de plástico reciclado biodegradável.", "E": "Funcionar apenas quando mergulhado em nitrogênio líquido."}, "resposta_correta": "B", "justificativa": "O retículo cristalino hexagonal em favo de mel do grafeno possui ligações sigma sp2 C-C extremamente robustas (módulo de Young de 1 TPa e resistência à tração de 130 GPa), enquanto os orbitais pz desemparelhados formam bandas de condução e valência que se tocam nos pontos de Dirac, propiciando condução balística de férmions de Dirac sem massa.", "possui_imagem": false},
  {"id": 35, "uid": "CIEN-9-035", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Energia de Rede Cristalina e Ciclo de Born-Haber", "dificuldade": "Difícil", "enunciado": "A estabilidade de um composto iônico não é determinada apenas pela atração de um par isolado cátion-ânion, mas pela chamada 'Energia Reticular' (Energia de Rede Cristalina) liberada quando íons gasosos se agrupam formando o sólido cristalino tridimensional. Pela Lei de Coulomb, a energia de rede de um cristal iônico é tanto maior quanto:", "alternativas": {"A": "Maior for a massa atômica de nêutrons no núcleo dos elementos.", "B": "Maiores forem as cargas dos íons (ex: íons divalentes como Mg^2+ e O^2- geram atração muito maior que Na+ e Cl-) e menores forem os raios iônicos (menor distância internuclear entre os centros dos íons no retículo).", "C": "Mais frio for o ambiente onde o mineral foi extraído.", "D": "Mais elétrons livres o composto tiver circulando no cristal.", "E": "Menor for o número de átomos de oxigênio ao redor da amostra."}, "resposta_correta": "B", "justificativa": "Pela Equação de Born-Landé e de Kapustinskii, a energia reticular (U) é diretamente proporcional ao produto dos módulos das cargas dos íons (|z+ . z-|) e inversamente proporcional à soma dos raios iônicos (r+ + r-). O MgO (|z+ . z-| = 4) possui energia reticular quase quatro vezes superior à do NaCl (|z+ . z-| = 1), explicando seu ponto de fusão colossal de ~2.852 ºC contra 801 ºC do NaCl.", "possui_imagem": false},
  {"id": 36, "uid": "CIEN-9-036", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Caráter Parcialmente Covalente em Ligações Iônicas: Regras de Fajans", "dificuldade": "Difícil", "enunciado": "Em química inorgânica, nenhuma ligação química entre elementos diferentes é 100% iônica pura; muitas ligações iônicas exibem acentuado 'caráter covalente' secundário. De acordo com as Regras de Fajans, uma ligação iônica apresentará elevado caráter covalente quando:", "alternativas": {"A": "O cátion for muito grande com carga +1 e o ânion for muito pequeno.", "B": "O cátion for pequeno e com alta densidade de carga positiva (alto poder polarizante) e o ânion for volumoso e facilmente deformável (alta polarizabilidade), permitindo que a nuvem eletrônica do ânion seja distorcida e atraída para o espaço internuclear.", "C": "Os dois elementos forem gases nobres que não possuem elétrons de valência.", "D": "A temperatura do cristal for mantida no zero absoluto.", "E": "A ligação ocorrer na presença de água oxigenada pura."}, "resposta_correta": "B", "justificativa": "As Regras de Fajans predizem a transição de ligação iônica pura para covalente polarizada por polarização reticular: cátions pequenos de alta carga (como Al3+, Li+) exercem forte campo eletrostático que distorce a nuvem eletrônica frouxa de ânions volumosos polarizáveis (como I-, S2-), compartilhando elétrons parcialmente e reduzindo pontos de fusão.", "possui_imagem": false},
  {"id": 37, "uid": "CIEN-9-037", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Dipolos Induzidos e Forças de Dispersão de London", "dificuldade": "Difícil", "enunciado": "Moléculas apolares como o gás hélio (He), o gás oxigênio (O2) e o tetracloreto de carbono (CCl4) não possuem polos elétricos permanentes. No entanto, sob temperaturas suficientemente baixas, elas conseguem se liquefazer e se solidificar. A atração intermolecular que mantém moléculas apolares unidas no estado condensado é a força de:", "alternativas": {"A": "Ponte de hidrogênio de alta energia.", "B": "Dispersão de London (dipolo induzido - dipolo instantâneo), originada por flutuações quânticas momentâneas e assimétricas na distribuição de elétrons na eletrosfera que criam dipolos transitórios que induzem dipolos elétricos em moléculas vizinhas.", "C": "Ligação iônica pura por troca de nêutrons.", "D": "Ligação metálica por mar de elétrons deslocalizados.", "E": "Atração magnética de polos norte e sul da Terra."}, "resposta_correta": "B", "justificativa": "Em moléculas apolares, a densidade de probabilidade eletrônica é simétrica na média temporal, mas flutuações estatísticas instantâneas geram momentos dipolares transitórios fugazes (dipolo instantâneo). Esse microcampo polariza as nuvens vizinhas (dipolo induzido), gerando atração eletrostática atrativa dispersiva de London (proporcional à polarizabilidade e à massa molar).", "possui_imagem": false},
  {"id": 38, "uid": "CIEN-9-038", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Exceções à Regra do Octeto: Octeto Expandido e Contraído", "dificuldade": "Difícil", "enunciado": "Embora a Regra do Octeto funcione perfeitamente para elementos do segundo período (C, N, O, F), ela sofre exceções notáveis em elementos do terceiro período em diante. Na molécula de trifluoreto de boro (BF3) e na molécula de hexafluoreto de enxofre (SF6), os átomos centrais de boro e enxofre apresentam, respectivamente:", "alternativas": {"A": "Octeto completo com 8 elétrons em ambos os casos.", "B": "Octeto contraído com apenas 6 elétrons de valência no boro e octeto expandido com 12 elétrons de valência no enxofre (que utiliza orbitais d disponíveis da terceira camada para acomodar mais de quatro pares ligantes).", "C": "100 elétrons em ambos os átomos centrais.", "D": "Ausência total de ligações covalentes nos dois compostos.", "E": "Ligações metálicas que transformam o gás em ouro."}, "resposta_correta": "B", "justificativa": "O boro no BF3 estabiliza-se como deficiente de elétrons com sexteto incompleto (3 pares ligantes = 6 elétrons, forte ácido de Lewis). O enxofre no SF6 pertence ao terceiro período (possui orbitais 3d energeticamente acessíveis), promovendo hipervalência ou octeto expandido com 6 pares ligantes (12 elétrons) e geometria octaédrica regular.", "possui_imagem": false},
  {"id": 39, "uid": "CIEN-9-039", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Teoria dos Orbitais Moleculares (TOM) e o Paramagnetismo do O2", "dificuldade": "Difícil", "enunciado": "A fórmula clássica de Lewis para o oxigênio molecular (:O=O:) prevê que todos os seus elétrons estão emparelhados em pares (comportamento diamagnético). No entanto, experimentos laboratoriais com oxigênio líquido demonstram que ele é azul e é fortemente atraído pelos polos de um ímã (comportamento paramagnético). A Teoria dos Orbitais Moleculares (TOM) explica com sucesso o paramagnetismo do O2 demonstrando que:", "alternativas": {"A": "A molécula de oxigênio contém ferro metálico dissolvido no núcleo.", "B": "No diagrama de orbitais moleculares, os dois últimos elétrons de valência ocupam separadamente dois orbitais moleculares antiligantes degenerados diferentes (π* 2px e π* 2py) com spins paralelos desemparelhados segundo a Regra de Hund, gerando momento magnético permanente de spin.", "C": "O oxigênio líquido sofre combustão espontânea com o ímã.", "D": "O oxigênio não é uma substância covalente, mas sim um metal condutor.", "E": "A atração pelo ímã ocorre apenas na presença de gravidade zero."}, "resposta_correta": "B", "justificativa": "A limitação da teoria de Lewis foi superada pela TOM: a configuração eletrônica molecular fundamental do O2 é σ1s² σ*1s² σ2s² σ*2s² σ2pz² π2px² π2py² π*2px¹ π*2py¹. A presença de dois elétrons desemparelhados com spins paralelos nos orbitais antiligantes π* comprova o paramagnetismo observado experimentalmente.", "possui_imagem": false},
  {"id": 40, "uid": "CIEN-9-040", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Resistividade e Coeficiente Térmico nos Metais vs. Semicondutores", "dificuldade": "Difícil", "enunciado": "Quando a temperatura de uma barra de cobre metálico aumenta de 20 ºC para 100 ºC, sua resistência elétrica AUMENTA. Em contraste, quando a temperatura de um cristal de silício semicondutor de alta pureza aumenta na mesma faixa, sua resistência elétrica DIMINUI consideravelmente. A justificativa microscópica para esse comportamento oposto é:", "alternativas": {"A": "O cobre enferruja no calor e o silício se transforma em prata.", "B": "Nos metais condutores o aquecimento intensifica a agitação térmica dos cátions da rede, aumentando a frequência de colisões inelásticas com os elétrons livres (menor tempo de livre percurso médio); nos semicondutores térmicos, a energia térmica promove elétrons da banda de valência para a banda de condução vencendo o gap de energia (bandgap), gerando milhões de novos portadores de carga livres (elétrons e lacunas) que superam o efeito de espalhamento.", "C": "O silício perde todos os seus prótons quando é aquecido.", "D": "O cobre perde seus elétrons de valência para o ar da sala.", "E": "Ambos os materiais comportam-se da mesma forma sem diferença física."}, "resposta_correta": "B", "justificativa": "Em metais condutores (com densidade de portadores n fixa e altíssima), a resistividade aumenta com a temperatura devido ao espalhamento elétron-fônon (coeficiente de temperatura de resistência positivo, α > 0). Em semicondutores intrínsecos, a geração térmica de pares elétron-buraco através do bandgap cresce exponencialmente (n ∝ e^(-Eg/2kT)), dominando a condutividade (α < 0).", "possui_imagem": false},
  {"id": 41, "uid": "CIEN-9-041", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Polarizabilidade e Forças de London em Halogênios", "dificuldade": "Difícil", "enunciado": "À temperatura ambiente (25 ºC) e 1 atm, os elementos do grupo 17 da Tabela Periódica (halogênios) exibem uma transição contínua impressionante de estados físicos da matéria: o flúor (F2) e o cloro (Cl2) são gases, o bromo (Br2) é um líquido volátil e o iodo (I2) é um sólido escuro com brilho metálico. Essa elevação progressiva nos pontos de fusão e ebulição ao descer na família é explicada por:", "alternativas": {"A": "O aumento no número de ligações iônicas entre os átomos de halogênio.", "B": "O aumento do raio atômico e do número total de elétrons, que eleva a polarizabilidade da nuvem eletrônica molecular; nuvens maiores e mais volumosas são mais facilmente deformáveis, amplificando a magnitude das forças de dispersão de London intermoleculares que unem as moléculas no estado condensado.", "C": "A absorção de calor solar pelo iodo no laboratório.", "D": "O fato de o flúor ser um metal e o iodo ser um gás comprimido.", "E": "A quebra espontânea dos núcleos de bromo em mercúrio líquido."}, "resposta_correta": "B", "justificativa": "Nuvens eletrônicas volumosas e difusas de átomos pesados (como o iodo com Z=53) são muito mais deformáveis por campos elétricos instantâneos externos (alta polarizabilidade molecular α) do que as nuvens compactas de átomos pequenos (flúor com Z=9); isso intensifica as forças atrativas dispersivas de London (U ∝ α²), elevando os pontos de ebulição (F2: -188 ºC -> I2: +184 ºC).", "possui_imagem": false},
  {"id": 42, "uid": "CIEN-9-042", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Hibridização sp, sp2 e sp3 no Carbono", "dificuldade": "Difícil", "enunciado": "O átomo de carbono possui configuração eletrônica fundamental 1s² 2s² 2p², com apenas dois elétrons desemparelhados nos orbitais p. Para formar quatro ligações covalentes tetraédricas equivalentes idênticas na molécula de metano (CH4), o carbono realiza o processo mecanoquímico de 'hibridização de orbitais', que consiste em:", "alternativas": {"A": "Destruir os elétrons do orbital 2s para que não atrapalhem as ligações.", "B": "Promover um elétron do subnível 2s para o orbital 2p vazio e misturar linearmente o orbital 2s com os três orbitais 2p, originando quatro novos orbitais híbridos sp3 degenerados (com mesma energia e forma), orientados simetricamente no espaço a ângulos de 109º 28' entre si.", "C": "Transformar o carbono em um cátion de carga +4 fixo.", "D": "Compartilhar prótons do núcleo com os átomos de hidrogênio.", "E": "Fundir os orbitais atômicos em um único anel metálico circular."}, "resposta_correta": "B", "justificativa": "A hibridização sp3 combina linearmente a função de onda do orbital esférico 2s com as dos três orbitais lobulares 2p (px, py, pz), gerando quatro orbitais híbridos direcionais com 25% de caráter s e 75% de caráter p, cuja repulsão geométrica máxima minimiza a energia na configuração tetraédrica perfeita de 109,5º.", "possui_imagem": false},
  {"id": 43, "uid": "CIEN-9-043", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Momento Dipolar Resultante e Vetores em Moléculas Simétricas", "dificuldade": "Difícil", "enunciado": "A molécula de tetracloreto de carbono (CCl4) possui quatro ligações carbono-cloro fortemente polares (devido à grande diferença de eletronegatividade entre o C e o Cl). No entanto, medidas físico-químicas de constante dielétrica comprovam que o CCl4 é uma substância rigorosamente APOLAR (momento dipolar resultante μ_total = 0). A explicação vetorial para a apolaridade do CCl4 é:", "alternativas": {"A": "Os cloros perderam sua eletronegatividade ao se ligarem ao carbono.", "B": "Devido à geometria tetraédrica perfeitamente simétrica da molécula, os quatro vetores momento dipolar das ligações C-Cl (que apontam para os vértices do tetraedro regular) possuem módulos iguais e anulam-se mutuamente na soma vetorial tridimensional (Σ μ = 0).", "C": "A molécula gira tão rápido que cancela suas cargas por efeito centrífugo.", "D": "O carbono absorve todos os elétrons de volta para o núcleo atômico.", "E": "A ligação C-Cl se torna apolar quando o composto entra em contato com o ar."}, "resposta_correta": "B", "justificativa": "A polaridade global de uma molécula depende da geometria espacial: ligações individuais polares geram vetores momento de dipolo de ligação (μ); quando a simetria molecular espacial é perfeita (como no tetraedro regular de ligantes idênticos CCl4 ou na geometria linear do CO2), o somatório vetorial resultante é nulo (μ_res = 0), classificando a molécula como apolar.", "possui_imagem": false},
  {"id": 44, "uid": "CIEN-9-044", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Geometria Molecular e Pares de Elétrons Livres na Amônia (NH3)", "dificuldade": "Difícil", "enunciado": "A molécula de amônia (NH3) possui quatro pares de elétrons ao redor do átomo central de nitrogênio (três pares compartilhados com hidrogênios e um par de elétrons não ligante livre). O ângulo experimental entre as ligações N-H na amônia é de aproximadamente 107º, sendo ligeiramente menor do que o ângulo tetraédrico ideal de 109,5º do metano (CH4). Esse fechamento angular na amônia é provocado por:", "alternativas": {"A": "A atração de gravidade exercida pelo núcleo do nitrogênio sobre os hidrogênios.", "B": "A maior repulsão eletrostática exercida pelo par de elétrons não ligante (par livre), que é atraído por apenas um núcleo atômico e ocupa um volume angular maior no espaço do que os pares compartilhados, comprimindo os pares ligantes vizinhos.", "C": "A quebra espontânea de uma das ligações covalentes com o hidrogênio.", "D": "A presença de ar comprimido dentro da molécula de amônia.", "E": "O resfriamento térmico dos hidrogênios em relação ao nitrogênio."}, "resposta_correta": "B", "justificativa": "Pela teoria VSEPR de Gillespie-Nyholm, a hierarquia de forças repulsivas dita que: repulsão par livre-par livre > par livre-par ligante > par ligante-par ligante. O par de elétrons isolado do nitrogênio, confinado a um único centro nuclear, é mais difuso e exerce maior pressão estérica de repulsão sobre as nuvens ligantes N-H, fechando o ângulo para 107º na pirâmide trigonal.", "possui_imagem": false},
  {"id": 45, "uid": "CIEN-9-045", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Propriedades Térmicas de Nanotubos de Carbono", "dificuldade": "Difícil", "enunciado": "Nanotubos de carbono de parede única (SWCNTs) consistem em cilindros ocos com diâmetro de cerca de 1 nanômetro formados pelo enrolamento de uma folha de grafeno. Além de extrema resistência mecânica, eles apresentam condutividade térmica axial extraordinária (mais de 3.500 W/m.K, superando o diamante e o cobre). O transporte de calor ultrarrápido ao longo do eixo do nanotubo ocorre principalmente na forma de:", "alternativas": {"A": "Elétrons que entram em combustão lenta com oxigênio residual.", "B": "Fônons (quantos de vibração mecânica coerente da rede cristalina que viajam balisticamente em linha reta sem espalhamento inelástico na estrutura molecular perfeita e rígida de ligações sp2).", "C": "Vapor de água superaquecido confinado no interior oco do tubo.", "D": "Prótons que saltam de um átomo de carbono para outro no vácuo.", "E": "Micro-ondas eletromagnéticas geradas por baterias moleculares internas."}, "resposta_correta": "B", "justificativa": "Em materiais carbônicos de rede covalente com fortíssimas ligações sp2 (como grafeno e nanotubos), a condução de calor é dominada pela propagação acústica de vibrações da rede cristalina quantizadas (fônons); a perfeição estrutural atômica unidimensional confere longo livre percurso médio aos fônons acústicos (condução balística de calor).", "possui_imagem": false},
  {"id": 46, "uid": "CIEN-9-046", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Semicondutores Intrínsecos vs. Extrínsecos: Dopagem Tipo N e Tipo P", "dificuldade": "Difícil", "enunciado": "Na fabricação de microprocessadores e chips de computadores, o silício puro (grupo 14, 4 elétrons de valência) tem sua condutividade elétrica manipulada através da dopagem atômica controlada. A dopagem com fósforo (grupo 15, 5 elétrons de valência) e a dopagem com boro (grupo 13, 3 elétrons de valência) produzem, respectivamente:", "alternativas": {"A": "Semicondutores metálicos e semicondutores iônicos puros.", "B": "Semicondutores do Tipo N (com excesso de elétrons livres de condução fornecidos pelos átomos doadores de fósforo) e semicondutores do Tipo P (com excesso de lacunas ou 'buracos' positivos deixados pelos átomos aceitadores de boro na rede).", "C": "Dois tipos idênticos de isolantes elétricos que não conduzem corrente.", "D": "Supercondutores de alta temperatura sem resistência elétrica.", "E": "Chips que funcionam exclusivamente à base de vapor d'água."}, "resposta_correta": "B", "justificativa": "A dopagem extrínseca substitui átomos tetravalentes de Si na rede: a adição de elemento pentavalente (P, As) fornece um elétron extra desemparelhado na banda de condução (Tipo N / negativo); a adição de elemento trivalente (B, Ga) deixa uma vacância eletrônica na banda de valência que atua como portador móvel de carga positiva fictícia (Tipo P / positivo).", "possui_imagem": false},
  {"id": 47, "uid": "CIEN-9-047", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Efeito Fotoelétrico em Painéis Solares e a Teoria Quântica de Einstein", "dificuldade": "Difícil", "enunciado": "Em células fotovoltaicas de silício presentes em painéis solares, a incidência de luz gera corrente elétrica direta. Em 1905, Albert Einstein explicou o Efeito Fotoelétrico (trabalho que lhe rendeu o Prêmio Nobel de Física em 1921), demonstrando que a emissão de elétrons de um material pela luz depende de:", "alternativas": {"A": "A luz viajar em ondas contínuas de calor mecânico que aquecem o metal até ferver.", "B": "A luz ser quantizada em pacotes discretos de energia chamados fótons (E = h . f), sendo necessário que a frequência da luz incidente supere a frequência de corte mínima do material para que a energia do fóton consiga vencer a função trabalho da superfície e ejetar o elétron da rede.", "C": "A intensidade do brilho da luz ser tão alta que empurra os átomos fisicamente para trás.", "D": "O silício ser queimado como carvão na presença de oxigênio.", "E": "A corrente elétrica ser gerada pela atração magnética da Lua."}, "resposta_correta": "B", "justificativa": "O efeito fotoelétrico confirmou a natureza corpuscular da radiação eletromagnética: cada fóton incidente transfere sua energia discretizada E = hν a um elétron individual; se hν > Φ (função trabalho do material semicondutor), o elétron é ejetado para a banda de condução com energia cinética residual Ec = hν - Φ, gerando corrente fotoelétrica.", "possui_imagem": false},
  {"id": 48, "uid": "CIEN-9-048", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Líquidos Iônicos à Temperatura Ambiente (RTILs)", "dificuldade": "Difícil", "enunciado": "Diferente dos sais minerais comuns (como o NaCl, que fundem a mais de 800 ºC), certos sais sintéticos modernos conhecidos como 'Líquidos Iônicos à Temperatura Ambiente' (RTILs) apresentam pontos de fusão inferiores a 25 ºC, permanecendo líquidos fluidos à temperatura ambiente. O fator molecular que impede esses sais de solidificarem à temperatura ambiente é:", "alternativas": {"A": "Eles não possuírem íons e serem feitos apenas de água destilada.", "B": "A combinação de cátions orgânicos volumosos e altamente assimétricos com ânions difusos que possuem baixa densidade de carga localizada, o que desestabiliza e impede o empacotamento geométrico ordenado no retículo cristalino sólido e derruba a energia reticular a níveis mínimos.", "C": "A presença de pedras de gelo microscópicas no interior do líquido.", "D": "O fato de os elétrons evaporarem para fora do frasco fechado.", "E": "Eles serem substâncias radioativas que explodem quando esfriam."}, "resposta_correta": "B", "justificativa": "Sais como cloreto de 1-butil-3-metilimidazólio ([BMIM]Cl) contêm cátions orgânicos heterocíclicos volumosos com conformações conformacionais flexíveis e assimetria estérica pronunciada combinados com ânions deslocalizados (como TFSI-); a desordem entrópica e a baixa densidade de carga frustram a nucleação de retículo cristalino ordenado, mantendo o estado líquido estável à temperatura ambiente.", "possui_imagem": false},
  {"id": 49, "uid": "CIEN-9-049", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Diamagnetismo, Paramagnetismo e Ferromagnetismo nos Materiais", "dificuldade": "Difícil", "enunciado": "A resposta magnética de diferentes materiais a campos magnéticos externos divide-os em diamagnéticos, paramagnéticos e ferromagnéticos. Materiais ferromagnéticos (como o ferro, cobalto e níquel metálicos) exibem altíssima atração por ímãs e mantêm magnetização residual permanente porque:", "alternativas": {"A": "Não possuem elétrons em suas camadas eletrônicas.", "B": "Seus átomos possuem elétrons desemparelhados em orbitais d internos cujos spins atômicos acoplam-se paralelamente por forças de troca quântica espontânea, organizando-se em regiões microscópicas coerentes chamadas domínios magnéticos de Weiss que se alinham na presença do campo externo.", "C": "São compostos por água congelada magnetizada no subsolo.", "D": "Absorvem radiação solar através de poros invisíveis na carcaça.", "E": "Perdem todos os prótons do núcleo quando encostam em um ímã."}, "resposta_correta": "B", "justificativa": "O ferromagnetismo resulta da interação de troca mecânico-quântica (exchange interaction) que favorece o alinhamento paralelo de spins desemparelhados de camadas d ou f incompletas em domínios magnéticos de Weiss contendo bilhões de momentos de dipolo alinhados espontaneamente; a aplicação de campo externo expande os domínios favoráveis, gerando magnetização de saturação massiva.", "possui_imagem": false},
  {"id": 50, "uid": "CIEN-9-050", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 15: Ligações Químicas e Propriedades dos Materiais", "tema": "Ponto Crítico e Fluidos Supercríticos: CO2 Supercrítico", "dificuldade": "Difícil", "enunciado": "Quando uma substância como o dióxido de carbono (CO2) é submetida a temperaturas superiores a 31,1 ºC e pressões superiores a 73 atmosferas (acima de seu Ponto Crítico termodinâmico), a interface visual que separa a fase líquida da fase gasosa desaparece completamente, formando o chamado 'Fluido Supercrítico'. A enorme aplicação industrial do CO2 supercrítico (como na descafeinização do café e extração de óleos essenciais nobres) baseia-se no fato de que ele:", "alternativas": {"A": "É um ácido mineral corrosivo que dissolve metais pesados.", "B": "Combina propriedades físicas híbridas extraordinárias: possui densidade comparável à de um líquido (conferindo alto poder de dissolução seletiva de compostos orgânicos) e viscosidade e difusividade semelhantes às de um gás (penetrando com facilidade e rapidez em poros microscópicos de sólidos vegetais, sem deixar resíduos tóxicos após despressurização).", "C": "Fica no estado de gelo seco brilhante a 500 graus Celsius.", "D": "Se transforma em gasolina fóssil de alta octanagem de avião.", "E": "Reage com o oxigênio explodindo como dinamite no café."}, "resposta_correta": "B", "justificativa": "Fluidos supercríticos operam além do ponto crítico líquido-vapor (Tc, Pc): com tensões superficiais nulas e propriedades de transporte gasosas acopladas a densidades solventes líquidas, o CO2 supercrítico atua como solvente verde 'sintonizável' (tunable solvent) cuja densidade e poder de solvatação variam continuamente com a pressão, despressurizando-se como gás atóxico sem contaminantes residuais.", "possui_imagem": false},
  {"id": 51, "uid": "CIEN-9-051", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Conceito de Ácido de Arrhenius", "dificuldade": "Fácil", "enunciado": "De acordo com a teoria clássica do químico sueco Svante Arrhenius, ácidos são substâncias que, quando dissolvidas em água líquida, sofrem ionização e liberam exclusivamente como cátion o íon:", "alternativas": {"A": "Hidróxido (OH^-).", "B": "Hidrogênio (H^+ ou hidrônio H3O^+).", "C": "Sódio (Na^+).", "D": "Cloreto (Cl^-).", "E": "Óxido (O^2-)."}, "resposta_correta": "B", "justificativa": "Segundo a definição eletrolítica de Arrhenius, ácidos são compostos moleculares que em solução aquosa se ionizam, liberando íons H+ (H3O+) como os únicos cátions presentes no meio.", "possui_imagem": true},
  {"id": 52, "uid": "CIEN-9-052", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Conceito de Base de Arrhenius", "dificuldade": "Fácil", "enunciado": "Ainda segundo a teoria de Arrhenius, as bases (ou hidróxidos) são compostos que, em solução aquosa, sofrem dissociação iônica e liberam exclusivamente como ânion o íon:", "alternativas": {"A": "Hidrogênio (H^+).", "B": "Hidróxido ou hidroxila (OH^-).", "C": "Sulfato (SO4^2-).", "D": "Nitrato (NO3^-).", "E": "Carbonato (CO3^2-)."}, "resposta_correta": "B", "justificativa": "Bases de Arrhenius são compostos que liberam ânions hidróxido (OH-) como os únicos ânions em solução aquosa através do processo de dissociação iônica.", "possui_imagem": true},
  {"id": 53, "uid": "CIEN-9-053", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Escala de pH: Acidez, Neutralidade e Alcalinidade", "dificuldade": "Fácil", "enunciado": "A escala de pH varia de 0 a 14 a uma temperatura de 25 ºC e afere o grau de acidez ou alcalinidade de uma solução aquosa. Uma solução é considerada ácida, neutra ou básica (alcalina), respectivamente, quando seu valor de pH é:", "alternativas": {"A": "Maior que 7, igual a 14 e menor que 0.", "B": "Menor que 7, igual a 7 e maior que 7.", "C": "Igual a 10, menor que 2 e igual a 0.", "D": "Menor que 1, igual a 10 e maior que 20.", "E": "Negativo, zero e infinito."}, "resposta_correta": "B", "justificativa": "A escala de pH convencional a 25 ºC estabelece que: soluções com pH < 7 possuem caráter ácido ([H+] > [OH-]); pH = 7 representa neutralidade ([H+] = [OH-]); e pH > 7 caracteriza meio básico ou alcalino ([OH-] > [H+]).", "possui_imagem": true},
  {"id": 54, "uid": "CIEN-9-054", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Indicador Fenolftaleína", "dificuldade": "Fácil", "enunciado": "A fenolftaleína é um indicador químico ácido-base amplamente utilizado em aulas de laboratório de ciências. Ao adicionar algumas gotas de fenolftaleína a uma solução de hidróxido de sódio (NaOH, meio básico), a cor da solução torna-se imediatamente:", "alternativas": {"A": "Amarela ouro.", "B": "Rosa-carmim (ou magenta brilhante).", "C": "Azul marinho escuro.", "D": "Incolor transparente.", "E": "Verde folha."}, "resposta_correta": "B", "justificativa": "A fenolftaleína permanece completamente incolor em soluções ácidas e neutras (pH < 8,2) e assume uma coloração rosa-carmim intensa/magenta em meios alcalinos básicos (pH entre 8,2 e 10,0).", "possui_imagem": true},
  {"id": 55, "uid": "CIEN-9-055", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Reação de Neutralização: Ácido + Base", "dificuldade": "Fácil", "enunciado": "Quando misturamos uma solução de ácido clorídrico (HCl) com uma solução de hidróxido de sódio (NaOH), ocorre uma clássica reação de neutralização química que produz:", "alternativas": {"A": "Dois ácidos e gás oxigênio puro.", "B": "Um sal (cloreto de sódio, NaCl) e água líquida (H2O).", "C": "Lava vulcânica incandescente e petróleo.", "D": "Apenas gás carbônico concentrado.", "E": "Ferro metálico sólido e enxofre."}, "resposta_correta": "B", "justificativa": "A reação de neutralização total entre um ácido e uma base de Arrhenius produz sistematicamente sal e água: Ácido + Base -> Sal + Água (HCl + NaOH -> NaCl + H2O).", "possui_imagem": true},
  {"id": 56, "uid": "CIEN-9-056", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Ácido Clorídrico e Suco Gástrico", "dificuldade": "Fácil", "enunciado": "O ácido clorídrico (fórmula HCl) é um ácido inorgânico forte e volátil. No corpo humano saudável, o HCl desempenha a função vital de compor:", "alternativas": {"A": "A saliva na boca para limpar os dentes.", "B": "O suco gástrico no estômago, auxiliando a digestão enzimática de proteínas e matando bactérias ingeridas com a comida.", "C": "O suor nas axilas durante a corrida.", "D": "A lágrima nos olhos para afastar poeira.", "E": "O líquido sinovial que lubrifica as articulações."}, "resposta_correta": "B", "justificativa": "Células parietais da mucosa gástrica secretam ácido clorídrico (HCl) a um pH estomacal entre 1,5 e 2,0, ativando o pepsinogênio em pepsina funcional e exercendo ação bactericida essencial.", "possui_imagem": true},
  {"id": 57, "uid": "CIEN-9-057", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Base no Cotidiano: Hidróxido de Sódio (Soda Cáustica)", "dificuldade": "Fácil", "enunciado": "O hidróxido de sódio (fórmula química NaOH) é uma base forte e corrosiva vendida no comércio popular com o nome de 'soda cáustica'. No dia a dia doméstico e na indústria, o NaOH é amplamente utilizado para:", "alternativas": {"A": "Temperar saladas de alface e carnes.", "B": "Desentupir encanamentos de esgoto e fabricar sabão a partir de gorduras e óleos vegetais.", "C": "Adoçar sucos de frutas naturais.", "D": "Apagar princípios de incêndio em aparelhos elétricos.", "E": "Lubrificar correntes de bicicleta."}, "resposta_correta": "B", "justificativa": "A soda cáustica (NaOH) saponifica triglicerídeos de gorduras e hidrolisa queratina e matéria orgânica, sendo agente desentupidor de pias e reagente primário na indústria de sabões (reação de saponificação).", "possui_imagem": true},
  {"id": 58, "uid": "CIEN-9-058", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Sal no Cotidiano: Bicarbonato de Sódio", "dificuldade": "Fácil", "enunciado": "O bicarbonato de sódio (fórmula química NaHCO3) é um sal branco muito versátil utilizado em padarias como fermento químico para fazer bolos crescerem e como antiácido estomacal. O bolo cresce porque, ao ser aquecido com os ingredientes, o NaHCO3 libera bolhas de:", "alternativas": {"A": "Gás nitrogênio líquido congelado.", "B": "Dióxido de carbono (gás carbônico - CO2).", "C": "Gás cloro tóxico amarelo.", "D": "Monóxido de carbono asfixiante.", "E": "Vapor de ferro fundido."}, "resposta_correta": "B", "justificativa": "A decomposição térmica ou reação ácida do bicarbonato de sódio (NaHCO3) desprende dióxido de carbono gasoso (CO2), cujas microbolhas expandem a rede de glúten da massa do bolo, tornando-a macia e aerada.", "possui_imagem": true},
  {"id": 59, "uid": "CIEN-9-059", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Antiácido Estomacal: Leite de Magnésia", "dificuldade": "Fácil", "enunciado": "O medicamento conhecido popularmente como 'leite de magnésia', utilizado para aliviar sintomas de queimação no estômago e azia, é uma suspensão aquosa de qual base fraca?", "alternativas": {"A": "Hidróxido de sódio (NaOH).", "B": "Hidróxido de magnésio [Mg(OH)2].", "C": "Ácido sulfúrico (H2SO4).", "D": "Cloreto de potássio (KCl).", "E": "Óxido de enxofre (SO3)."}, "resposta_correta": "B", "justificativa": "O leite de magnésia é constituído por hidróxido de magnésio [Mg(OH)2], uma base pouco solúvel e suave que reage no estômago neutralizando o excesso de ácido clorídrico: Mg(OH)2 + 2 HCl -> MgCl2 + 2 H2O.", "possui_imagem": true},
  {"id": 60, "uid": "CIEN-9-060", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Conceito de Óxidos", "dificuldade": "Fácil", "enunciado": "Na química inorgânica, os óxidos são definidos como compostos binários (formados por apenas dois elementos químicos diferentes), nos quais o elemento mais eletronegativo da substância é obrigatoriamente o:", "alternativas": {"A": "Hidrogênio.", "B": "Oxigênio.", "C": "Carbono.", "D": "Cloro.", "E": "Nitrogênio."}, "resposta_correta": "B", "justificativa": "Por definição, óxidos são compostos binários de fórmula geral ExOy em que o oxigênio é o átomo mais eletronegativo (excluindo-se os fluoretos de oxigênio OF2 e O2F2, onde o flúor é mais eletronegativo).", "possui_imagem": true},
  {"id": 61, "uid": "CIEN-9-061", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Óxidos e a Chuva Ácida: Enxofre", "dificuldade": "Fácil", "enunciado": "A queima de combustíveis fósseis contendo impurezas de enxofre (como carvão mineral e diesel) libera para a atmosfera o gás dióxido de enxofre (SO2) e trióxido de enxofre (SO3). Na atmosfera, o SO3 reage com as gotículas de água da chuva gerando:", "alternativas": {"A": "Ácido sulfúrico (H2SO4), o principal responsável pela acidez prejudicial da chuva ácida.", "B": "Hidróxido de sódio que limpa o ar das cidades.", "C": "Água com açúcar que nutre as florestas tropicais.", "D": "Sal de cozinha puro que precipita como cristais brancos.", "E": "Gás hélio que faz as nuvens voarem mais rápido."}, "resposta_correta": "A", "justificativa": "O SO3 é um óxido ácido (anidrido sulfúrico); ao reagir quimicamente com a água líquida das nuvens, sofre hidratação formando ácido sulfúrico: SO3 + H2O -> H2SO4, derrubando o pH da chuva para valores inferiores a 4,5.", "possui_imagem": true},
  {"id": 62, "uid": "CIEN-9-062", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Óxido de Cálcio: A Cal Virgem", "dificuldade": "Fácil", "enunciado": "O óxido de cálcio (CaO), conhecido na construção civil e na agricultura como 'cal viva' ou 'cal virgem', reage vigorosamente com a água liberando grande quantidade de calor e transformando-se em hidróxido de cálcio [Ca(OH)2], conhecido como 'cal hidratada'. Por essa reação, o CaO é classificado como um:", "alternativas": {"A": "Óxido ácido puro.", "B": "Óxido básico.", "C": "Óxido neutro indiferente.", "D": "Sal neutro de cozinha.", "E": "Ácido carboxílico."}, "resposta_correta": "B", "justificativa": "Óxidos básicos são formados por metais com baixo número de oxidação (+1 ou +2); ao reagirem com água, formam hidróxidos ou bases (CaO + H2O -> Ca(OH)2), ou reagem com ácidos formando sal e água.", "possui_imagem": true},
  {"id": 63, "uid": "CIEN-9-063", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Óxidos Neutros no Cotidiano", "dificuldade": "Fácil", "enunciado": "Gases como o monóxido de carbono (CO) e o monóxido de nitrogênio (NO) são classificados na química como 'óxidos neutros' (ou indiferentes) porque eles:", "alternativas": {"A": "Neutralizam qualquer ácido ou base instantaneamente no ar.", "B": "Não reagem com a água líquida, não reagem com ácidos e não reagem com bases em condições ambientais normais.", "C": "Possuem pH rigorosamente igual a 14.", "D": "São formados por ferro fundido radioativo.", "E": "Não contêm oxigênio em suas fórmulas moleculares."}, "resposta_correta": "B", "justificativa": "Óxidos neutros (como CO, NO e N2O) são compostos covalentes que não apresentam propriedades ácidas nem básicas, não formando ácidos com água e não reagindo com bases ou ácidos diluídos ordinários.", "possui_imagem": false},
  {"id": 64, "uid": "CIEN-9-064", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Ácido Acético e o Vinagre", "dificuldade": "Fácil", "enunciado": "O vinagre comum utilizado para temperar saladas na cozinha deve seu sabor azedo e aroma característico à presença de cerca de 4% a 5% de um ácido orgânico fraco chamado:", "alternativas": {"A": "Ácido sulfúrico.", "B": "Ácido acético (ou ácido etanoico).", "C": "Ácido clorídrico concentrado.", "D": "Ácido nítrico puro.", "E": "Ácido fluorídrico."}, "resposta_correta": "B", "justificativa": "O vinagre culinário é uma solução aquosa diluída de ácido acético (CH3COOH), produzido industrialmente pela fermentação oxidativa do etanol do vinho ou de cereais por bactérias acéticas (Acetobacter).", "possui_imagem": false},
  {"id": 65, "uid": "CIEN-9-065", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Papel de Tornassol: Mudança de Cor", "dificuldade": "Fácil", "enunciado": "O papel de tornassol é uma fita impregnada com corantes naturais extraídos de líquens. Quando uma fita de tornassol azul é mergulhada em uma solução com características ácidas (como suco de limão ou vinagre), sua cor muda para:", "alternativas": {"A": "Verde fluorescente.", "B": "Vermelho (ou rosa).", "C": "Amarelo dourado.", "D": "Preto escorregadio.", "E": "Transparente incolor."}, "resposta_correta": "B", "justificativa": "Em meio ácido (pH < 4,5), o indicador tornassol encontra-se protonado em sua forma vermelha; em meio básico (pH > 8,3), encontra-se desprotonado em sua forma azul.", "possui_imagem": false},
  {"id": 66, "uid": "CIEN-9-066", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Sal Inorgânico: Carbonato de Cálcio", "dificuldade": "Fácil", "enunciado": "O carbonato de cálcio (fórmula CaCO3) é um sal insolúvel em água muito abundante na natureza, compondo o giz escolar, rochas calcárias, mármore e as conchas de moluscos marinhos. Ao pingar gotas de ácido clorídrico sobre uma pedra de calcário, observa-se efervescência imediata devido à liberação de:", "alternativas": {"A": "Gás nitrogênio líquido.", "B": "Gás carbônico (dióxido de carbono - CO2).", "C": "Gás oxigênio puro.", "D": "Fumaça de chumbo sólido.", "E": "Vapor de mercúrio metálico."}, "resposta_correta": "B", "justificativa": "Carbonatos reagem com ácidos fortes produzindo sal solúvel, água e gás carbônico: CaCO3 + 2 HCl -> CaCl2 + H2O + CO2(g), sendo a efervescência de CO2 o teste clássico de identificação geológica de calcários.", "possui_imagem": false},
  {"id": 67, "uid": "CIEN-9-067", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Gás Carbônico (CO2): Óxido Ácido", "dificuldade": "Fácil", "enunciado": "O dióxido de carbono (CO2) presente nos refrigerantes e no ar expirado pelo ser humano é classificado quimicamente como um óxido ácido (anidrido carbônico). Ao borbulhar CO2 na água pura, ele reage quimicamente formando o:", "alternativas": {"A": "Hidróxido de sódio (base cáustica).", "B": "Ácido carbônico (H2CO3, que confere leve acidez à água com gás).", "C": "Ácido clorídrico corrosivo.", "D": "Sal de cozinha sólido cristalino.", "E": "Óxido de ferro marrom."}, "resposta_correta": "B", "justificativa": "O CO2 reage reversivelmente com a água líquida formando ácido carbônico: CO2 + H2O <-> H2CO3, que confere o frescor levemente ácido característico da água mineral gaseificada e refrigerantes.", "possui_imagem": false},
  {"id": 68, "uid": "CIEN-9-068", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Grau de Ionização (Alfa) e Força dos Ácidos", "dificuldade": "Médio", "enunciado": "A força de um ácido depende de sua capacidade de liberar íons H+ em solução aquosa, medida pelo Grau de Ionização (α = número de moléculas ionizadas / número total de moléculas dissolvidas). Um ácido que apresenta α = 92% e outro que apresenta α = 1,3% são classificados, respectivamente, como:", "alternativas": {"A": "Ácido fraco e ácido forte.", "B": "Ácido forte (altamente ionizado, excelente eletrólito) e ácido fraco (pouco ionizado, mau condutor de eletricidade).", "C": "Ambos são sais insolúveis neutros.", "D": "Ácido neutro e base concentrada.", "E": "Ambos são óxidos básicos puros."}, "resposta_correta": "B", "justificativa": "Por convenção da físico-química inorgânica: ácidos com grau de ionização α ≥ 50% são classificados como fortes (como HCl, H2SO4, HNO3); ácidos com 5% < α < 50% são moderados; e ácidos com α ≤ 5% são classificados como fracos (como CH3COOH, H2CO3).", "possui_imagem": false},
  {"id": 69, "uid": "CIEN-9-069", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Reação de Dissociação Iônica vs. Ionização", "dificuldade": "Médio", "enunciado": "Embora ambos os processos produzam íons livres em água, na química diferencia-se rigorosamente a 'dissociação iônica' da 'ionização'. A distinção correta entre esses dois fenômenos reside em:", "alternativas": {"A": "Ionização acontece apenas com metais puros e dissociação com gases nobres.", "B": "Na dissociação iônica, os íons já existiam previamente no retículo cristalino do composto iônico (como no NaOH) e são apenas separados pela água; na ionização, os íons NÃO existiam originalmente (o composto é molecular covalente, como o HCl gasoso) e são criados pela reação química com a água.", "C": "Dissociação quebra os núcleos dos átomos e ionização junta moléculas.", "D": "Ambos são processos exclusivamente físicos que ocorrem sem água.", "E": "A ionização ocorre apenas no vácuo espacial do espaço sideral."}, "resposta_correta": "B", "justificativa": "A dissociação iônica é a separação eletrostática de íons pré-existentes de uma substância iônica pela solvatação da água (NaOH(s) -> Na+(aq) + OH-(aq)). A ionização é uma reação química onde uma substância molecular covalente reage com a água originando novos íons que não existiam (HCl(g) + H2O(l) -> H3O+(aq) + Cl-(aq)).", "possui_imagem": false},
  {"id": 70, "uid": "CIEN-9-070", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Cálculo de Variação de pH: Escala Logarítmica", "dificuldade": "Médio", "enunciado": "A escala de pH é uma escala logarítmica de base 10 calculada pela concentração de íons hidrogênio: pH = -log [H+]. Se o suco de tomate tem pH = 4 e a água pura neutra tem pH = 7, quantas vezes o suco de tomate é MAIS ÁCIDO (isto é, possui maior concentração de íons H+) do que a água neutra?", "alternativas": {"A": "3 vezes mais ácido.", "B": "30 vezes mais ácido.", "C": "1.000 vezes mais ácido (10^3 = 10 x 10 x 10).", "D": "7 vezes mais ácido.", "E": "40 vezes mais ácido."}, "resposta_correta": "C", "justificativa": "Sendo a escala logarítmica, cada unidade inteira de decréscimo no pH corresponde a um aumento de 10 vezes na concentração de íons H+: ΔpH = 7 - 4 = 3 unidades. Portanto: 10^3 = 1.000 vezes maior concentração hidrogeniônica.", "possui_imagem": false},
  {"id": 71, "uid": "CIEN-9-071", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Nomenclatura Básica de Ácidos: Hidrácidos vs. Oxiácidos", "dificuldade": "Médio", "enunciado": "Ácidos inorgânicos que não possuem oxigênio em sua molécula são chamados de hidrácidos e recebem a terminação '-ídrico' (como o ácido clorídrico, HCl). Já os oxiácidos contêm oxigênio e recebem terminações como '-ico' e '-oso'. Qual das alternativas apresenta apenas hidrácidos?", "alternativas": {"A": "H2SO4, HNO3 e H3PO4.", "B": "HCl, HBr, HI e H2S.", "C": "H2CO3, HClO e H3BO3.", "D": "NaOH, KOH e Ca(OH)2.", "E": "CO2, SO2 e SO3."}, "resposta_correta": "B", "justificativa": "Hidrácidos são ácidos binários desprovidos de oxigênio na fórmula: ácido clorídrico (HCl), ácido bromídrico (HBr), ácido iodídrico (HI), ácido sulfídrico (H2S) e ácido cianídrico (HCN). As demais alternativas apresentam oxiácidos ou bases.", "possui_imagem": false},
  {"id": 72, "uid": "CIEN-9-072", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Força de Oxiácidos: Regra de Pauling", "dificuldade": "Médio", "enunciado": "Para estimar a força relativa de um oxiácido de fórmula geral HaXOb, o químico Linus Pauling propôs a regra matemática subtraindo o número de átomos de hidrogênio ionizáveis do número de átomos de oxigênio (n = b - a). Pela Regra de Pauling, o ácido sulfúrico (H2SO4, onde n = 4 - 2 = 2) e o ácido hipocloroso (HClO, onde n = 1 - 1 = 0) são classificados, respectivamente, como:", "alternativas": {"A": "Ácido fraco e ácido forte.", "B": "Ácido forte (n = 2) e ácido fraco (n = 0).", "C": "Ambos são ácidos moderados de mesma força.", "D": "Ácido neutro e sal duplo.", "E": "Bases solúveis fortes."}, "resposta_correta": "B", "justificativa": "Pela Regra de Pauling para oxiácidos HaXOb: se (b - a) ≥ 2 o ácido é forte (H2SO4 com 4-2=2, HNO3 com 3-1=2); se (b - a) = 1 o ácido é moderado (H3PO4); se (b - a) = 0 o ácido é fraco (HClO com 1-1=0, H3BO3).", "possui_imagem": false},
  {"id": 73, "uid": "CIEN-9-073", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Reação de Metais com Ácidos: Liberação de H2", "dificuldade": "Médio", "enunciado": "Ao colocar raspas de zinco metálico (Zn) ou ferro em um tubo de ensaio contendo ácido clorídrico (HCl), observa-se efervescência vigorosa de um gás incolor que entra em combustão com um pequeno estalo ('pop') ao aproximar uma chama. A reação química ocorrida e o gás liberado são:", "alternativas": {"A": "Zn + 2 HCl -> ZnCl2 + H2 (gás hidrogênio liberado por simples troca).", "B": "Zn + HCl -> ZnO + Cl2 (gás cloro liberado).", "C": "Zn + HCl -> ZnH2 + CO2 (gás carbônico).", "D": "Zn + 2 HCl -> Zn + H2O (vapor de água).", "E": "Não há reação química, apenas evaporação física do ácido."}, "resposta_correta": "A", "justificativa": "Metais com potencial de redução menor que o hidrogênio (metais reativos como Zn, Fe, Mg) sofrem oxidação por ácidos minerais com redução dos íons H+ a gás hidrogênio molecular inflamável: Zn(s) + 2 HCl(aq) -> ZnCl2(aq) + H2(g).", "possui_imagem": false},
  {"id": 74, "uid": "CIEN-9-074", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Neutralização Parcial e Sais Ácidos (Hidrogenossais)", "dificuldade": "Médio", "enunciado": "Quando uma molécula de ácido sulfúrico (H2SO4, diácido) reage com apenas uma molécula de hidróxido de sódio (NaOH, monobase), ocorre uma neutralização parcial estequiométrica formando água e o sal denominado hidrogenossulfato de sódio (fórmula NaHSO4). Esse composto é classificado como um:", "alternativas": {"A": "Sal básico (hidroxissal).", "B": "Sal ácido (hidrogenossal, que ainda preserva um hidrogênio ionizável em sua estrutura).", "C": "Óxido duplo hidratado.", "D": "Ácido mineral puro.", "E": "Composto covalente volátil."}, "resposta_correta": "B", "justificativa": "Sais ácidos (hidrogenossais) originam-se da neutralização parcial de poliácidos quando nem todos os hidrogênios ionizáveis são consumidos pela base, retendo cátions H+ substituíveis no ânion do sal (como NaHSO4 ou NaHCO3).", "possui_imagem": false},
  {"id": 75, "uid": "CIEN-9-075", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Ácido Fluorídrico (HF) e o Ataque ao Vidro", "dificuldade": "Médio", "enunciado": "Em laboratórios de química analítica, todos os ácidos fortes (como sulfúrico, nítrico e clorídrico) são guardados com segurança em frascos de vidro borossilicato. No entanto, o ácido fluorídrico (HF), embora seja considerado um ácido moderado, NUNCA pode ser armazenado em vidro, devendo ser guardado em frascos de polietileno (plástico). O motivo dessa restrição técnica é:", "alternativas": {"A": "O HF explodir espontaneamente quando entra em contato com a luz visível.", "B": "O HF ser o único ácido capaz de reagir quimicamente e corroer o dióxido de silício (SiO2, o vidro), dissolvendo o frasco e formando tetrafluoreto de silício gasoso (SiF4).", "C": "O vidro esfriar o ácido fluorídrico até congelar a tampa.", "D": "O HF queimar os átomos de oxigênio do vidro por combustão nuclear.", "E": "O plástico absorver a acidez do produto tornando-o neutro."}, "resposta_correta": "B", "justificativa": "O ácido fluorídrico possui afinidade química ímpar pelo silício, reagindo diretamente com a rede de sílica do vidro: SiO2 + 4 HF -> SiF4 + 2 H2O (ou H2SiF6), dissolvendo as paredes do frasco e sendo utilizado industrialmente para gravar caracteres e fosquear peças de vidro.", "possui_imagem": false},
  {"id": 76, "uid": "CIEN-9-076", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Gás Sulfídrico (H2S): O Cheiro de Ovo Podre", "dificuldade": "Médio", "enunciado": "Em esgotos sanitários, lagoas eutrofizadas e na putrefação de matéria orgânica que contém proteínas ricas em enxofre, forma-se o gás sulfídrico (fórmula química H2S). Esse hidrácido é famoso pelo seu cheiro fétido característico de 'ovo podre' e é extremamente perigoso em ambientes confinados porque:", "alternativas": {"A": "Ele atrai mosquitos gigantes da floresta.", "B": "Além de ser inflamável, é um gás altamente neurotóxico e paralisante do olfato que inibe a enzima citocromo c oxidase celular de forma semelhante ao cianeto, podendo causar asfixia celular e morte rápida em altas concentrações.", "C": "Ele solidifica o sangue dos trabalhadores em plástico duro.", "D": "Ele é feito de ouro radioativo que queima a pele.", "E": "Ele não possui peso e flutua para a estratosfera em segundos."}, "resposta_correta": "B", "justificativa": "O ácido sulfídrico (H2S gasoso) é um asfixiante celular sistêmico de alta toxicidade que inibe a cadeia de transporte de elétrons mitocondrial; em concentrações acima de 100 ppm, paralisa rapidamente o nervo olfatório, privando a vítima da percepção do odor e causando colapso respiratório fatal.", "possui_imagem": false},
  {"id": 77, "uid": "CIEN-9-077", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Chuva Ácida Natural vs. Antropogênica", "dificuldade": "Médio", "enunciado": "Mesmo em regiões totalmente desabitadas e livres de poluição industrial (como no meio de florestas intocadas), a água da chuva normal e limpa NÃO possui pH rigorosamente neutro igual a 7,0, mas apresenta um pH naturalmente levemente ácido em torno de 5,6. Essa acidez natural da chuva limpa decorre da:", "alternativas": {"A": "Presença de ácido clorídrico que evapora dos oceanos.", "B": "Dissolução do dióxido de carbono (CO2) presente naturalmente na atmosfera na água da chuva, formando ácido carbônico (H2CO3) em equilíbrio fraco.", "C": "Queda de cinzas de meteoros do espaço sideral.", "D": "Poluição causada por peixes nos rios.", "E": "Respiração de pássaros durante o voo migratório."}, "resposta_correta": "B", "justificativa": "A atmosfera pura contém ~0,04% de CO2 natural que se dissolve no vapor d'água das nuvens em equilíbrio termodinâmico: CO2 + H2O <-> H2CO3 <-> H+ + HCO3-, estabelecendo um pH natural de ~5,6. Considera-se 'chuva ácida antropogênica' quando o pH cai abaixo de 5,0 por ação de SOx e NOx industriais.", "possui_imagem": false},
  {"id": 78, "uid": "CIEN-9-078", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Classificação de Sais: Solubilidade e Regras Práticas", "dificuldade": "Médio", "enunciado": "Na química de soluções inorgânicas, as regras de solubilidade dos sais auxiliam a prever quando ocorrerá a formação de um precipitado sólido insolúvel. Como regra geral de ampla aplicação analítica, quais sais são praticamente 100% SOLÚVEIS em água em qualquer situação?", "alternativas": {"A": "Todos os sais de carbonato e sulfato de ferro.", "B": "Todos os sais formados por cátions de metais alcalinos (família 1, como Na+ e K+) e todos os sais de ânion nitrato (NO3^-).", "C": "Todos os sais que contêm chumbo, prata e mercúrio.", "D": "Nenhum sal se dissolve em água à temperatura ambiente.", "E": "Apenas sais extraídos do fundo de vulcões marinhos."}, "resposta_correta": "B", "justificativa": "Regras analíticas clássicas de solubilidade estabelecem que todos os sais contendo cátions do grupo 1 (Li+, Na+, K+, Rb+, Cs+), cátion amônio (NH4+) e todos os sais derivados do ânion nitrato (NO3-) e acetato (CH3COO-) são universalmente solúveis em água líquida.", "possui_imagem": false},
  {"id": 79, "uid": "CIEN-9-079", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Peróxido de Hidrogênio (H2O2) e Propriedades Especiais", "dificuldade": "Médio", "enunciado": "A água oxigenada comercial é uma solução aquosa de peróxido de hidrogênio (H2O2). Os peróxidos são óxidos especiais em que o oxigênio possui número de oxidação excepcional de -1 (em vez do nox habitual -2), unidos por uma ponte de oxigênio (-O-O-). Ao pingar água oxigenada sobre um ferimento que sangra, ocorre intensa efervescência de oxigênio devido à ação de qual enzima celular?", "alternativas": {"A": "Amilase salivar.", "B": "Catalase (uma enzima antioxidante que acelera a quebra de H2O2 em água líquida e gás oxigênio O2).", "C": "Pepsina gástrica ácida.", "D": "Insulina pancreática.", "E": "Ptialina de dente."}, "resposta_correta": "B", "justificativa": "A catalase é uma enzima peroxissomal heme-dependente extremamente rápida presente nas hemácias e tecidos que decompõe o peróxido de hidrogênio citotóxico: 2 H2O2 -> 2 H2O + O2(g); a efervescência observada na pele machucada é a liberação mecânica imediata de bolhas de oxigênio gasoso.", "possui_imagem": false},
  {"id": 80, "uid": "CIEN-9-080", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Óxidos Anfóteros: Zinco e Alumínio", "dificuldade": "Médio", "enunciado": "Certos óxidos metálicos, como o óxido de zinco (ZnO) e o óxido de alumínio (Al2O3), apresentam comportamento químico duplo singular dependendo do meio em que se encontram: reagem com ácidos fortes comportando-se como bases, e reagem com bases fortes comportando-se como ácidos. Esses óxidos são classificados como:", "alternativas": {"A": "Óxidos neutros indiferentes.", "B": "Óxidos anfóteros.", "C": "Superóxidos nucleares.", "D": "Óxidos ácidos puros anidridos.", "E": "Sais duplos hidratados."}, "resposta_correta": "B", "justificativa": "Óxidos anfóteros são substâncias que reagem tanto com ácidos fortes (atuando como aceptores de prótons/bases) quanto com bases fortes (formando complexos solúveis como aluminatos e zincatos), exibindo caráter ácido-base intermediário dependente do reagente antagonista.", "possui_imagem": false},
  {"id": 81, "uid": "CIEN-9-081", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Sais Hidratados: O Sulfato de Cobre Pentaidratado", "dificuldade": "Médio", "enunciado": "Em prateleiras de laboratórios de ciências, encontra-se um sal em belos cristais azuis brilhantes chamado sulfato de cobre pentaidratado (fórmula CuSO4 . 5 H2O). Ao aquecer suavemente esses cristais azuis em uma cápsula de porcelana, o sal perde suas moléculas de água de cristalização e transforma-se em um pó branco sem brilho (CuSO4 anidro). Esse pó branco volta a ficar azul se pingarmos água sobre ele. Esse fenômeno comprova que:", "alternativas": {"A": "O cobre metálico derreteu e virou água pura.", "B": "A cor azul dos cristais dependia da presença coordenada das moléculas de água presas no interior do retículo cristalino (água de hidratação/cristalização).", "C": "O sal queimou com oxigênio virando fumaça branca.", "D": "A água continha tinta azul misturada antes do experimento.", "E": "Houve a transformação do sal em ácido clorídrico."}, "resposta_correta": "B", "justificativa": "Sais hidratados incorporam uma razão estequiométrica fixa de moléculas de água em sua rede cristalina (ligadas por forças de coordenação ao cátion Cu2+); a remoção térmica das moléculas de água altera a simetria do campo cristalino dos orbitais d do cobre, descorando o sal em CuSO4 anidro branco.", "possui_imagem": false},
  {"id": 82, "uid": "CIEN-9-082", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Hipoclorito de Sódio e o Poder Alvejante da Água Sanitária", "dificuldade": "Médio", "enunciado": "A água sanitária utilizada na desinfecção e alvejamento de superfícies é uma solução aquosa contendo cerca de 2% a 2,5% de hipoclorito de sódio (fórmula química NaClO). O poder bactericida e alvejante dessa solução decorre do fato de o ânion hipoclorito (ClO^-) atuar como:", "alternativas": {"A": "Um combustível fóssil que queima bactérias por fogo direto.", "B": "Um agente oxidante extremamente potente, que reage quimicamente e oxida componentes vitais de paredes celulares e enzimas bacterianas, além de destruir duplas ligações de corantes orgânicos.", "C": "Um ácido fraco que resfria a água até o congelamento.", "D": "Uma base sólida que petrifica os microrganismos em pedra.", "E": "Uma vitamina nutritiva que alimenta fungos benéficos."}, "resposta_correta": "B", "justificativa": "O íon hipoclorito (ClO-) e o ácido hipocloroso (HClO) em equilíbrio hidrolítico possuem altíssimo potencial de oxidação: eles transferem oxigênio e clorinam irreversivelmente pontes dissulfeto e grupos tiol de proteínas de membrana bacteriana, desestruturando envelopes virais e despigmentando cromóforos orgânicos.", "possui_imagem": false},
  {"id": 83, "uid": "CIEN-9-083", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Sulfato de Cálcio e o Gesso na Ortopedia", "dificuldade": "Médio", "enunciado": "Na imobilização de fraturas ósseas e na modelagem de molduras no teto, utiliza-se o pó de gesso estuque (hemidrato de sulfato de cálcio, CaSO4 . 1/2 H2O). Quando o médico ou operário mistura esse pó com água e o aplica sobre a gaze, a massa endurece e esquenta em poucos minutos tornando-se um bloco rígido e sólido (gesso hidratado, CaSO4 . 2 H2O). O endurecimento e aquecimento do gesso decorrem de:", "alternativas": {"A": "A queima de carvão mineral dentro do pó.", "B": "Uma reação química exotérmica de reidratação cristalina que incorpora moléculas de água na rede sólida formando uma malha entrelaçada densa de cristais de di-hidrato.", "C": "A evaporação de toda a água da mistura para a atmosfera.", "D": "A fusão atômica de átomos de cálcio gerando radiação.", "E": "A decomposição do pó em gás carbônico comprimido."}, "resposta_correta": "B", "justificativa": "A pega do gesso ortopédico é uma reação de reidratação exotérmica controlada: CaSO4 . 0,5 H2O + 1,5 H2O -> CaSO4 . 2 H2O (gipsita) + calor; o crescimento e entrelaçamento tridimensional dos cristais prismáticos de di-hidrato conferem rigidez estrutural rápida à tala.", "possui_imagem": false},
  {"id": 84, "uid": "CIEN-9-084", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Hidróxido de Alumínio e Antiácidos com Efeito Constipante", "dificuldade": "Médio", "enunciado": "Em formulações farmacêuticas de antiácidos estomacais mastigáveis ou líquidos, é comum combinar o hidróxido de magnésio [Mg(OH)2] com o hidróxido de alumínio [Al(OH)3]. A justificativa farmacológica e fisiológica clássica para combinar essas duas bases diferentes no mesmo medicamento é:", "alternativas": {"A": "Uma das bases tem sabor de chocolate e a outra de morango.", "B": "O hidróxido de magnésio possui efeito colateral laxativo (solta o intestino), enquanto o hidróxido de alumínio possui efeito colateral constipante (prende o intestino); a combinação de ambas as bases equilibra o trânsito intestinal do paciente enquanto neutraliza o ácido gástrico.", "C": "O alumínio destrói todas as bactérias da boca em dez segundos.", "D": "O magnésio faz a pessoa dormir profundamente após o almoço.", "E": "Ambas as bases transformam o estômago em um órgão estéril sem suco gástrico."}, "resposta_correta": "B", "justificativa": "O cátion Mg2+ atua como catártico osmótico no intestino delgado, acelerando o trânsito e causando diarreia osmótica; por outro lado, cátions Al3+ relaxam a musculatura lisa gástrica e inibem o peristaltismo, induzindo constipação. A combinação farmacotécnica balanceada 1:1 neutraliza os efeitos colaterais intestinais antagônicos.", "possui_imagem": false},
  {"id": 85, "uid": "CIEN-9-085", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Definição de Ácido e Base de Brønsted-Lowry vs. Lewis", "dificuldade": "Difícil", "enunciado": "Embora a teoria de Arrhenius seja excelente para soluções aquosas simples, ela falha em explicar reações em fase gasosa ou solventes não aquosos (como a reação entre gás amônia e gás clorídrico gerando cloreto de amônio sólido: NH3(g) + HCl(g) -> NH4Cl(s)). Para expandir o conceito, as teorias modernas de Brønsted-Lowry e de Lewis definem, respectivamente, um Ácido como:", "alternativas": {"A": "Uma espécie que doa elétrons e uma espécie que libera íons hidróxido.", "B": "Uma espécie química doadora de prótons (H^+) segundo Brønsted-Lowry, e uma espécie química receptora de um par de elétrons segundo Gilbert Lewis.", "C": "Uma substância sólida insolúvel de sabor doce em ambas as teorias.", "D": "Um átomo que perde todos os seus nêutrons em solução aquosa.", "E": "Uma substância exclusivamente radioativa artificial."}, "resposta_correta": "B", "justificativa": "A teoria de Brønsted-Lowry (1923) baseia-se na transferência de prótons: Ácido é doador de H+ e Base é receptora de H+. A teoria eletrônica mais abrangente de G. N. Lewis (1923) baseia-se em pares de elétrons: Ácido é aceptor de par de elétrons (orbital vazio) e Base é doadora de par de elétrons (par isolado).", "possui_imagem": false},
  {"id": 86, "uid": "CIEN-9-086", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Força Relativa e Equilíbrio de Constante de Acidez (Ka)", "dificuldade": "Difícil", "enunciado": "A força de um ácido fraco em solução aquosa é quantificada termodinamicamente pela Constante de Ionização Ácida (Ka). Sabendo que o ácido fluorídrico possui Ka = 6,8 x 10^-4 e o ácido cianídrico possui Ka = 4,9 x 10^-10 a 25 ºC, pode-se afirmar cientificamente que:", "alternativas": {"A": "O ácido cianídrico é mais forte porque possui expoente negativo maior.", "B": "O ácido fluorídrico é cerca de 1,4 milhão de vezes mais forte que o ácido cianídrico, pois quanto maior o valor numérico de Ka, maior é a extensão da ionização e maior é a concentração de íons H3O^+ em equilíbrio.", "C": "Ambos são ácidos fortes que se ionizam 100% em água.", "D": "O Ka de um ácido não possui nenhuma relação com a sua força química.", "E": "O ácido cianídrico é uma base forte de Arrhenius pura."}, "resposta_correta": "B", "justificativa": "A constante de equilíbrio Ka = [H3O+][A-] / [HA] mensura a extensão da ionização ácida no equilíbrio: quanto maior Ka (menor pKa = -log Ka), mais deslocado para a direita está o equilíbrio e maior a acidez relativa; com Ka da ordem de 10^-4 contra 10^-10, o HF ioniza-se ordens de magnitude mais que o HCN.", "possui_imagem": false},
  {"id": 87, "uid": "CIEN-9-087", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Hidrólise Salina e pH de Soluções de Sais", "dificuldade": "Difícil", "enunciado": "Muitos estudantes acreditam erroneamente que 'toda solução de sal em água tem pH rigorosamente neutro igual a 7'. No entanto, se dissolvermos cloreto de amônio (NH4Cl, sal formado por ácido forte HCl e base fraca NH4OH) em água pura, o pH da solução resultante será estritamente ÁCIDO (pH < 7). Esse desvio ocorre devido ao fenômeno da 'hidrólise salina', no qual:", "alternativas": {"A": "O cloreto queima as moléculas de hidrogênio da água.", "B": "O cátion amônio (NH4^+), proveniente da base fraca, reage quimicamente com a água (hidrólise do cátion), regenerando a base fraca pouco dissociada (NH4OH) e liberando íons hidrônio (H3O^+) em excesso no meio, tornando a solução ácida.", "C": "O sal de amônio se transforma em ácido sulfúrico concentrado.", "D": "A água perde toda a sua condutividade elétrica.", "E": "O oxigênio da água evapora instantaneamente como gás puro."}, "resposta_correta": "B", "justificativa": "Na hidrólise salina, íons derivados de eletrólitos fracos reagem com a água. O cátion NH4+ (ácido conjugado da base fraca NH3) hidrolisa: NH4+ + H2O <-> NH3 + H3O+, liberando excesso de H3O+ em solução; o ânion Cl- (base conjugada do ácido forte HCl) é espectador e não hidrolisa, resultando em pH ácido (<7).", "possui_imagem": false},
  {"id": 88, "uid": "CIEN-9-088", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Solução Tampão (Buffer) e Manutenção do pH Sanguíneo", "dificuldade": "Difícil", "enunciado": "O sangue humano mantém seu pH rigorosamente estável em uma faixa vital estreita entre 7,35 e 7,45. Variações de apenas 0,4 unidade de pH no sangue podem levar ao coma ou à morte por acidose ou alcalose metabólica. O principal sistema químico de Solução Tampão (Buffer) que neutraliza variações de acidez no sangue é o par conjugado:", "alternativas": {"A": "Ácido clorídrico e hidróxido de sódio.", "B": "Ácido carbônico (H2CO3) e íon bicarbonato (HCO3^-) em equilíbrio fisiológico dinâmico com a ventilação pulmonar de CO2 e a excreção renal de bicarbonato.", "C": "Sulfato de cobre e cal hidratada.", "D": "Vinagre puro e sabão em pó dissolvido.", "E": "Água oxigenada e hipoclorito de sódio."}, "resposta_correta": "B", "justificativa": "O sistema tampão bicarbonato/ácido carbônico plasmático opera pelo equilíbrio: CO2(g) + H2O <-> H2CO3 <-> H+ + HCO3-. Excessos de H+ metabólicos são tamponados por HCO3- formando H2CO3 que é eliminado como CO2 pelos pulmões; quedas de H+ são repostas pela dissociação do H2CO3 e retenção renal de bicarbonato (Equação de Henderson-Hasselbalch).", "possui_imagem": false},
  {"id": 89, "uid": "CIEN-9-089", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Ácidos Polipróticos e Ionizações Sucessivas", "dificuldade": "Difícil", "enunciado": "O ácido fosfórico (H3PO4) é um triácido que se ioniza em três etapas sucessivas em água, apresentando três constantes de ionização distintas (Ka1 = 7,5 x 10^-3; Ka2 = 6,2 x 10^-8; Ka3 = 4,2 x 10^-13). A explicação física para o fato de a primeira constante de ionização ser ordens de magnitude maior que a segunda e a terceira (Ka1 >> Ka2 >> Ka3) é:", "alternativas": {"A": "O segundo e terceiro hidrogênios serem feitos de chumbo em vez de prótons.", "B": "A primeira ionização remove um próton positivo (H^+) de uma molécula neutra (H3PO4); as ionizações subsequentes exigem remover um próton positivo de ânions que já possuem carga líquida negativa residual (H2PO4^- e HPO4^2-), o que demanda muito maior energia devido à intensa atração eletrostática contrária.", "C": "As mitocôndrias da água impedirem a saída de mais de um elétron.", "D": "O fósforo perder sua massa atômica após o primeiro minuto.", "E": "A temperatura da solução cair para zero grau após a primeira ionização."}, "resposta_correta": "B", "justificativa": "A remoção de um cátion H+ de uma espécie neutra envolve barreira eletrostática moderada (Ka1); remover um segundo H+ do ânion monovalente H2PO4- e um terceiro do ânion divalente HPO4^2- exige superar a forte atração coulombiana restauradora da carga negativa central do ânion, tornando Ka sucessivos centenas de milhares de vezes menores.", "possui_imagem": false},
  {"id": 90, "uid": "CIEN-9-090", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Reação de Saponificação: Síntese de Sabão", "dificuldade": "Difícil", "enunciado": "A fabricação tradicional de sabão de barra a partir de óleo de cozinha usado baseia-se na reação química de saponificação (hidrólise alcalina de ésteres). Nessa reação, um triglicerídeo (gordura ou óleo) reage com uma base forte aquecida (hidróxido de sódio, NaOH), produzindo como produtos finais:", "alternativas": {"A": "Petróleo refinado e gás natural fóssil.", "B": "Sais de ácidos graxos de sódio (o sabão propriamente dito) e glicerol (glicerina pura, um triálcool solúvel).", "C": "Ácido sulfúrico concentrado e pó de ferro.", "D": "Apenas água destilada e sal de cozinha comum.", "E": "Plástico rígido biodegradável e oxigênio líquido."}, "resposta_correta": "B", "justificativa": "A saponificação é a hidrólise de triésteres de glicerila em meio fortemente alcalino: cada molécula de triglicerídeo é clivada pelo ataque nucleofílico de 3 íons hidróxido (OH-), liberando 1 molécula de 1,2,3-propanotriol (glicerina) e 3 moléculas de sais de carboxilato de sódio de cadeia longa (sabão tensoativo).", "possui_imagem": false},
  {"id": 91, "uid": "CIEN-9-091", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Superácidos e a Escala de Hammett", "dificuldade": "Difícil", "enunciado": "Na química avançada, chamam-se 'superácidos' aqueles que possuem acidez superior à do ácido sulfúrico 100% puro. O mais potente superácido conhecido é o 'ácido fluoroantimônico' (uma mistura de ácido fluorídrico e pentafluoreto de antimônio: HF + SbF5). A causa da acidez cósmica colossal desse sistema baseia-se em:", "alternativas": {"A": "A capacidade do antimônio de destruir todos os elétrons do laboratório.", "B": "O SbF5 atuar como um poderosíssimo ácido de Lewis que se coordena fortemente com o ânion fluoreto (F^-), formando o ânion ultraestável e deslocalizado [SbF6]^- e deixando prótons H^+ praticamente 'nus' e livres de qualquer solvatação na solução, com afinidade protonante extrema.", "C": "O ácido ser armazenado dentro de barras de ferro puro fundido.", "D": "A mistura produzir calor suficiente para derreter diamantes instantaneamente.", "E": "O flúor se transformar em gás nobre inerte durante a reação."}, "resposta_correta": "B", "justificativa": "O pentafluoreto de antimônio (SbF5) é um potente aceptor de pares de elétrons de Lewis; ao sequestrar o ânion F- do HF formando o ânion octaédrico fracamente coordenante [SbF6]-, ele desestabiliza a ligação H-F gerando prótons 'desnudados' e desolvatados com função de acidez de Hammett H0 = -31,3 (mais de 10^16 vezes mais protonante que o H2SO4 100%).", "possui_imagem": false},
  {"id": 92, "uid": "CIEN-9-092", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Autoionização da Água e o Produto Iônico (Kw)", "dificuldade": "Difícil", "enunciado": "Mesmo a água quimicamente pura de máxima condutividade nula sofre uma minúscula reação química reversível de transferência de prótons entre suas próprias moléculas chamada autoionização da água: 2 H2O(l) <-> H3O^+(aq) + OH^-(aq). A 25 ºC, o produto iônico da água Kw = [H3O+] . [OH-] é igual a 1,0 x 10^-14. Se a temperatura da água pura for elevada para 60 ºC (sabendo que a autoionização é um processo endotérmico que absorve calor):", "alternativas": {"A": "O Kw cai para zero e a água deixa de ter íons.", "B": "O equilíbrio desloca-se para a direita, aumentando as concentrações de H3O^+ e OH^-, elevando o valor de Kw e reduzindo o pH neutro da água pura para cerca de 6,5, embora a água continue rigorosamente neutra porque [H3O+] continua exatamente igual a [OH-].", "C": "A água pura torna-se um ácido forte corrosivo que dissolve plástico.", "D": "A água pura torna-se uma base cáustica que queima a pele.", "E": "O valor de Kw é uma constante universal imutável que nunca varia com a temperatura."}, "resposta_correta": "B", "justificativa": "Pelo Princípio de Le Chatelier, reações endotérmicas têm sua constante de equilíbrio aumentada com a temperatura: a 60 ºC, Kw ≈ 1,0 x 10^-13; logo [H+] = [OH-] ≈ 3,16 x 10^-7 M, resultando em pH = 6,51. A água permanece quimicamente neutra porque a estequiometria [H+] = [OH-] mantém-se rigorosamente preservada.", "possui_imagem": false},
  {"id": 93, "uid": "CIEN-9-093", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Calagem do Solo e Neutralização de Alumínio Tóxico", "dificuldade": "Difícil", "enunciado": "Muitos solos do Cerrado brasileiro são naturalmente ácidos (pH < 5,0) e contêm altos teores de íons alumínio trivalente solúvel (Al^3+), que é altamente tóxico e atrofia as raízes de culturas agrícolas. A aplicação de calcário agrícola moído (calcita CaCO3 e dolomita MgCO3) corrige o solo porque:", "alternativas": {"A": "O calcário queima as sementes das ervas daninhas com calor químico.", "B": "Os ânions carbonato (CO3^2-) hidrolisam e neutralizam os íons H^+ do solo, elevando o pH para a faixa ideal de 6,0 a 6,5 e promovendo a precipitação do alumínio tóxico na forma de hidróxido de alumínio insolúvel e inofensivo [Al(OH)3], além de fornecer cálcio e magnésio como nutrientes vegetais.", "C": "O calcário transforma a terra arenosa em argila de ferro fundido.", "D": "O solo se transforma em adubo químico sintético de laboratório.", "E": "O calcário atrai a chuva ácida para o subsolo das fazendas."}, "resposta_correta": "B", "justificativa": "A calagem reage com a acidez potencial e ativa do solo: CO3^2- consome H+ liberando HCO3- e elevando o pH; com a elevação do pH acima de 5,5, o Al3+ trocável precipita quantitativamente como gibbsita insolúvel Al(OH)3, eliminando a toxidez radicular e aumentando a saturação por bases (V%).", "possui_imagem": false},
  {"id": 94, "uid": "CIEN-9-094", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Nomenclatura IUPAC de Sais com Múltiplos No-x de Cátions", "dificuldade": "Difícil", "enunciado": "O ferro pode formar dois cátions estáveis com números de oxidação diferentes: Fe^2+ (ferro II ou ferroso) e Fe^3+ (ferro III ou férrico). Ao reagirem com o ácido clorídrico e ácido sulfúrico, formam-se, respectivamente, os sais FeCl2, FeCl3 e Fe2(SO4)3. Os nomes químicos corretos dessas substâncias segundo a nomenclatura IUPAC moderna e tradicional são:", "alternativas": {"A": "Cloreto férrico, cloreto ferroso e sulfito de ferro.", "B": "Cloreto de ferro(II) / cloreto ferroso, cloreto de ferro(III) / cloreto férrico e sulfato de ferro(III) / sulfato férrico.", "C": "Hipoclorito de ferro, perclorato de ferro e óxido ferroso.", "D": "Cloreto de ferro neutro, sal de ferro e ácido sulfúrico sólido.", "E": "Ferro clorídrico I, ferro clorídrico II e ferro sulfúrico III."}, "resposta_correta": "B", "justificativa": "Para metais de transição com valência variável, a IUPAC padroniza a notação de Stock com algarismos romanos da carga do cátion: Fe^2+ é ferro(II) e sufixo -oso; Fe^3+ é ferro(III) e sufixo -ico. Derivados do ácido clorídrico (HCl) recebem sufixo -eto (cloreto) e do ácido sulfúrico (H2SO4) recebem sufixo -ato (sulfato).", "possui_imagem": false},
  {"id": 95, "uid": "CIEN-9-095", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Titulação Ácido-Base e Ponto de Equivalência", "dificuldade": "Difícil", "enunciado": "Em uma titulação analítica clássica no laboratório, 25,0 mL de uma solução de ácido clorídrico (HCl) de concentração molar desconhecida são completamente neutralizados por exatamente 20,0 mL de uma solução padrão de hidróxido de sódio (NaOH) 0,10 mol/L, utilizando fenolftaleína como indicador de ponto final. Qual é a concentração molar calculada da solução de ácido clorídrico?", "alternativas": {"A": "0,050 mol/L.", "B": "0,080 mol/L.", "C": "0,125 mol/L.", "D": "0,200 mol/L.", "E": "0,500 mol/L."}, "resposta_correta": "B", "justificativa": "Pela estequiometria 1:1 da reação HCl + NaOH -> NaCl + H2O: no ponto de equivalência, número de mols de ácido = número de mols de base (M_acido . V_acido = M_base . V_base). Portanto: M_acido x 25,0 mL = 0,10 mol/L x 20,0 mL -> M_acido = 2,0 / 25,0 = 0,080 mol/L.", "possui_imagem": false},
  {"id": 96, "uid": "CIEN-9-096", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Corrosão Eletroquímica do Ferro e Formação da Ferrugem", "dificuldade": "Difícil", "enunciado": "A formação da ferrugem em estruturas de ferro expostas ao ar úmido não é uma simples combinação direta, mas sim um processo eletroquímico de célula galvânica espontânea. Na gota de água condensada sobre a superfície do metal, as semirreações anódica e catódica e o produto final hidratado são, respectivamente:", "alternativas": {"A": "Oxidação do hidrogênio no ânodo e redução do ferro no cátodo formando sulfato de ferro.", "B": "Oxidação do ferro metálico a íons Fe^2+ no ânodo (Fe -> Fe^2+ + 2e^-), redução do gás oxigênio dissolvido no cátodo (O2 + 2 H2O + 4e^- -> 4 OH^-) e precipitação de hidróxido de ferro seguido por oxidação a óxido de ferro(III) hidratado (Fe2O3 . n H2O, a ferrugem).", "C": "Combustão atômica de carbono puro formando fuligem sólida.", "D": "Dissolução do ferro em ácido clorídrico puro secretado pelo ar.", "E": "Transformação do ferro em chumbo radioativo."}, "resposta_correta": "B", "justificativa": "A corrosão atmosférica opera como micropilha galvânica: regiões de tensão mecânica atuam como ânodo oxidando Fe a Fe2+; nas bordas aeradas da gota, o O2 reduz-se catodicamente a OH-; íons Fe2+ e OH- difundem-se precipitando Fe(OH)2, que é oxidado por O2 a óxido férrico hidratado marrom-avermelhado (Fe2O3.nH2O).", "possui_imagem": false},
  {"id": 97, "uid": "CIEN-9-097", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Ácido Nítrico (HNO3) e a Síntese de Fertilizantes e Explosivos", "dificuldade": "Difícil", "enunciado": "O ácido nítrico (fórmula química HNO3) é um dos reagentes inorgânicos mais fabricados e estratégicos da indústria química mundial, produzido em escala de milhões de toneladas pelo Processo Ostwald (oxidação catalítica da amônia sobre tela de platina). Os dois principais destinos industriais do ácido nítrico são:", "alternativas": {"A": "Adoçar refrigerantes e limpar lentes de óculos.", "B": "A fabricação em larga escala de fertilizantes agrícolas nitrogenados (como o nitrato de amônio, NH4NO3) e a síntese de compostos orgânicos nitrados para explosivos industriais e militares (como TNT e nitroglicerina).", "C": "Produzir água oxigenada para tingir cabelos.", "D": "Substituir o óleo diesel em motores de tratores agrícolas.", "E": "Fabricar baterias elétricas de sal de cozinha."}, "resposta_correta": "B", "justificativa": "O HNO3 é o pilar da indústria de nitratos sintéticos: a neutralização com NH3 produz nitrato de amônio (fertilizante macronutriente indispensável para produtividade agrícola global) e reações de nitração eletrofílica aromática produzem ésteres e nitrocompostos energéticos militares e minerários.", "possui_imagem": false},
  {"id": 98, "uid": "CIEN-9-098", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Efeito Nivelador da Água em Ácidos Fortes", "dificuldade": "Difícil", "enunciado": "Em solvente água líquida, ácidos fortes como o ácido perclórico (HClO4), o ácido clorídrico (HCl) e o ácido nítrico (HNO3) parecem possuir exatamente a mesma força ácida (todos se ionizam quase 100%). Esse fenômeno é conhecido como 'Efeito Nivelador da Água', e sua explicação termodinâmica reside no fato de que:", "alternativas": {"A": "A água quebra os núcleos atômicos de todos os ácidos do mundo.", "B": "A base conjugada da água (o íon H3O^+) é o ácido mais forte que pode existir em equilíbrio em solução aquosa; como esses ácidos fortes são muito mais ácidos que o H3O^+, eles transferem seus prótons quantitativamente para as moléculas de água, sendo nivelados à força do cátion hidrônio.", "C": "Todos os ácidos fortes têm a mesma massa atômica de prótons.", "D": "A água pura congela qualquer ácido que entre em contato com ela.", "E": "O pH de qualquer ácido forte na água é rigorosamente igual a 14."}, "resposta_correta": "B", "justificativa": "O efeito nivelador (leveling effect) do solvente anfiprótico estipula que nenhum ácido mais forte que o cátion liônio conjugado do solvente (H3O+ em água) pode coexistir sem reagir completamente; solventes menos básicos (como ácido acético glacial puro) são exigidos para diferenciar a força intrínseca de superácidos (HClO4 > HI > HBr > HCl).", "possui_imagem": false},
  {"id": 99, "uid": "CIEN-9-099", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Gás Cloro e a Formação de Ácido Hipocloroso na Desinfecção da Água", "dificuldade": "Difícil", "enunciado": "Nas estações municipais de tratamento de água potável (ETAs), injeta-se gás cloro (Cl2) na água como agente bactericida e desinfetante final. Ao entrar em contato com a água líquida, o Cl2 sofre uma reação química de desproporcionamento (auto-óxido-redução), gerando como agentes germicidas ativos em equilíbrio:", "alternativas": {"A": "Sal de cozinha sólido e gás nitrogênio puro.", "B": "Ácido clorídrico (HCl) e ácido hipocloroso (HClO), sendo o HClO a espécie neutra e não dissociada dotada do mais potente e rápido poder de destruição de microrganismos patogênicos.", "C": "Soda cáustica concentrada e petróleo cru.", "D": "Gás oxigênio líquido medicinal sem acidez.", "E": "Ácido sulfúrico diluído que corrói os canos de água."}, "resposta_correta": "B", "justificativa": "A cloração da água envolve dismutação: Cl2 + H2O <-> HClO + HCl. O ácido hipocloroso (HClO), por ser uma molécula neutra e apolar de pequeno tamanho, atravessa facilmente a membrana lipofílica de bactérias e protozoários, inativando enzimas respiratórias por oxidação de grupos tiol (-SH) muito mais rápido que o ânion hipoclorito ClO- dissociado.", "possui_imagem": false},
  {"id": 100, "uid": "CIEN-9-100", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 16: Funções Inorgânicas: Ácidos, Bases, Sais e Óxidos", "tema": "Constante de Produto de Solubilidade (Kps) e Formação de Cálculos Renais", "dificuldade": "Difícil", "enunciado": "A formação dolorosa de cálculos renais (pedras nos rins) no sistema urinário humano deve-se frequentemente à precipitação química de cristais de oxalato de cálcio (CaC2O4), um sal inorgânico extremamente insolúvel em água. De acordo com o princípio termodinâmico do Produto de Solubilidade (Kps = [Ca^2+] . [C2O4^2-]), a pedra no rim começa a se formar e crescer quando:", "alternativas": {"A": "A urina da pessoa se torna pura como água destilada.", "B": "O produto das concentrações iônicas dos íons cálcio e oxalato na urina ultrapassa o valor limite da constante do produto de solubilidade (Qip > Kps), tornando a urina supersaturada e induzindo a nucleação e precipitação contínua de cristais sólidos insolúveis nos néfrons.", "C": "O rim deixa de receber sangue arterial oxigenado.", "D": "O paciente ingere veneno de serpente cascavel.", "E": "A temperatura do corpo sobe para 100 graus Celsius."}, "resposta_correta": "B", "justificativa": "O produto de solubilidade Kps governa o equilíbrio de precipitação: quando desidratação crônica (baixo volume urinário) ou hipercalciúria elevam as concentrações molares até que o quociente iônico ultrapasse o Kps (Q > Kps), a solução atinge o regime metastável e supersaturado, deflagrando a nucleação heterogênea e agregação de cristais de oxalato de cálcio (urolitíase).", "possui_imagem": false},
  {"id": 101, "uid": "CIEN-9-101", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Conceito de Reação Química", "dificuldade": "Fácil", "enunciado": "Em uma transformação química, substâncias iniciais sofrem rearranjo de suas ligações atômicas, formando novas substâncias com propriedades distintas. As substâncias que iniciam a transformação e as que são formadas ao final são denominadas, respectivamente:", "alternativas": {"A": "Produtos e reagentes.", "B": "Reagentes e produtos.", "C": "Catalisadores e solutos.", "D": "Soluções e precipitados.", "E": "Misturas e compostos."}, "resposta_correta": "B", "justificativa": "Em uma equação química, os reagentes situam-se antes da seta (substâncias iniciais) e os produtos situam-se após a seta (substâncias formadas).", "possui_imagem": true},
  {"id": 102, "uid": "CIEN-9-102", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Evidências de Reações Químicas", "dificuldade": "Fácil", "enunciado": "Qual das alternativas a seguir apresenta exclusivamente fenômenos considerados evidências macroscópicas comuns da ocorrência de uma reação química?", "alternativas": {"A": "Mudança de estado físico da água e dissolução de sal.", "B": "Liberação de gás (efervescência), formação de precipitado e alteração de cor.", "C": "Trituração de um sólido e evaporação do álcool.", "D": "Fusão do gelo e dilatação térmica de uma barra metálica.", "E": "Condensação de vapor e sublimação do iodo."}, "resposta_correta": "B", "justificativa": "Efervescência (gás), precipitação de sólidos insolúveis, liberação de calor/luz e mudança de coloração são fortes indícios macroscópicos de reações químicas.", "possui_imagem": true},
  {"id": 103, "uid": "CIEN-9-103", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Equações Químicas", "dificuldade": "Fácil", "enunciado": "Na representação de uma reação química por meio de uma equação balanceada, a seta (→) possui o significado fundamental de:", "alternativas": {"A": "Igualdade matemática estrita entre volumes gasosos.", "B": "Sentido da transformação dos reagentes originando os produtos.", "C": "Equilíbrio térmico entre os recipientes do laboratório.", "D": "Indicação de que a reação ocorre apenas no vácuo.", "E": "Separação física entre líquidos e sólidos."}, "resposta_correta": "B", "justificativa": "A seta indica o sentido de conversão em que os reagentes se transformam nos produtos da reação.", "possui_imagem": true},
  {"id": 104, "uid": "CIEN-9-104", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Estados Físicos na Equação", "dificuldade": "Fácil", "enunciado": "Em equações químicas, é frequente o uso de símbolos entre parênteses como (s), (l), (g) e (aq). O símbolo (aq) indica especificamente que a substância está:", "alternativas": {"A": "Em estado gasoso de alta pressão.", "B": "Dissolvida em água, formando uma solução aquosa.", "C": "Em estado sólido cristalino.", "D": "No estado líquido puro e anidro.", "E": "Aquecida acima de 100 °C."}, "resposta_correta": "B", "justificativa": "A notação (aq) refere-se ao estado aquoso, significando que o composto encontra-se dissolvido em água.", "possui_imagem": true},
  {"id": 105, "uid": "CIEN-9-105", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação de Síntese ou Adição", "dificuldade": "Fácil", "enunciado": "Uma reação química em que duas ou mais substâncias reagentes simples ou compostas combinam-se para formar um único produto composto é classificada como:", "alternativas": {"A": "Decomposição ou análise.", "B": "Síntese ou adição.", "C": "Simples troca ou deslocamento.", "D": "Dupla troca.", "E": "Neutralização total."}, "resposta_correta": "B", "justificativa": "A reação de síntese (ou adição) tem forma geral A + B → AB, onde múltiplos reagentes originam um único produto.", "possui_imagem": true},
  {"id": 106, "uid": "CIEN-9-106", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação de Decomposição", "dificuldade": "Fácil", "enunciado": "O aquecimento do carbonato de cálcio sólido resulta na formação de óxido de cálcio sólido e liberação de gás carbônico gasoso [CaCO3(s) → CaO(s) + CO2(g)]. Essa reação é um exemplo típico de:", "alternativas": {"A": "Síntese.", "B": "Decomposição (ou análise).", "C": "Deslocamento simples.", "D": "Dupla troca.", "E": "Precipitação coloidal."}, "resposta_correta": "B", "justificativa": "Reações em que um único reagente se divide em dois ou mais produtos são chamadas de decomposição ou análise.", "possui_imagem": true},
  {"id": 107, "uid": "CIEN-9-107", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Lei de Lavoisier", "dificuldade": "Fácil", "enunciado": "A célebre frase 'Na natureza nada se cria, nada se perde, tudo se transforma' sintetiza a Lei da Conservação das Massas, enunciada por Antoine Lavoisier. Essa lei estabelece que, em um sistema fechado:", "alternativas": {"A": "A massa total dos produtos é sempre o dobro da massa dos reagentes.", "B": "A massa total dos reagentes é exatamente igual à massa total dos produtos.", "C": "A massa dos sólidos sempre diminui devido à perda de energia térmica.", "D": "O volume dos gases gerados é igual à massa dos líquidos.", "E": "Átomos são destruídos para dar lugar a novas moléculas."}, "resposta_correta": "B", "justificativa": "A Lei de Lavoisier estabelece a conservação da massa em sistemas fechados: a soma das massas dos reagentes é igual à soma das massas dos produtos.", "possui_imagem": true},
  {"id": 108, "uid": "CIEN-9-108", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Lei de Proust", "dificuldade": "Fácil", "enunciado": "A Lei das Proporções Definidas (ou Constantes), proposta por Joseph Louis Proust, afirma que:", "alternativas": {"A": "Dois elementos químicos sempre reagem na proporção de 1:1 em massa, independentemente da substância.", "B": "Uma determinada substância pura composta é sempre formada pelos mesmos elementos combinados na mesma proporção em massa.", "C": "A velocidade de uma reação independe da temperatura do meio.", "D": "Gases reagem apenas em proporções molares ímpares.", "E": "A massa dos reagentes é sempre maior que a dos produtos em recipientes abertos."}, "resposta_correta": "B", "justificativa": "A Lei de Proust afirma que uma substância composta apresenta composição mássica constante e fixa entre seus elementos constituintes.", "possui_imagem": true},
  {"id": 109, "uid": "CIEN-9-109", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento Químico - Conceito", "dificuldade": "Fácil", "enunciado": "O balanceamento de uma equação química fundamenta-se na Lei de Lavoisier e tem como objetivo garantir que:", "alternativas": {"A": "Haja o mesmo número de moléculas antes e depois da reação.", "B": "O número total de átomos de cada elemento seja idêntico nos reagentes e nos produtos.", "C": "Os coeficientes estequiométricos sejam sempre números fracionários.", "D": "Todos os reagentes e produtos apresentem a mesma massa molar.", "E": "A reação ocorra sem variação de temperatura."}, "resposta_correta": "B", "justificativa": "Balancear significa igualar a quantidade de átomos de cada elemento químico em ambos os membros da equação, respeitando a conservação atômica.", "possui_imagem": true},
  {"id": 110, "uid": "CIEN-9-110", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Coeficientes Estequiométricos", "dificuldade": "Fácil", "enunciado": "Na equação química 2 H2 + O2 → 2 H2O, o número '2' posicionado antes da fórmula da água (H2O) representa o:", "alternativas": {"A": "Índice atômico do hidrogênio.", "B": "Coeficiente estequiométrico, que indica a proporção de moléculas/mols formados.", "C": "Número de oxidação do oxigênio.", "D": "Grau de dissociação iônica do composto.", "E": "Volume em litros da solução líquida."}, "resposta_correta": "B", "justificativa": "O número à frente da fórmula química é o coeficiente estequiométrico e indica a proporção relativa de entidades participantes da reação.", "possui_imagem": true},
  {"id": 111, "uid": "CIEN-9-111", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Diferença entre Índice e Coeficiente", "dificuldade": "Fácil", "enunciado": "Ao balancear uma equação química, uma regra fundamental de conservação da identidade das substâncias é:", "alternativas": {"A": "Alterar os índices das fórmulas para igualar os átomos rapidamente.", "B": "Alterar apenas os coeficientes estequiométricos, mantendo os índices das fórmulas inalterados.", "C": "Multiplicar os índices atômicos por zero se houver excesso de oxigênio.", "D": "Transformar elementos metálicos em ametais.", "E": "Eliminar elementos que apareçam apenas nos reagentes."}, "resposta_correta": "B", "justificativa": "Nunca se alteram os índices das fórmulas químicas (que definiriam outra substância), ajustando-se exclusivamente os coeficientes estequiométricos.", "possui_imagem": false},
  {"id": 112, "uid": "CIEN-9-112", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação de Simples Troca", "dificuldade": "Fácil", "enunciado": "A reação representada por Zn(s) + 2 HCl(aq) → ZnCl2(aq) + H2(g), na qual uma substância simples reage com uma composta gerando uma nova substância simples e outra composta, é denominada:", "alternativas": {"A": "Dupla troca.", "B": "Simples troca (ou deslocamento).", "C": "Síntese total.", "D": "Decomposição térmica.", "E": "Fotólise."}, "resposta_correta": "B", "justificativa": "Trata-se de uma reação de simples troca (ou deslocamento), de padrão geral A + BC → AC + B.", "possui_imagem": true},
  {"id": 113, "uid": "CIEN-9-113", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação de Dupla Troca", "dificuldade": "Fácil", "enunciado": "Quando soluções aquosas de cloreto de sódio e nitrato de prata são misturadas, observa-se a reação: NaCl(aq) + AgNO3(aq) → AgCl(s) + NaNO3(aq). Essa reação classifica-se como:", "alternativas": {"A": "Simples troca.", "B": "Dupla troca.", "C": "Síntese.", "D": "Decomposição.", "E": "Eletrólise."}, "resposta_correta": "B", "justificativa": "Duas substâncias compostas permutaram cátions e ânions entre si, gerando duas novas substâncias compostas (padrão AB + CD → AD + CB).", "possui_imagem": false},
  {"id": 114, "uid": "CIEN-9-114", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Eletrólise da Água - Aspecto Básico", "dificuldade": "Fácil", "enunciado": "A eletrólise da água é uma reação química provocada pela passagem de corrente elétrica, que quebra as moléculas de água líquida produzindo:", "alternativas": {"A": "Gás oxigênio (O2) e gás hidrogênio (H2).", "B": "Gás carbônico (CO2) e monóxido de carbono (CO).", "C": "Ozônio (O3) e água oxigenada (H2O2).", "D": "Ácido clorídrico e hidróxido de sódio.", "E": "Vapor de água e gelo."}, "resposta_correta": "A", "justificativa": "A eletrólise da água decompõe o líquido em suas substâncias simples formadoras: 2 H2O(l) → 2 H2(g) + O2(g).", "possui_imagem": false},
  {"id": 115, "uid": "CIEN-9-115", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Sistema Aberto vs. Fechado", "dificuldade": "Fácil", "enunciado": "Ao queimar 10 g de palha de aço em um prato aberto sobre uma balança, verifica-se que a massa final indicada é maior que 10 g. Esse aumento aparente de massa deve-se ao fato de que:", "alternativas": {"A": "A balança sofreu interferência gravitacional do fogo.", "B": "O ferro reagiu com o oxigênio do ar atmosférico, incorporando átomos de oxigênio na ferrugem formada.", "C": "A queima criou novos átomos de ferro do nada.", "D": "O nitrogênio do ar se transformou em carbono sólido.", "E": "A Lei de Lavoisier não se aplica a metais."}, "resposta_correta": "B", "justificativa": "Em sistema aberto, o ferro reage com o oxigênio gasoso do ar: 4 Fe + 3 O2 → 2 Fe2O3. A massa do oxigênio incorporado explica o ganho de massa aparente.", "possui_imagem": false},
  {"id": 116, "uid": "CIEN-9-116", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação Exotérmica vs. Endotérmica", "dificuldade": "Fácil", "enunciado": "Reações químicas que liberam calor para o ambiente, como a combustão da madeira ou da queima do gás de cozinha, são denominadas:", "alternativas": {"A": "Endotérmicas.", "B": "Exotérmicas.", "C": "Atermáticas.", "D": "Isoméricas.", "E": "Reversíveis puras."}, "resposta_correta": "B", "justificativa": "Reações exotérmicas liberam calor para o meio ambiente durante sua ocorrência.", "possui_imagem": false},
  {"id": 117, "uid": "CIEN-9-117", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Aplicação da Lei de Lavoisier", "dificuldade": "Médio", "enunciado": "Em um recipiente fechado e selado, 12 g de carbono sólido reagem completamente com 32 g de gás oxigênio, produzindo gás carbônico como único produto. Qual é a massa de gás carbônico obtida?", "alternativas": {"A": "20 g.", "B": "32 g.", "C": "44 g.", "D": "56 g.", "E": "24 g."}, "resposta_correta": "C", "justificativa": "Pela Lei de Lavoisier (sistema fechado): Massa dos reagentes = Massa dos produtos. Assim, 12 g (C) + 32 g (O2) = 44 g de CO2.", "possui_imagem": false},
  {"id": 118, "uid": "CIEN-9-118", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Aplicação Combinada Lavoisier e Proust", "dificuldade": "Médio", "enunciado": "Sabendo que 4 g de gás hidrogênio reagem com 32 g de gás oxigênio formando 36 g de água, qual massa de gás oxigênio seria necessária para reagir completamente com 10 g de gás hidrogênio?", "alternativas": {"A": "40 g.", "B": "64 g.", "C": "80 g.", "D": "100 g.", "E": "16 g."}, "resposta_correta": "C", "justificativa": "A proporção em massa H2 : O2 é 4 g : 32 g = 1 : 8. Portanto, para 10 g de H2, necessita-se de 10 × 8 = 80 g de O2.", "possui_imagem": false},
  {"id": 119, "uid": "CIEN-9-119", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento da Combustão do Metano", "dificuldade": "Médio", "enunciado": "Considere a reação de combustão completa do gás metano representada de forma incompleta: CH4 + x O2 → y CO2 + z H2O. Os coeficientes estequiométricos x, y e z que tornam a equação corretamente balanceada são, respectivamente:", "alternativas": {"A": "x = 1, y = 1, z = 2.", "B": "x = 2, y = 1, z = 2.", "C": "x = 2, y = 2, z = 1.", "D": "x = 3, y = 1, z = 4.", "E": "x = 4, y = 2, z = 2."}, "resposta_correta": "B", "justificativa": "Reagentes: 1 C, 4 H, 2×2=4 O. Produtos: 1 C (em CO2), 2 H2O (com 4 H e 2 O) + 2 O (em CO2) = 4 O. Equação balanceada: 1 CH4 + 2 O2 → 1 CO2 + 2 H2O.", "possui_imagem": false},
  {"id": 120, "uid": "CIEN-9-120", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento da Síntese da Amônia", "dificuldade": "Médio", "enunciado": "No processo Haber-Bosch para produção de amônia, ocorre a reação: N2 + H2 → NH3. Para que a equação obedeça à Lei de Lavoisier com os menores números inteiros possíveis, os coeficientes de N2, H2 e NH3 devem ser:", "alternativas": {"A": "1, 1 e 1.", "B": "1, 3 e 2.", "C": "2, 3 e 2.", "D": "1, 2 e 3.", "E": "2, 6 e 4."}, "resposta_correta": "B", "justificativa": "Balanceando o nitrogênio: 1 N2 fornece 2 NH3. Para equilibrar os 6 átomos de hidrogênio gerados (2×3), são necessárias 3 moléculas de H2. Coeficientes: 1 N2 + 3 H2 → 2 NH3.", "possui_imagem": false},
  {"id": 121, "uid": "CIEN-9-121", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Eletrólise da Água - Proporção Volumétrica", "dificuldade": "Médio", "enunciado": "Durante a eletrólise da água acidulada em um voltâmetro de Hoffman (2 H2O → 2 H2 + O2), recolhem-se os gases formados em tubos graduados. A razão entre o volume de gás hidrogênio e o volume de gás oxigênio recolhidos é de:", "alternativas": {"A": "1 : 1.", "B": "2 : 1.", "C": "1 : 2.", "D": "4 : 1.", "E": "3 : 1."}, "resposta_correta": "B", "justificativa": "Pela equação balanceada 2 H2O(l) → 2 H2(g) + 1 O2(g), a cada 2 mols de H2(g) produz-se 1 mol de O2(g). Pela Lei de Avogadro, o volume de H2 é o dobro do volume de O2 (proporção 2:1).", "possui_imagem": true},
  {"id": 122, "uid": "CIEN-9-122", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Classificação de Reação Redox / Deslocamento", "dificuldade": "Médio", "enunciado": "Analise a equação química a seguir: Fe(s) + CuSO4(aq) → FeSO4(aq) + Cu(s). Essa reação, em que o ferro metálico desloca o cobre da solução de sulfato de cobre, é classificada como:", "alternativas": {"A": "Síntese total.", "B": "Decomposição por pirólise.", "C": "Deslocamento ou simples troca.", "D": "Dupla troca com formação de gás.", "E": "Polimerização iônica."}, "resposta_correta": "C", "justificativa": "O metal ferro (substância simples) substitui o cátion cobre no sal (substância composta), caracterizando uma simples troca ou deslocamento.", "possui_imagem": false},
  {"id": 123, "uid": "CIEN-9-123", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Previsão de Ocorrência de Dupla Troca", "dificuldade": "Médio", "enunciado": "Para que uma reação de dupla troca ocorra de fato em meio aquoso entre dois eletrólitos, é necessário que haja pelo menos uma das seguintes condições:", "alternativas": {"A": "Formação de um composto insolúvel (precipitado), volátil (gás) ou menos ionizado (como a água).", "B": "Aumento da temperatura para mais de 500 °C.", "C": "Presença de oxigênio puro a alta pressão.", "D": "Que ambos os produtos sejam solúveis e totalmente dissociados.", "E": "Que ocorra quebra de núcleos atômicos."}, "resposta_correta": "A", "justificativa": "Reações de dupla troca ocorrem se houver 'força propulsora': formação de precipitado (insolúvel), gás (volátil) ou eletrólito fraco/água.", "possui_imagem": false},
  {"id": 124, "uid": "CIEN-9-124", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento com Óxidos de Ferro", "dificuldade": "Médio", "enunciado": "A reação de redução do minério de ferro em alto-forno pode ser simplificada pela equação: Fe2O3 + CO → Fe + CO2. Ajustando os coeficientes estequiométricos com os menores inteiros possíveis, a soma desses coeficientes é:", "alternativas": {"A": "6.", "B": "7.", "C": "8.", "D": "9.", "E": "10."}, "resposta_correta": "D", "justificativa": "Equação balanceada: 1 Fe2O3 + 3 CO → 2 Fe + 3 CO2. Soma dos coeficientes: 1 + 3 + 2 + 3 = 9.", "possui_imagem": false},
  {"id": 125, "uid": "CIEN-9-125", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Lei de Lavoisier em Recipiente Aberto com Efervescência", "dificuldade": "Médio", "enunciado": "Um comprimido efervescente de 5 g é dissolvido em um copo contendo 100 g de água sobre uma balança aberta. Ao final da efervescência, a balança registra 103,5 g. A explicação científica para a leitura de massa final é:", "alternativas": {"A": "A balança errou a medição por falta de calibração.", "B": "Houve destruição de matéria durante a reação química.", "C": "1,5 g de gás carbônico escapou para a atmosfera durante a efervescência.", "D": "A água absorveu massa do ar ambiente.", "E": "O comprimido sofreu desintegração radioativa espontânea."}, "resposta_correta": "C", "justificativa": "A massa inicial total era 5 g + 100 g = 105 g. Como o sistema era aberto, 105 g - 103,5 g = 1,5 g de CO2 escapou em forma gasosa, mantendo a Lei de Lavoisier rigorosamente válida.", "possui_imagem": false},
  {"id": 126, "uid": "CIEN-9-126", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Excesso de Reagente e Lei de Proust", "dificuldade": "Médio", "enunciado": "Sabe-se que 6 g de magnésio metálico reagem com 4 g de gás oxigênio para formar 10 g de óxido de magnésio. Se colocarmos 6 g de magnésio para reagir com 7 g de gás oxigênio em recipiente fechado, obteremos:", "alternativas": {"A": "13 g de óxido de magnésio e nenhum reagente sobrando.", "B": "10 g de óxido de magnésio e 3 g de oxigênio em excesso.", "C": "17 g de óxido de magnésio.", "D": "12 g de óxido de magnésio e 1 g de magnésio em excesso.", "E": "7 g de óxido de magnésio e 6 g de oxigênio restante."}, "resposta_correta": "B", "justificativa": "O magnésio é o reagente limitante (6 g consome exatamente 4 g de O2, gerando 10 g de MgO). Dos 7 g de O2 fornecidos, 4 g reagem e 3 g sobram como excesso.", "possui_imagem": false},
  {"id": 127, "uid": "CIEN-9-127", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento da Combustão do Etanol", "dificuldade": "Médio", "enunciado": "O etanol (C2H6O) sofre combustão completa de acordo com a equação: C2H6O(l) + x O2(g) → y CO2(g) + z H2O(g). Os valores dos coeficientes x, y e z são, respectivamente:", "alternativas": {"A": "x = 2, y = 2, z = 3.", "B": "x = 3, y = 2, z = 3.", "C": "x = 3, y = 1, z = 2.", "D": "x = 7/2, y = 2, z = 3.", "E": "x = 4, y = 2, z = 4."}, "resposta_correta": "B", "justificativa": "C2H6O possui 2 C (exige 2 CO2) e 6 H (exige 3 H2O). Nos produtos temos 2×2 + 3×1 = 7 átomos de O. Como o C2H6O já fornece 1 átomo de O, restam 6 átomos a serem supridos pelo O2, exigindo 3 O2. Portanto: 1 C2H6O + 3 O2 → 2 CO2 + 3 H2O.", "possui_imagem": false},
  {"id": 128, "uid": "CIEN-9-128", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Identificação de Agente Oxidante e Redutor", "dificuldade": "Médio", "enunciado": "Na reação de simples troca Zn(s) + 2 Ag+(aq) → Zn2+(aq) + 2 Ag(s), o zinco passa de número de oxidação 0 para +2, enquanto a prata passa de +1 para 0. Nesse processo:", "alternativas": {"A": "O zinco ganha elétrons e a prata perde elétrons.", "B": "O zinco oxida-se (perde elétrons) e a prata reduz-se (ganha elétrons).", "C": "Ambas as espécies sofrem oxidação simultânea.", "D": "O número total de elétrons diminui no sistema.", "E": "A prata atua como agente redutor."}, "resposta_correta": "B", "justificativa": "Oxidação é a perda de elétrons (aumento do Nox: Zn0 → Zn2+). Redução é o ganho de elétrons (diminuição do Nox: Ag+ → Ag0).", "possui_imagem": false},
  {"id": 129, "uid": "CIEN-9-129", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Classificação de Decomposições Específicas", "dificuldade": "Médio", "enunciado": "A decomposição de uma substância provocada pela ação do calor, da luz e da corrente elétrica recebem denominações específicas, respectivamente:", "alternativas": {"A": "Pirólise, fotólise e eletrólise.", "B": "Fotólise, eletrólise e pirólise.", "C": "Eletrólise, pirólise e hidrólise.", "D": "Hidrólise, fotólise e combustão.", "E": "Termólise, combustão e calcinação."}, "resposta_correta": "A", "justificativa": "Decomposição por calor é pirólise (ou termólise); por luz é fotólise; por eletricidade é eletrólise.", "possui_imagem": false},
  {"id": 130, "uid": "CIEN-9-130", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento por Tentativas com Parênteses", "dificuldade": "Médio", "enunciado": "Considere a reação: Al(OH)3 + H2SO4 → Al2(SO4)3 + H2O. Após balancear a equação com os menores coeficientes inteiros, os coeficientes de Al(OH)3 e H2O são, respectivamente:", "alternativas": {"A": "1 e 3.", "B": "2 e 6.", "C": "2 e 3.", "D": "3 e 6.", "E": "1 e 6."}, "resposta_correta": "B", "justificativa": "Para Al2(SO4)3, precisamos de 2 Al(OH)3 e 3 H2SO4. Os hidrogênios: 2×3 + 3×2 = 12 H, formando 6 H2O. Equação balanceada: 2 Al(OH)3 + 3 H2SO4 → 1 Al2(SO4)3 + 6 H2O.", "possui_imagem": false},
  {"id": 131, "uid": "CIEN-9-131", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Conservação de Cargas em Equações Iônicas", "dificuldade": "Médio", "enunciado": "Além da conservação do número de átomos, uma equação química que envolve espécies iônicas deve necessariamente respeitar:", "alternativas": {"A": "O princípio de que a carga total dos reagentes deve ser igual à carga total dos produtos.", "B": "A obrigatoriedade de todas as espécies terem carga zero.", "C": "O cancelamento de todos os cátions presentes.", "D": "A transformação de todos os elétrons em nêutrons.", "E": "A manutenção exclusiva de compostos apolares."}, "resposta_correta": "A", "justificativa": "Em equações iônicas, o princípio da conservação da carga elétrica exige que a soma algébrica das cargas elétricas nos reagentes seja idêntica à soma nos produtos.", "possui_imagem": false},
  {"id": 132, "uid": "CIEN-9-132", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Velocidade de Reação e Teoria das Colisões", "dificuldade": "Médio", "enunciado": "Para que uma reação química ocorra em nível molecular, é fundamental que as partículas reagentes colidam entre si. De acordo com a Teoria das Colisões, a colisão será efetiva se possuir:", "alternativas": {"A": "Orientação espacial adequada e energia igual ou superior à energia de ativação.", "B": "Apenas velocidade máxima, independentemente do ângulo de contato.", "C": "Cargas elétricas exatamente iguais para gerar repulsão atômica.", "D": "Massa molecular nula e volume infinito.", "E": "Temperatura absoluta próxima de zero Kelvin."}, "resposta_correta": "A", "justificativa": "Uma colisão eficaz requer geometria espacial favorável e energia cinética mínima suficiente (energia de ativação) para romper ligações existentes.", "possui_imagem": false},
  {"id": 133, "uid": "CIEN-9-133", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Fatores que Afetam a Velocidade", "dificuldade": "Médio", "enunciado": "Um estudante dissolveu um comprimido efervescente inteiro em um copo de água fria e outro comprimido triturado em um copo de água morna. A reação ocorreu muito mais rapidamente no segundo copo porque:", "alternativas": {"A": "A menor área de contato e a menor temperatura aceleram as colisões.", "B": "O aumento da superfície de contato (trituração) e o aumento da temperatura aumentam a frequência e energia das colisões efetivas.", "C": "A água morna destrói o gás carbônico antes que ele se forme.", "D": "A trituração converte a reação em um processo puramente físico.", "E": "A água fria neutraliza o ácido cítrico do comprimido."}, "resposta_correta": "B", "justificativa": "Triturar o sólido aumenta a superfície de contato; aquecer a água aumenta a energia cinética média das moléculas, elevando drasticamente a frequência de choques efetivos.", "possui_imagem": false},
  {"id": 134, "uid": "CIEN-9-134", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Cálculo Estequiométrico Baseado em Proust", "dificuldade": "Difícil", "enunciado": "Três experimentos foram realizados para a síntese da amônia a partir de nitrogênio e hidrogênio (N2 + 3 H2 → 2 NH3):\n- Exp 1: 28 g de N2 reagem com 6 g de H2 formando 34 g de NH3.\n- Exp 2: 56 g de N2 reagem com X g de H2 formando Y g de NH3.\n- Exp 3: Z g de N2 reagem com 18 g de H2 formando W g de NH3.\nOs valores de X, Y, Z e W são, respectivamente:", "alternativas": {"A": "X = 12 g, Y = 68 g, Z = 84 g, W = 102 g.", "B": "X = 6 g, Y = 62 g, Z = 56 g, W = 74 g.", "C": "X = 14 g, Y = 70 g, Z = 70 g, W = 88 g.", "D": "X = 12 g, Y = 48 g, Z = 28 g, W = 46 g.", "E": "X = 18 g, Y = 74 g, Z = 84 g, W = 108 g."}, "resposta_correta": "A", "justificativa": "Pela Lei de Proust, a razão N2:H2:NH3 é 28:6:34 (ou 14:3:17). No Exp 2, duplicou-se N2 (56 g), logo X = 12 g de H2 e Y = 68 g de NH3. No Exp 3, triplicou-se H2 (18 g), logo Z = 28×3 = 84 g de N2 e W = 34×3 = 102 g de NH3.", "possui_imagem": false},
  {"id": 135, "uid": "CIEN-9-135", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Combustão em Recipiente Fechado e Pressão", "dificuldade": "Difícil", "enunciado": "Em um cilindro rígido de volume constante e fechado, queima-se completamente 1 mol de gás propano com oxigênio suficiente: C3H8(g) + 5 O2(g) → 3 CO2(g) + 4 H2O(g). Se a temperatura for mantida constante acima de 100 °C (para que a água permaneça no estado de vapor), a pressão total interna do cilindro após a reação, em relação à pressão inicial dos reagentes gasosos, terá:", "alternativas": {"A": "Diminuído em 50%.", "B": "Permanecido exatamente a mesma.", "C": "Aumentado, pois o número total de mols de gases aumentou de 6 mols para 7 mols.", "D": "Caído a zero devido ao consumo de combustível.", "E": "Aumentado em mais de 300%."}, "resposta_correta": "C", "justificativa": "Reagentes gasosos: 1 mol de C3H8 + 5 mols de O2 = 6 mols de gás. Produtos gasosos: 3 mols de CO2 + 4 mols de H2O = 7 mols de gás. Pela equação dos gases ideais (PV = nRT), a T e V constantes, o aumento de mols de gás (de 6 para 7) acarreta aumento proporcional da pressão.", "possui_imagem": false},
  {"id": 136, "uid": "CIEN-9-136", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Análise de Tabela de Leis Ponderais com Resíduo", "dificuldade": "Difícil", "enunciado": "Considere a reação: 2 Mg(s) + O2(g) → 2 MgO(s). Em um ensaio, 48 g de Mg reagiram com 40 g de O2 em sistema fechado. Sabendo que a proporção em massa de combinação entre magnésio e oxigênio é rigorosamente de 3 : 2, determine a massa final total contida no recipiente após o término da reação:", "alternativas": {"A": "80 g.", "B": "88 g.", "C": "48 g.", "D": "40 g.", "E": "96 g."}, "resposta_correta": "B", "justificativa": "Pela Lei de Lavoisier, em sistema fechado, a massa total presente no recipiente após a reação é rigorosamente a soma das massas adicionadas inicialmente: 48 g + 40 g = 88 g (composta por 80 g de MgO formado e 8 g de O2 em excesso).", "possui_imagem": false},
  {"id": 137, "uid": "CIEN-9-137", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanceamento Algébrico Complexo", "dificuldade": "Difícil", "enunciado": "Considere a equação de oxirredução não balanceada: a Cu + b HNO3 → c Cu(NO3)2 + d NO + e H2O. Utilizando os menores coeficientes inteiros que satisfazem o balanço de massa e elétrons, os valores de a, b, c, d e e são:", "alternativas": {"A": "a = 1, b = 4, c = 1, d = 2, e = 2.", "B": "a = 3, b = 8, c = 3, d = 2, e = 4.", "C": "a = 3, b = 6, c = 3, d = 1, e = 3.", "D": "a = 2, b = 6, c = 2, d = 2, e = 3.", "E": "a = 1, b = 8, c = 1, d = 2, e = 4."}, "resposta_correta": "B", "justificativa": "Cu oxida de 0 para +2 (perde 2 e-), N reduz de +5 para +2 em NO (ganha 3 e-). Invertendo variações: 3 Cu e 2 NO. Nos produtos: 3 Cu(NO3)2 possuem 6 NO3-. Somando com os 2 N de NO, totalizam-se 8 HNO3. Balanceando hidrogênio: 8 H exigem 4 H2O. Equação balanceada: 3 Cu + 8 HNO3 → 3 Cu(NO3)2 + 2 NO + 4 H2O.", "possui_imagem": false},
  {"id": 138, "uid": "CIEN-9-138", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Interpretação Microscópica da Conservação de Massa", "dificuldade": "Difícil", "enunciado": "Por que a hipótese atômica formulada por John Dalton em 1808 conseguiu fornecer uma explicação teórica microscópica perfeita para a Lei de Conservação da Massa de Lavoisier?", "alternativas": {"A": "Porque Dalton propôs que átomos se dividem em partículas subatômicas que dissipam calor.", "B": "Porque Dalton postulou que átomos são indestrutíveis e indivisíveis em transformações químicas, ocorrendo apenas sua separação, combinação ou rearranjo.", "C": "Porque Dalton descobriu os elétrons livres e sua massa desprezível.", "D": "Porque Dalton demonstrou que as reações químicas criam novos núcleos atômicos a cada choque.", "E": "Porque Dalton provou que a massa atômica varia de acordo com o estado físico da matéria."}, "resposta_correta": "B", "justificativa": "Se os átomos de cada elemento são indestrutíveis e mantêm sua massa fixa durante as reações químicas, rearranjando-se para formar novas moléculas, a massa total antes e depois do processo deve ser rigorosamente a mesma.", "possui_imagem": false},
  {"id": 139, "uid": "CIEN-9-139", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação com Formação de Gás e Efervescência", "dificuldade": "Difícil", "enunciado": "Ao misturar ácido clorídrico (HCl) e bicarbonato de sódio (NaHCO3), a reação ocorre em duas etapas imediatas:\nEtapa 1: HCl + NaHCO3 → NaCl + H2CO3\nEtapa 2: H2CO3 → H2O + CO2\nA equação global desse processo e a justificativa para a efervescência observada são:", "alternativas": {"A": "HCl + NaHCO3 → NaCl + H2O + CO2; a efervescência decorre do desprendimento rápido de CO2 gasoso proveniente da instabilidade do ácido carbônico.", "B": "HCl + NaHCO3 → NaH + ClCO3; a efervescência decorre da condensação de água pura.", "C": "2 HCl + NaHCO3 → NaCl2 + CO2; a efervescência decorre da fervura do HCl.", "D": "HCl + NaHCO3 → NaO + HCl2; a efervescência decorre do consumo de oxigênio.", "E": "HCl + NaHCO3 → NaCl + 2 H2O; a efervescência é gerada pelo vapor de água."}, "resposta_correta": "A", "justificativa": "O ácido carbônico (H2CO3) formado na dupla troca é extremamente instável e decompõe-se espontaneamente em H2O e CO2 gasoso, cuja liberação rápida produz a efervescência.", "possui_imagem": false},
  {"id": 140, "uid": "CIEN-9-140", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Determinação de Reagente Limitante e Rendimento", "dificuldade": "Difícil", "enunciado": "Considere a reação balanceada: 2 Al + 3 Cl2 → 2 AlCl3. Em um laboratório, misturam-se 54 g de alumínio (massa molar = 27 g/mol) e 213 g de cloro (massa molar de Cl2 = 71 g/mol). Sabendo que 1 mol de Al reage com 1,5 mol de Cl2:\nQual é o reagente limitante e qual a massa máxima teórica de AlCl3 (massa molar = 133,5 g/mol) que pode ser formada?", "alternativas": {"A": "O alumínio é limitante e formam-se 133,5 g de AlCl3.", "B": "O cloro é limitante e formam-se 200 g de AlCl3.", "C": "Ambos os reagentes estão em proporção estequiométrica exata e formam-se 267 g de AlCl3.", "D": "O alumínio está em excesso de 27 g.", "E": "O cloro está em excesso de 100 g."}, "resposta_correta": "C", "justificativa": "Temos 54/27 = 2 mols de Al e 213/71 = 3 mols de Cl2. A proporção estequiométrica exata da reação é de 2 mols de Al para 3 mols de Cl2. Portanto, não há excesso; formam-se exatamente 2 mols de AlCl3, equivalentes a 2 × 133,5 g = 267 g.", "possui_imagem": false},
  {"id": 141, "uid": "CIEN-9-141", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Classificação e Balanceamento da Respiração Celular", "dificuldade": "Difícil", "enunciado": "A respiração celular pode ser resumida pela reação química: C6H12O6 + 6 O2 → 6 CO2 + 6 H2O + energia. Sob o ponto de vista termoquímico e de classificação, esse processo biológico fundamental é:", "alternativas": {"A": "Uma reação endotérmica de síntese de matéria orgânica.", "B": "Uma reação exotérmica de oxirredução onde a glicose é oxidada pelo oxigênio.", "C": "Uma reação de simples troca puramente anaeróbica.", "D": "Um fenômeno físico de evaporação de açúcares.", "E": "Uma reação de dupla troca sem variação de energia."}, "resposta_correta": "B", "justificativa": "A oxidação da glicose pelo O2 degrada a molécula orgânica liberando energia livre (exotérmica/exergônica) armazenada na forma de ATP.", "possui_imagem": false},
  {"id": 142, "uid": "CIEN-9-142", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanço de Equação de Combustão de Hidrocarboneto Geral", "dificuldade": "Difícil", "enunciado": "Para um alcano genérico de fórmula molecular CnH2n+2, o coeficiente estequiométrico do gás oxigênio (O2) necessário para sua combustão completa, em termos de n, é expresso por:", "alternativas": {"A": "(3n + 1) / 2.", "B": "(2n + 1) / 2.", "C": "3n / 2.", "D": "n + 1.", "E": "2n + 2."}, "resposta_correta": "A", "justificativa": "Equação geral: CnH2n+2 + x O2 → n CO2 + (n + 1) H2O. O total de átomos de O nos produtos é 2n (em CO2) + (n + 1) (em H2O) = 3n + 1. Como cada molécula de O2 possui 2 átomos, x = (3n + 1)/2.", "possui_imagem": false},
  {"id": 143, "uid": "CIEN-9-143", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Energia de Ativação e Ação de Catalisadores", "dificuldade": "Difícil", "enunciado": "Em sistemas químicos e biológicos (enzimas), a adição de um catalisador acelera a velocidade da reação porque:", "alternativas": {"A": "Aumenta a energia total liberada (entalpia) pelos reagentes.", "B": "Diminui a energia de ativação necessária, fornecendo um caminho reacional alternativo.", "C": "Aumenta a massa final de produtos obtidos.", "D": "Impede colisões moleculares que liberam calor.", "E": "Desloca o equilíbrio destruindo os reagentes."}, "resposta_correta": "B", "justificativa": "O catalisador não é consumido e acelera a reação ao diminuir a energia de ativação requerida para atingir o complexo ativado, sem alterar a variação de energia global (ΔH).", "possui_imagem": false},
  {"id": 144, "uid": "CIEN-9-144", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Diferença entre Fusão Nuclear e Reação Química", "dificuldade": "Difícil", "enunciado": "A combustão do carvão é uma reação química, enquanto a geração de energia no interior do Sol ocorre por fusão nuclear. A diferença fundamental entre esses dois tipos de processos em relação aos núcleos atômicos e à conservação da massa é que:", "alternativas": {"A": "Em reações químicas, os núcleos atômicos permanecem inalterados e a massa se conserva estritamente; na fusão nuclear, núcleos se fundem e parte da massa é convertida em energia (E = mc²).", "B": "Em reações químicas há destruição de prótons, enquanto na fusão nuclear os prótons são apenas resfriados.", "C": "Reações químicas liberam muito mais energia por grama do que reações nucleares.", "D": "Em fusões nucleares não há participação de nêutrons ou prótons.", "E": "A Lei de Lavoisier aplica-se rigorosamente a fusões nucleares, mas não a reações químicas."}, "resposta_correta": "A", "justificativa": "Reações químicas envolvem rearranjo de elétrons da eletrosfera sem alteração nuclear (núcleos preservados). Em reações nucleares, núcleos atômicos sofrem fusão ou fissão com defeito de massa convertido em energia.", "possui_imagem": false},
  {"id": 145, "uid": "CIEN-9-145", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Reação de Termita e Poder Redutor", "dificuldade": "Difícil", "enunciado": "A reação de aluminotermia (termita), representada por 2 Al(s) + Fe2O3(s) → Al2O3(s) + 2 Fe(l) + calor intenso, é empregada na soldagem de trilhos ferroviários. Essa reação ocorre espontaneamente após ignição inicial porque:", "alternativas": {"A": "O alumínio possui menor afinidade pelo oxigênio que o ferro.", "B": "O alumínio é mais reativo que o ferro e possui maior potencial de oxidação, deslocando o ferro de seu óxido de forma extremamente exotérmica.", "C": "O óxido de ferro é uma base fraca que se decompõe na água.", "D": "O ferro metálico dissolve o óxido de alumínio em temperatura ambiente.", "E": "Trata-se de uma reação endotérmica que absorve calor do solo."}, "resposta_correta": "B", "justificativa": "O alumínio é mais eletropositivo e redutor que o ferro (fila de reatividade dos metais). Assim, o Al desloca o Fe do óxido em uma reação de simples troca altamente exotérmica capaz de fundir o ferro gerado.", "possui_imagem": false},
  {"id": 146, "uid": "CIEN-9-146", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Neutralização Parcial vs. Total", "dificuldade": "Difícil", "enunciado": "Considere a reação entre 1 mol de ácido fosfórico (H3PO4) e 2 mols de hidróxido de sódio (NaOH) em meio aquoso. O sal formado e a classificação dessa reação são:", "alternativas": {"A": "Na3PO4 (fosfato de sódio), neutralização total.", "B": "Na2HPO4 (hidrogenofosfato de sódio), neutralização parcial.", "C": "NaH2PO4 (di-hidrogenofosfato de sódio), neutralização ácida total.", "D": "NaPO3 (metafosfato de sódio), decomposição.", "E": "NaCl (cloreto de sódio), síntese."}, "resposta_correta": "B", "justificativa": "H3PO4 possui 3 hidrogênios ionizáveis. Reagindo com apenas 2 OH- (de 2 NaOH), neutralizam-se 2 H+, restando 1 H+ no ânion salino: H3PO4 + 2 NaOH → Na2HPO4 + 2 H2O. O sal formado é o hidrogenofosfato de sódio (neutralização parcial).", "possui_imagem": false},
  {"id": 147, "uid": "CIEN-9-147", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Estudo Cinético e Gráfico de Concentração", "dificuldade": "Difícil", "enunciado": "Ao acompanhar a decomposição do peróxido de hidrogênio (2 H2O2 → 2 H2O + O2), mede-se a concentração do reagente em função do tempo. Observa-se que a curva de concentração de H2O2 decresce mais rapidamente no início e vai ficando menos inclinada com o passar do tempo. Isso se justifica porque:", "alternativas": {"A": "A temperatura do sistema cai até o zero absoluto.", "B": "A concentração de reagente diminui com o tempo, reduzindo o número de colisões entre as moléculas reagentes por unidade de tempo.", "C": "O oxigênio formado atua como inibidor irreversível da reação.", "D": "A água produzida evapora, resfriando o recipiente.", "E": "A massa total dos reagentes aumenta no final."}, "resposta_correta": "B", "justificativa": "A velocidade instantânea de uma reação é proporcional à concentração dos reagentes. À medida que o H2O2 é consumido, há menor frequência de choques efetivos, diminuindo a velocidade do processo.", "possui_imagem": false},
  {"id": 148, "uid": "CIEN-9-148", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Identificação de Precipitado em Dupla Troca", "dificuldade": "Difícil", "enunciado": "Ao misturar soluções aquosas incolores de nitrato de chumbo II [Pb(NO3)2] e iodeto de potássio (KI), forma-se imediatamente um precipitado amarelo brilhante insolúvel. A equação química balanceada correta e a identificação do precipitado são:", "alternativas": {"A": "Pb(NO3)2(aq) + KI(aq) → PbI(s) + KNO3(aq); precipitado é o KNO3.", "B": "Pb(NO3)2(aq) + 2 KI(aq) → PbI2(s) + 2 KNO3(aq); precipitado amarelo é o iodeto de chumbo II (PbI2).", "C": "Pb(NO3)2(aq) + 2 KI(aq) → PbK2(s) + 2 INO3(aq); precipitado é o PbK2.", "D": "2 PbNO3(aq) + KI2(aq) → Pb2I(s) + 2 KNO3(aq); precipitado é o iodeto de potássio.", "E": "Pb(NO3)2(aq) + KI(aq) → Pb(s) + I2(s) + KNO3(aq); precipitado é o chumbo metálico."}, "resposta_correta": "B", "justificativa": "A reação de dupla troca gera iodeto de chumbo II (PbI2), que é insolúvel em água e tem cor amarela intensa característica, e nitrato de potássio (KNO3), que permanece solúvel.", "possui_imagem": false},
  {"id": 149, "uid": "CIEN-9-149", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Cálculo de Composição Centesimal e Proust", "dificuldade": "Difícil", "enunciado": "Sabe-se que 100 g de carbonato de cálcio puro (CaCO3) decompõem-se termicamente formando 56 g de óxido de cálcio (CaO) e 44 g de gás carbônico (CO2). Se 250 g de carbonato de cálcio contendo 20% de impurezas inertes forem calcinados até decomposição completa, qual será a massa de CO2 gasoso liberada?", "alternativas": {"A": "110 g.", "B": "88 g.", "C": "44 g.", "D": "56 g.", "E": "200 g."}, "resposta_correta": "B", "justificativa": "Em 250 g de amostra com 20% de impurezas, a pureza é 80%. Massa de CaCO3 puro = 250 × 0,80 = 200 g. Como 100 g de CaCO3 produzem 44 g de CO2, 200 g produzirão 200 × (44/100) = 88 g de CO2.", "possui_imagem": false},
  {"id": 150, "uid": "CIEN-9-150", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 17: Reações Químicas, Balanceamento e Leis Ponderais", "tema": "Balanço Mássico e Lei das Proporções Múltiplas", "dificuldade": "Difícil", "enunciado": "O carbono combina-se com o oxigênio formando dois gases distintos: monóxido de carbono (CO) e dióxido de carbono (CO2). Em CO, 12 g de carbono combinam-se com 16 g de oxigênio; em CO2, 12 g de carbono combinam-se com 32 g de oxigênio. A relação entre as massas de oxigênio (16 g e 32 g) para a mesma massa de carbono (12 g) é de 1 : 2. Essa regularidade matemática exemplifica a:", "alternativas": {"A": "Lei das Proporções Múltiplas de Dalton.", "B": "Lei das Proporções Recíprocas de Richter.", "C": "Lei Volumétrica de Gay-Lussac.", "D": "Lei da Indestrutibilidade da Matéria.", "E": "Lei dos Gases Ideais de Boyle-Mariotte."}, "resposta_correta": "A", "justificativa": "A Lei de Dalton (Proporções Múltiplas) estabelece que quando dois elementos formam mais de um composto, as massas do segundo que se combinam com uma massa fixa do primeiro estão entre si numa relação de números inteiros e pequenos (16:32 = 1:2).", "possui_imagem": false},
  {"id": 151, "uid": "CIEN-9-151", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Conceito de Biodiversidade", "dificuldade": "Fácil", "enunciado": "O termo biodiversidade (ou diversidade biológica) refere-se à variedade de vida existente na Terra. Ela abrange três níveis fundamentais de organização biológica, que são:", "alternativas": {"A": "Diversidade molecular, atômica e cósmica.", "B": "Diversidade genética, diversidade de espécies e diversidade de ecossistemas.", "C": "Diversidade geológica, climática e mineral.", "D": "Diversidade celular, tecidual e de órgãos.", "E": "Diversidade bacteriana, viral e fúngica apenas."}, "resposta_correta": "B", "justificativa": "A biodiversidade é formalmente compreendida em três níveis interligados: diversidade genética (intraespecífica), diversidade de espécies e diversidade de ecossistemas/biomas.", "possui_imagem": true},
  {"id": 152, "uid": "CIEN-9-152", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços Ecossistêmicos - Conceito", "dificuldade": "Fácil", "enunciado": "Os benefícios diretos e indiretos que os seres humanos obtêm gratuitamente do funcionamento saudável da natureza e de seus ecossistemas são denominados:", "alternativas": {"A": "Serviços ecossistêmicos (ou ambientais).", "B": "Recursos não renováveis.", "C": "Impactos antrópicos negativos.", "D": "Taxas de exploração florestal.", "E": "Produtos agrícolas industrializados."}, "resposta_correta": "A", "justificativa": "Serviços ecossistêmicos são as contribuições diretas e indiretas dos ecossistemas para o bem-estar e sobrevivência da sociedade humana.", "possui_imagem": true},
  {"id": 153, "uid": "CIEN-9-153", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços de Provisão", "dificuldade": "Fácil", "enunciado": "A obtenção de alimentos (como peixes e castanhas), água potável, madeira para construção e princípios ativos para fabricação de medicamentos são exemplos de serviços ecossistêmicos classificados como:", "alternativas": {"A": "Serviços de regulação.", "B": "Serviços de provisão (ou abastecimento).", "C": "Serviços culturais.", "D": "Serviços de suporte puro.", "E": "Serviços geológicos."}, "resposta_correta": "B", "justificativa": "Serviços de provisão correspondem aos bens materiais e recursos tangíveis fornecidos pelos ecossistemas, como alimento, água doce, fibras e remédios.", "possui_imagem": true},
  {"id": 154, "uid": "CIEN-9-154", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços de Regulação", "dificuldade": "Fácil", "enunciado": "O controle natural de enchentes por florestas ripárias, a purificação do ar, a polinização de lavouras agrícolas por abelhas e a regulação do clima regional são classificados como serviços ecossistêmicos de:", "alternativas": {"A": "Provisão.", "B": "Regulação.", "C": "Cultura.", "D": "Extração.", "E": "Consumo."}, "resposta_correta": "B", "justificativa": "Serviços de regulação são benefícios obtidos a partir da modulação dos processos naturais dos ecossistemas, como equilíbrio climático, controle de erosão e pragas, e polinização.", "possui_imagem": true},
  {"id": 155, "uid": "CIEN-9-155", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços Culturais", "dificuldade": "Fácil", "enunciado": "O turismo ecológico em parques naturais, a recreação ao ar livre, a inspiração artística e os valores espirituais e educacionais associados a paisagens naturais constituem serviços ecossistêmicos:", "alternativas": {"A": "De provisão.", "B": "De suporte.", "C": "Culturais.", "D": "Químicos.", "E": "Climáticos."}, "resposta_correta": "C", "justificativa": "Serviços culturais são os benefícios não materiais que as pessoas obtêm dos ecossistemas por meio de enriquecimento espiritual, recreação, turismo e reflexão estética.", "possui_imagem": true},
  {"id": 156, "uid": "CIEN-9-156", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços de Suporte", "dificuldade": "Fácil", "enunciado": "Serviços ecossistêmicos de suporte são aqueles necessários para a produção de todos os outros serviços ecológicos. Um exemplo fundamental de serviço de suporte é:", "alternativas": {"A": "A venda de artesanato em feiras urbanas.", "B": "A ciclagem de nutrientes e a formação de solo.", "C": "O engarrafamento de água mineral.", "D": "A colheita mecanizada de soja.", "E": "O transporte aéreo de passageiros."}, "resposta_correta": "B", "justificativa": "A formação do solo, a fotossíntese e a ciclagem de nutrientes são serviços de suporte básicos que sustentam a vida e tornam possíveis todos os demais serviços.", "possui_imagem": true},
  {"id": 157, "uid": "CIEN-9-157", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Espécies Exóticas Invasoras", "dificuldade": "Fácil", "enunciado": "Uma espécie exótica invasora é definida ecologicamente como:", "alternativas": {"A": "Um organismo originário do próprio ecossistema que se tornou ameaçado de extinção.", "B": "Uma espécie introduzida fora de sua área de distribuição natural que se reproduz intensamente, ameaça a biodiversidade nativa e desequilibra as teias alimentares locais.", "C": "Qualquer animal selvagem criado em cativeiro em zoológicos.", "D": "Uma planta silvestre utilizada exclusivamente para paisagismo urbano sem reprodução.", "E": "Um micro-organismo fossilizado da Era Paleozoica."}, "resposta_correta": "B", "justificativa": "Espécies exóticas invasoras são organismos não nativos que, ao serem introduzidos, proliferam sem predadores naturais e competem com espécies nativas, causando graves desequilíbrios ecológicos.", "possui_imagem": true},
  {"id": 158, "uid": "CIEN-9-158", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Exemplo de Espécie Invasora no Brasil", "dificuldade": "Fácil", "enunciado": "Qual das alternativas a seguir cita um exemplo notório de espécie exótica invasora que causa graves impactos econômicos e ambientais nos ecossistemas aquáticos e terrestres brasileiros?", "alternativas": {"A": "Onça-pintada e tamanduá-bandeira.", "B": "Mexilhão-dourado e javali europeu.", "C": "Pau-brasil e jacarandá-da-bahia.", "D": "Mico-leão-dourado e ariranha.", "E": "Peixe-boi-marinho e tuiuiú."}, "resposta_correta": "B", "justificativa": "O mexilhão-dourado (nos rios e hidrelétricas) e o javali (na agricultura e matas nativas) são espécies exóticas invasoras que causam enormes prejuízos ecológicos e econômicos no Brasil.", "possui_imagem": true},
  {"id": 159, "uid": "CIEN-9-159", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "O que é o SNUC?", "dificuldade": "Fácil", "enunciado": "No Brasil, o Sistema Nacional de Unidades de Conservação (SNUC), instituído pela Lei Federal nº 9.985/2000, organiza as áreas protegidas do país em dois grandes grupos:", "alternativas": {"A": "Áreas Urbanas e Áreas Industriais.", "B": "Unidades de Proteção Integral e Unidades de Uso Sustentável.", "C": "Parques Temáticos e Reservas de Mineração.", "D": "Zonas Agrícolas e Zonas Portuárias.", "E": "Florestas Comerciais e Terras Indígenas."}, "resposta_correta": "B", "justificativa": "O SNUC divide formalmente as Unidades de Conservação em dois grupos: Unidades de Proteção Integral e Unidades de Uso Sustentável.", "possui_imagem": true},
  {"id": 160, "uid": "CIEN-9-160", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Objetivo da Proteção Integral", "dificuldade": "Fácil", "enunciado": "O objetivo básico das Unidades de Conservação do grupo de Proteção Integral é:", "alternativas": {"A": "Permitir o corte raso de madeira e a mineração sob fiscalização anual.", "B": "Preservar a natureza, sendo admitido apenas o uso indireto dos seus recursos naturais, salvo os casos previstos na legislação.", "C": "Incentivar a expansão de lavouras e a criação intensiva de gado.", "D": "Garantir a ocupação imobiliária de loteamentos ecológicos residenciais.", "E": "Construir grandes reservatórios de água para usinas termoelétricas."}, "resposta_correta": "B", "justificativa": "Unidades de Proteção Integral têm por objetivo manter os ecossistemas livres de alterações antrópicas, permitindo apenas uso indireto (pesquisa, educação e turismo controlado).", "possui_imagem": true},
  {"id": 161, "uid": "CIEN-9-161", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Exemplo de Proteção Integral", "dificuldade": "Fácil", "enunciado": "Qual das seguintes categorias de Unidade de Conservação pertence estritamente ao grupo de Proteção Integral segundo o SNUC?", "alternativas": {"A": "Área de Proteção Ambiental (APA).", "B": "Reserva Extrativista (RESEX).", "C": "Parque Nacional (PARNA).", "D": "Floresta Nacional (FLONA).", "E": "Área de Relevante Interesse Ecológico (ARIE)."}, "resposta_correta": "C", "justificativa": "O Parque Nacional pertence ao grupo de Proteção Integral, juntamente com Estação Ecológica, Reserva Biológica, Monumento Natural e Refúgio de Vida Silvestre.", "possui_imagem": true},
  {"id": 162, "uid": "CIEN-9-162", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Objetivo do Uso Sustentável", "dificuldade": "Fácil", "enunciado": "As Unidades de Conservação do grupo de Uso Sustentável têm como objetivo principal:", "alternativas": {"A": "Proibir qualquer presença humana ou pesquisa científica no interior da reserva.", "B": "Compatibilizar a conservação da natureza com o uso sustentável de parcela dos seus recursos naturais.", "C": "Eradicar todas as populações tradicionais residentes na região.", "D": "Destinar toda a área florestal para queima e extração de carvão vegetal.", "E": "Transformar ecossistemas nativos em pastagens de monocultura."}, "resposta_correta": "B", "justificativa": "Unidades de Uso Sustentável buscam conciliar a conservação biológica com o uso direto e racional de recursos por populações tradicionais e manejo sustentável.", "possui_imagem": false},
  {"id": 163, "uid": "CIEN-9-163", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Reserva Extrativista (RESEX)", "dificuldade": "Fácil", "enunciado": "Uma Reserva Extrativista (RESEX) é uma categoria de Uso Sustentável criada especificamente para proteger os meios de vida e a cultura de:", "alternativas": {"A": "Empresas multinacionais de mineração de bauxita.", "B": "Populações tradicionais extrativistas (como seringueiros e castanheiros) cuja subsistência baseia-se no extrativismo sustentável.", "C": "Pecuaristas industriais voltados para a exportação de carne bovina.", "D": "Incorporadoras imobiliárias do litoral brasileiro.", "E": "Companhias de reflorestamento com pinus e eucalipto."}, "resposta_correta": "B", "justificativa": "As Reservas Extrativistas (RESEX) protegem ecossistemas e garantem o uso sustentável dos recursos pelas populações tradicionais extrativistas que historicamente os manejam.", "possui_imagem": false},
  {"id": 164, "uid": "CIEN-9-164", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Área de Proteção Ambiental (APA)", "dificuldade": "Fácil", "enunciado": "A Área de Proteção Ambiental (APA) é uma Unidade de Conservação de Uso Sustentável que se destaca por:", "alternativas": {"A": "Ser constituída apenas por terras públicas onde nenhuma pessoa pode residir.", "B": "Ser uma área geralmente extensa, dotada de atributos bióticos e abióticos de interesse, que pode abranger tanto terras públicas quanto propriedades privadas.", "C": "Exigir a desapropriação imediata de todas as fazendas e cidades existentes.", "D": "Impedir qualquer tipo de atividade econômica ou circulação de veículos.", "E": "Ser restrita a ilhas oceânicas sem vegetação."}, "resposta_correta": "B", "justificativa": "A APA é uma UC de Uso Sustentável ampla que admite áreas públicas e propriedades particulares, conciliando ocupação humana regulada com proteção ambiental.", "possui_imagem": false},
  {"id": 165, "uid": "CIEN-9-165", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Pegada Ecológica - Conceito", "dificuldade": "Fácil", "enunciado": "A 'Pegada Ecológica' é um indicador metodológico utilizado para mensurar:", "alternativas": {"A": "A quantidade de passos que um turista dá em trilhas de parques ecológicos.", "B": "A quantidade de terra e água biologicamente produtivas necessária para sustentar o padrão de consumo e absorver os resíduos de uma população.", "C": "A velocidade de crescimento das raízes das árvores nativas em florestas tropicais.", "D": "A profundidade dos rios poluídos por esgoto doméstico.", "E": "O peso total de todos os animais vertebrados de um bioma."}, "resposta_correta": "B", "justificativa": "A pegada ecológica estima a área de ecossistemas produtivos demandada para suprir o consumo de recursos e assimilar os resíduos gerados por determinado estilo de vida.", "possui_imagem": false},
  {"id": 166, "uid": "CIEN-9-166", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Biocapacidade do Planeta", "dificuldade": "Fácil", "enunciado": "Diz-se que a humanidade entrou em 'déficit ecológico' (ou que o planeta ultrapassou sua capacidade de suporte) quando:", "alternativas": {"A": "A população global para de consumir produtos manufaturados.", "B": "A pegada ecológica humana supera a biocapacidade da Terra de regenerar recursos e absorver os resíduos gerados.", "C": "Todos os vulcões do mundo entram em erupção simultaneamente.", "D": "A quantidade de água dos oceanos evapora completamente.", "E": "O número de árvores plantadas ultrapassa o número de habitantes."}, "resposta_correta": "B", "justificativa": "O déficit ecológico ocorre quando a demanda humana por recursos biológicos supera a capacidade ecológica regenerativa da biosfera (biocapacidade).", "possui_imagem": false},
  {"id": 167, "uid": "CIEN-9-167", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Práticas Sustentáveis Individuais", "dificuldade": "Fácil", "enunciado": "Entre as atitudes cotidianas que contribuem diretamente para a redução da pegada ecológica individual, destaca-se:", "alternativas": {"A": "Aumentar o consumo de descartáveis plásticos de uso único.", "B": "Praticar o consumo consciente, reduzir o desperdício de alimentos e priorizar transporte coletivo ou ativo.", "C": "Lavar calçadas diariamente com mangueira de água tratada.", "D": "Manter lâmpadas e aparelhos eletrônicos ligados continuamente sem necessidade.", "E": "Despejar óleo de cozinha usado diretamente no ralo da pia."}, "resposta_correta": "B", "justificativa": "Consumo consciente, economia de água/energia, reciclagem, redução de desperdício e uso de transporte sustentável diminuem a pressão ecológica individual sobre os recursos do planeta.", "possui_imagem": false},
  {"id": 168, "uid": "CIEN-9-168", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Fragmentação de Hábitats e Efeito de Borda", "dificuldade": "Médio", "enunciado": "A abertura de estradas e o desmatamento dividem florestas contínuas em fragmentos menores e isolados. Um dos principais impactos ecológicos desse processo é o 'efeito de borda', caracterizado por:", "alternativas": {"A": "Aumento da umidade e estabilização térmica no interior dos fragmentos.", "B": "Alterações microclimáticas nas margens dos fragmentos, como maior incidência de vento, calor e dessecação, prejudicando espécies de interior florestal.", "C": "Crescimento imediato das populações de grandes carnívoros nativos.", "D": "Imunização das espécies contra pragas e parasitas exóticos.", "E": "Aumento da variabilidade genética de populações pequenas isoladas."}, "resposta_correta": "B", "justificativa": "O efeito de borda altera a temperatura, insolação e umidade nas periferias dos fragmentos, facilitando a penetração de ventos, espécies invasoras e fogo, além de degradar o habitat das espécies de floresta fechada.", "possui_imagem": false},
  {"id": 169, "uid": "CIEN-9-169", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Corredores Ecológicos", "dificuldade": "Médio", "enunciado": "Uma das estratégias mais eficazes de manejo para mitigar os efeitos deletérios da fragmentação de hábitats é a implantação de corredores ecológicos. Essa medida atua positivamente porque:", "alternativas": {"A": "Isola definitivamente as populações para evitar contaminação genética.", "B": "Conecta fragmentos florestais isolados, permitindo o fluxo gênico e o deslocamento seguro de animais e dispersores de sementes.", "C": "Permite o asfaltamento de novas rodovias para escoamento agrícola.", "D": "Substitui a vegetação nativa por espécies de rápido crescimento comercial.", "E": "Extingue predadores de topo para proteger herbívoros."}, "resposta_correta": "B", "justificativa": "Corredores ecológicos restabelecem a conectividade espacial entre fragmentos florestais, facilitando a dispersão de sementes e o fluxo gênico entre populações outrora isoladas.", "possui_imagem": false},
  {"id": 170, "uid": "CIEN-9-170", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Diversidade Genética e Resiliência", "dificuldade": "Médio", "enunciado": "Populações biológicas com baixa diversidade genética tornam-se extremamente vulneráveis a alterações ambientais ou surtos de doenças porque:", "alternativas": {"A": "Apresentam uma quantidade excessiva de mutações benéficas por geração.", "B": "Possuem menor variabilidade de alelos, o que reduz a probabilidade de que alguns indivíduos possuam características resistentes para sobreviver a novas pressões seletivas.", "C": "Têm capacidade infinita de adaptação fenotípica imediata.", "D": "Não competem com outras espécies por alimento e abrigo.", "E": "Apresentam taxas de natalidade muito superiores à capacidade de suporte."}, "resposta_correta": "B", "justificativa": "A diversidade genética é a matéria-prima da seleção natural. Populações geneticamente homogêneas correm risco de extinção frente a patógenos ou mudanças climáticas por falta de variantes resistentes.", "possui_imagem": false},
  {"id": 171, "uid": "CIEN-9-171", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Diferenciação no SNUC: ESEC vs. REBIO", "dificuldade": "Médio", "enunciado": "No grupo de Proteção Integral, a Estação Ecológica (ESEC) e a Reserva Biológica (REBIO) são categorias de proteção rigorosa. Uma particularidade da Estação Ecológica é que ela:", "alternativas": {"A": "Permite caça esportiva autorizada em finais de semana.", "B": "Tem como objetivo a preservação da natureza e a realização de pesquisas científicas, sendo que alterações no ecossistema só são permitidas para recuperação ou pesquisa em até 3% da área.", "C": "Admite a exploração de madeira por empresas privadas com plano de manejo.", "D": "É aberta irrestritamente ao turismo em massa e eventos musicais.", "E": "Destina-se exclusivamente à agricultura familiar orgânica."}, "resposta_correta": "B", "justificativa": "As ESECs destinam-se à preservação e à pesquisa científica, com visitação pública estritamente educacional e regras severas para intervenção experimental (limitada a pequenas frações da área).", "possui_imagem": false},
  {"id": 172, "uid": "CIEN-9-172", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Reserva Particular do Patrimônio Natural (RPPN)", "dificuldade": "Médio", "enunciado": "A Reserva Particular do Patrimônio Natural (RPPN) é uma categoria especial de Unidade de Conservação do SNUC. Sua característica definidora fundamental é:", "alternativas": {"A": "Ser criada em área privada por iniciativa voluntária do proprietário, gravada com perpetuidade no registro do imóvel, pertencendo ao grupo de Uso Sustentável.", "B": "Ser desapropriada pelo Estado sem indenização ao antigo proprietário.", "C": "Funcionar temporariamente por 5 anos, após os quais a terra pode ser desmatada.", "D": "Permitir a criação de gado de corte e plantio de cana-de-açúcar.", "E": "Pertencer ao grupo de Proteção Integral e exigir posse exclusiva do poder público."}, "resposta_correta": "A", "justificativa": "A RPPN é gravada na matrícula do imóvel com caráter perpétuo em terra privada voluntariamente cedida pelo proprietário para conservação, enquadrada como Uso Sustentável no SNUC.", "possui_imagem": false},
  {"id": 173, "uid": "CIEN-9-173", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Polinização como Serviço Ecossistêmico e Crise dos Polinizadores", "dificuldade": "Médio", "enunciado": "Estudos ecológicos indicam que cerca de 75% das principais culturas agrícolas mundiais que alimentam a humanidade dependem direta ou indiretamente de polinizadores naturais, como abelhas nativas. O declínio desses polinizadores por uso indiscriminado de agrotóxicos e perda de habitat representa uma ameaça direta a qual serviço ecossistêmico e suas consequências?", "alternativas": {"A": "Serviço cultural de recreação, sem impactos na produção de comida.", "B": "Serviço de regulação (polinização) que sustenta serviços de provisão (alimentos), podendo gerar crises de segurança alimentar e inflação de preços agrícolas.", "C": "Serviço de suporte geológico de formação de rochas vulcânicas.", "D": "Apenas à produção de mel comercial em pequena escala regional.", "E": "Ao ciclo hidrológico dos grandes aquíferos profundos."}, "resposta_correta": "B", "justificativa": "A polinização é um serviço de regulação vital que viabiliza a reprodução de plantas cultivadas (serviço de provisão de alimentos). Sua perda ameaça a segurança alimentar e a economia global.", "possui_imagem": false},
  {"id": 174, "uid": "CIEN-9-174", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Mecanismo Ecológico de Invasão Biológica", "dificuldade": "Médio", "enunciado": "Quando uma espécie exótica é introduzida em um novo continente, sua explosão populacional descontrolada costuma ser explicada pela 'Hipótese da Liberação de Inimigos Naturais'. Esse mecanismo postula que:", "alternativas": {"A": "A espécie passa a sintetizar clorofila e produzir seu próprio alimento.", "B": "No novo ambiente, a espécie invasora não encontra seus predadores, competidores e parasitas coevoluídos da sua terra de origem, alocando mais recursos para crescimento e reprodução acelerados.", "C": "O clima do novo local destrói imediatamente o DNA de todas as espécies nativas concorrentes.", "D": "A espécie invasora perde sua capacidade de reprodução sexuada.", "E": "A água do novo ecossistema tem propriedades radioativas que estimulam mutações."}, "resposta_correta": "B", "justificativa": "Sem predadores, patógenos e parasitas específicos de seu ecossistema nativo, a espécie invasora tem vantagem competitiva desproporcional, suplantando os organismos nativos locais.", "possui_imagem": false},
  {"id": 175, "uid": "CIEN-9-175", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Relação entre Desmatamento e Ciclo das Chuvas", "dificuldade": "Médio", "enunciado": "A Floresta Amazônica funciona como uma gigantesca bomba biológica que evapotranspira bilhões de litros de vapor de água diariamente, originando os 'rios voadores' que transportam umidade para o Centro-Oeste e Sudeste do Brasil. O desmatamento da Amazônia compromete qual serviço ecossistêmico de regulação?", "alternativas": {"A": "A geração de calor geotérmico nas profundezas da crosta.", "B": "A regulação climática e o regime de chuvas em regiões agrícolas distantes, aumentando o risco de secas severas e quebra de safras.", "C": "A salinização das águas marinhas da Antártica.", "D": "A rotação gravitacional da Terra em torno do Sol.", "E": "A atividade vulcânica da cadeia dos Andes."}, "resposta_correta": "B", "justificativa": "A transpiração florestal amazônica regula a umidade atmosférica e direciona chuvas vitais para a agricultura e reservatórios hídricos do Centro-Sul brasileiro.", "possui_imagem": false},
  {"id": 176, "uid": "CIEN-9-176", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Conceito de Espécie Bandeira e Guarda-Chuva", "dificuldade": "Médio", "enunciado": "Em biologia da conservação, a onça-pintada (Panthera onca) é frequentemente considerada uma 'espécie guarda-chuva'. Essa denominação técnica significa que:", "alternativas": {"A": "Ela se alimenta exclusivamente de árvores frutíferas que fazem sombra na floresta.", "B": "Por ser um carnívoro de topo de cadeia com enorme área de vida territorial, as ações e reservas criadas para protegê-la acabam protegendo automaticamente inúmeras outras espécies e ecossistemas inteiros.", "C": "Ela protege fisicamente os seres humanos de picadas de insetos peçonhentos.", "D": "Trata-se de uma espécie imune a qualquer tipo de doença viral ou bacteriana.", "E": "Sua caça é legalmente autorizada em todos os parques nacionais."}, "resposta_correta": "B", "justificativa": "Proteger uma espécie guarda-chuva de grande porte e ampla área de vida garante a conservação indireta de toda a comunidade biológica e habitat contidos sob seu domínio.", "possui_imagem": false},
  {"id": 177, "uid": "CIEN-9-177", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Impacto do Fogo em Biomas Brasileiros (Cerrado vs. Mata Atlântica)", "dificuldade": "Médio", "enunciado": "Embora o fogo natural esporádico faça parte da história evolutiva do Cerrado (onde muitas plantas têm cascas grossas e estruturas subterrâneas), na Mata Atlântica e na Floresta Amazônica o fogo antrópico é extremamente devastador porque:", "alternativas": {"A": "As plantas da Amazônia e Mata Atlântica não possuem adaptações evolutivas ao fogo, resultando em altíssima mortalidade de árvores e colapso da teia biológica.", "B": "O Cerrado tem temperaturas médias muito inferiores a zero grau no inverno.", "C": "A floresta úmida queima espontaneamente sem necessidade de oxigênio.", "D": "O solo da Mata Atlântica é composto por carvão mineral puro que queima por décadas.", "E": "As árvores do Cerrado morrem permanentemente com qualquer fagulha."}, "resposta_correta": "B", "justificativa": "Florestas úmidas tropicais não evoluíram sob regime de fogo; suas espécies têm casca fina e raízes superficiais, sofrendo mortalidade catastrófica quando submetidas a queimadas.", "possui_imagem": false},
  {"id": 178, "uid": "CIEN-9-178", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Créditos de Carbono e Pagamento por Serviços Ambientais (PSA)", "dificuldade": "Médio", "enunciado": "O Pagamento por Serviços Ambientais (PSA) é um instrumento econômico de política ambiental em que:", "alternativas": {"A": "Poluidores pagam propinas legais para continuar desmatando ilegalmente.", "B": "Proprietários rurais ou comunidades tradicionais que protegem nascentes, restauram matas ciliares e mantêm a floresta em pé recebem incentivos financeiros pelos serviços ecológicos prestados à coletividade.", "C": "O governo confisca terras preservadas para leiloá-las na bolsa de valores.", "D": "A água de rios públicos passa a ser vendida exclusivamente a multinacionais.", "E": "Cidadãos que reciclam lixo são multados por interferir na limpeza pública."}, "resposta_correta": "B", "justificativa": "O PSA remunera ou compensa provedores de serviços ambientais (como produtores que preservam nascentes e matas) pela manutenção de bens ecossistêmicos que beneficiam toda a sociedade.", "possui_imagem": false},
  {"id": 179, "uid": "CIEN-9-179", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Sobrepesca e Efeito Cascata Trófico", "dificuldade": "Médio", "enunciado": "A captura predatória e desmedida de tubarões nos oceanos (sobrepesca de predadores de topo) frequentemente resulta em um colapso ecológico conhecido como 'cascata trófica'. Isso ocorre porque:", "alternativas": {"A": "Os tubarões param de nadar e poluem o fundo do mar com plástico.", "B": "A redução drástica dos predadores de topo libera populações de mesopredadores ou herbívoros intermediários, que proliferam e dizimam os níveis tróficos inferiores (como peixes herbívoros ou recifes de coral).", "C": "A água do oceano perde seu oxigênio dissolvido imediatamente.", "D": "As algas marinhas se transformam em esponjas tóxicas.", "E": "Os peixes menores se tornam carnívoros imediatos de baleias."}, "resposta_correta": "B", "justificativa": "Remover o predador de topo altera o equilíbrio trófico em cascata: espécies intermediárias aumentam de forma descontrolada e consomem em excesso os níveis basais, desestruturando o ecossistema marinho.", "possui_imagem": false},
  {"id": 180, "uid": "CIEN-9-180", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Eutrofização Artificial em Corpos Hídricos", "dificuldade": "Médio", "enunciado": "O lançamento de esgoto doméstico não tratado e fertilizantes agrícolas ricos em fósforo e nitrogênio em lagoas provoca a proliferação explosiva de algas, seguida da morte de peixes por falta de oxigênio dissolvido. Esse fenômeno antrópico é denominado:", "alternativas": {"A": "Bioacumulação lipídica.", "B": "Eutrofização artificial.", "C": "Biomagnificação trófica.", "D": "Lixiviação calcária.", "E": "Intemperismo físico."}, "resposta_correta": "B", "justificativa": "A eutrofização ocorre quando o excesso de nutrientes induz o 'bloom' de algas; ao morrerem, a decomposição bacteriana aeróbica consome o O2 dissolvido na água, causando asfixia da fauna aquática.", "possui_imagem": false},
  {"id": 181, "uid": "CIEN-9-181", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Bioacumulação vs. Biomagnificação", "dificuldade": "Médio", "enunciado": "Diferencie os conceitos ecotoxicológicos de bioacumulação e biomagnificação:\nI. Bioacumulação é o acúmulo de uma substância tóxica nos tecidos de um mesmo indivíduo ao longo de sua vida.\nII. Biomagnificação é o aumento da concentração desse poluente em níveis tróficos sucessivamente mais altos da cadeia alimentar.\nSobre essas afirmações:", "alternativas": {"A": "Apenas a I é verdadeira.", "B": "Apenas a II é verdadeira.", "C": "Ambas são verdadeiras.", "D": "Ambas são falsas.", "E": "A afirmação I refere-se à biomagnificação e a II à bioacumulação."}, "resposta_correta": "C", "justificativa": "Bioacumulação ocorre no nível do indivíduo (acúmulo progressivo ao longo do tempo). Biomagnificação ocorre ao longo da cadeia alimentar (maior concentração nos predadores de topo).", "possui_imagem": false},
  {"id": 182, "uid": "CIEN-9-182", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Unidades de Conservação e Conflitos Fundiários", "dificuldade": "Médio", "enunciado": "Ao criar uma Unidade de Conservação da categoria Parque Nacional, o poder público deve lidar com uma exigência legal rigorosa prevista no SNUC que não é necessária para criar uma Área de Proteção Ambiental (APA). Essa exigência é:", "alternativas": {"A": "A proibição definitiva de realização de qualquer pesquisa científica no local.", "B": "A necessidade de desapropriação e indenização de todas as propriedades particulares inseridas no perímetro do parque, tornando a posse estritamente pública.", "C": "A obrigatoriedade de construir hotéis de luxo no centro da reserva.", "D": "A autorização expressa para pastoreio de gado comercial.", "E": "A aprovação prévia de países vizinhos da América do Sul."}, "resposta_correta": "B", "justificativa": "O Parque Nacional é de posse e domínio públicos; terras particulares nele incluídas devem ser legalmente desapropriadas e indenizadas pelo Estado, ao passo que a APA admite terras privadas sem desapropriação.", "possui_imagem": false},
  {"id": 183, "uid": "CIEN-9-183", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Conceito de Desenvolvimento Sustentável (Relatório Brundtland)", "dificuldade": "Médio", "enunciado": "Definido historicamente no relatório 'Nosso Futuro Comum' (Relatório Brundtland, 1987), o desenvolvimento sustentável é aquele que:", "alternativas": {"A": "Prioriza o crescimento econômico imediato a qualquer custo ecológico.", "B": "Atende às necessidades da geração presente sem comprometer a capacidade das gerações futuras de atenderem às suas próprias necessidades.", "C": "Defende o retorno imediato da civilização ao modo de vida pré-histórico.", "D": "Substitui todas as fontes de energia renováveis por queima de carvão.", "E": "Proíbe a agricultura e a criação de animais em todo o globo terrestre."}, "resposta_correta": "B", "justificativa": "O conceito clássico de desenvolvimento sustentável equilibra sustentabilidade ambiental, justiça social e viabilidade econômica entre as gerações presentes e futuras.", "possui_imagem": false},
  {"id": 184, "uid": "CIEN-9-184", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Teoria da Biogeografia de Ilhas e Fragmentação", "dificuldade": "Difícil", "enunciado": "A Teoria da Biogeografia de Ilhas, formulada por Robert MacArthur e Edward O. Wilson (1967), é amplamente aplicada no desenho de Unidades de Conservação e fragmentos florestais continentais. De acordo com essa teoria, a riqueza de espécies em equilíbrio em uma 'ilha' (ou fragmento) é determinada fundamentalmente pelo balanço entre:", "alternativas": {"A": "Taxas de mutação espontânea e velocidade do vento.", "B": "Taxas de imigração (colonização) e taxas de extinção, as quais dependem diretamente da área do fragmento e de seu grau de isolamento em relação à fonte de dispersores.", "C": "A profundidade dos lençóis freáticos e a altitude das montanhas.", "D": "A pressão atmosférica e a concentração de oxigênio no ar.", "E": "A abundância de carnívoros e a quantidade de ferro no solo."}, "resposta_correta": "B", "justificativa": "O número de espécies em equilíbrio resulta do balanço entre imigração (maior em ilhas mais próximas do continente/fonte) e extinção (menor em ilhas maiores, que suportam maiores populações).", "possui_imagem": false},
  {"id": 185, "uid": "CIEN-9-185", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Critérios SLOSS (Single Large or Several Small)", "dificuldade": "Difícil", "enunciado": "O debate ecológico histórico conhecido como SLOSS ('Single Large or Several Small') discute se é preferível criar uma única grande reserva natural ou várias reservas menores com a mesma área somada. Qual é o principal argumento biológico a favor de uma 'única grande reserva' (Single Large)?", "alternativas": {"A": "Redução do custo financeiro de construção de cercas perimetrais.", "B": "Menor razão borda/área (minimizando o efeito de borda) e capacidade de sustentar populações viáveis de grandes vertebrados que exigem vastos territórios, além de menor risco de extinção por deriva genética.", "C": "Garantir que incêndios florestais queimem toda a reserva de uma só vez.", "D": "Facilitar o turismo de massa concentrado em um único ponto.", "E": "Eliminar a necessidade de planos de manejo e fiscalização florestal."}, "resposta_correta": "B", "justificativa": "Uma grande reserva contínua possui núcleo florestal protegido de efeitos de borda, sustenta predadores de grande porte com requerimentos espaciais amplos e reduz o isolamento genético.", "possui_imagem": false},
  {"id": 186, "uid": "CIEN-9-186", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Análise Crítica do SNUC: Plano de Manejo e Zona de Amortecimento", "dificuldade": "Difícil", "enunciado": "Segundo o SNUC, toda Unidade de Conservação deve dispor de um 'Plano de Manejo' e, com exceção de APA e RPPN, deve possuir uma 'Zona de Amortecimento'. As definições corretas desses dois instrumentos são:", "alternativas": {"A": "Plano de Manejo é o valor das multas aplicadas; Zona de Amortecimento é a área asfaltada para estacionamento de visitantes.", "B": "Plano de Manejo é o documento técnico que estabelece o zoneamento e as normas de uso da UC; Zona de Amortecimento é o entorno da UC onde as atividades humanas estão sujeitas a normas específicas para filtrar impactos negativos sobre a área protegida.", "C": "Plano de Manejo é a licença concedida para extração mineral; Zona de Amortecimento é a cerca de arame farpado da divisa.", "D": "Plano de Manejo é o orçamento anual de compras; Zona de Amortecimento é o rio que corta a floresta.", "E": "Plano de Manejo aplica-se apenas a zoológicos; Zona de Amortecimento destina-se ao plantio de monoculturas."}, "resposta_correta": "B", "justificativa": "O Plano de Manejo guia a gestão e zoneamento da UC; a Zona de Amortecimento circunda a unidade para mitigar os impactos das atividades humanas vizinhas sobre o ecossistema protegido.", "possui_imagem": false},
  {"id": 187, "uid": "CIEN-9-187", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Hotspots de Biodiversidade (Conceito de Norman Myers)", "dificuldade": "Difícil", "enunciado": "Para ser qualificada internacionalmente como um 'Hotspot de Biodiversidade' segundo o conceito formulado pelo ecólogo Norman Myers, uma região biogeográfica deve atender simultaneamente a dois critérios rigorosos:", "alternativas": {"A": "Conter pelo menos 1.500 espécies de plantas vasculares endêmicas e ter perdido 70% ou mais de sua vegetação original nativa.", "B": "Possuir temperatura média acima de 30 °C e índice pluviométrico nulo no verão.", "C": "Ser desprovida de espécies carnívoras e possuir solos ricos em petróleo.", "D": "Estar localizada exclusivamente no continente africano em áreas costeiras.", "E": "Ter 100% de sua área coberta por parques nacionais de preservação."}, "resposta_correta": "A", "justificativa": "Um Hotspot de Biodiversidade deve abrigar alta riqueza biológica com extremo endemismo (≥ 1.500 espécies vasculares endêmicas) e estar sob grave ameaça (ter perdido ≥ 70% de seu habitat primário). No Brasil, Mata Atlântica e Cerrado são reconhecidos como Hotspots mundiais.", "possui_imagem": false},
  {"id": 188, "uid": "CIEN-9-188", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Hotspots Brasileiros Reconhecidos", "dificuldade": "Difícil", "enunciado": "Quais são os dois biomas brasileiros formalmente classificados como Hotspots Mundiais de Biodiversidade devido à extraordinária riqueza de espécies endêmicas associada a um estado crítico de degradação histórica?", "alternativas": {"A": "Pampa e Pantanal.", "B": "Mata Atlântica e Cerrado.", "C": "Amazônia e Caatinga.", "D": "Pantanal e Amazônia.", "E": "Caatinga e Pampa."}, "resposta_correta": "B", "justificativa": "Mata Atlântica (com cerca de 12% de cobertura original remanescente) e Cerrado (devastado pela rápida expansão agropecuária) são os dois biomas brasileiros reconhecidos internacionalmente como Hotspots de Conservação.", "possui_imagem": false},
  {"id": 189, "uid": "CIEN-9-189", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Valoração Econômica dos Serviços Ecossistêmicos", "dificuldade": "Difícil", "enunciado": "O estudo seminal liderado por Robert Costanza em 1997 estimou o valor econômico anual dos serviços ecossistêmicos globais em cerca de US$ 33 trilhões (quase o dobro do PIB mundial da época). O objetivo conceitual central dessa valoração ambiental é demonstrar que:", "alternativas": {"A": "A natureza deve ser inteiramente privatizada e vendida em leilões comerciais.", "B": "Os serviços prestados gratuitamente pela biosfera têm valor econômico inestimável, e sua degradação gera custos financeiros ocultos que ultrapassam o lucro imediato de sua destruição.", "C": "A economia humana independe completamente dos recursos biológicos naturais.", "D": "O PIB dos países aumentará se todas as florestas forem substituídas por concreto.", "E": "É possível calcular o preço exato para reconstruir o planeta Terra em laboratório."}, "resposta_correta": "B", "justificativa": "A valoração econômica evidencia que a destruição dos ecossistemas impõe prejuízos colossais não computados no mercado tradicional, reforçando a urgência da conservação para a sustentabilidade da economia humana.", "possui_imagem": false},
  {"id": 190, "uid": "CIEN-9-190", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Mosaicos de Áreas Protegidas no SNUC", "dificuldade": "Difícil", "enunciado": "O artigo 26 da Lei do SNUC prevê que quando existir um conjunto de Unidades de Conservação de categorias diferentes ou não, próximas, justapostas ou sobrepostas, e outras áreas protegidas públicas ou privadas, elas podem ser geridas de forma integrada como um 'Mosaico'. A principal vantagem ecológica e gerencial dessa figura é:", "alternativas": {"A": "Transformar todas as unidades em áreas de mineração sem fiscalização.", "B": "Otimizar recursos humanos e financeiros, integrando a fiscalização e compatibilizando a conservação da biodiversidade com o desenvolvimento regional em escala de paisagem.", "C": "Permitir a extinção dos planos de manejo de todas as unidades envolvidas.", "D": "Proibir permanentemente a circulação de pesquisadores universitários na região.", "E": "Subordinar todas as áreas à administração de empresas privadas estrangeiras."}, "resposta_correta": "B", "justificativa": "A gestão em mosaico integra a conservação da biodiversidade em escala de paisagem, promovendo a conectividade, compartilhamento de recursos de fiscalização e harmonia com o desenvolvimento socioeconômico regional.", "possui_imagem": false},
  {"id": 191, "uid": "CIEN-9-191", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Poluição por Microplásticos e Biomagnificação Marinha", "dificuldade": "Difícil", "enunciado": "Os microplásticos (< 5 mm) acumulam-se nos oceanos e absorvem poluentes orgânicos persistentes (POPs), como PCBs e pesticidas organoclorados hidrofóbicos. Quando ingeridos pelo zooplâncton, esses compostos tóxicos entram na teia trófica. O fenômeno pelo qual a concentração dessas toxinas nos tecidos de toninhas e orcas atinge níveis milhões de vezes maiores do que na água do mar é explicado por:", "alternativas": {"A": "Biomagnificação trófica, decorrente da lipossolubilidade e da não biodegradabilidade dos compostos tóxicos, que se concentram nos níveis tróficos superiores.", "B": "Excreção ativa acelerada de compostos tóxicos por carnívoros de topo.", "C": "Diluição progressiva da toxina conforme a biomassa aumenta na pirâmide trófica.", "D": "Evaporação seletiva do plástico no trato digestório dos peixes pelágicos.", "E": "Absorção de luz ultravioleta que quebra as toxinas em nutrientes inofensivos."}, "resposta_correta": "A", "justificativa": "Compostos lipofílicos e não biodegradáveis não são excretados; ao serem consumidos ao longo da cadeia alimentar, acumulam-se em proporções crescentes a cada nível trófico (biomagnificação).", "possui_imagem": false},
  {"id": 192, "uid": "CIEN-9-192", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Reserva da Biosfera da UNESCO e Zoneamento", "dificuldade": "Difícil", "enunciado": "As Reservas da Biosfera, chanceladas pelo programa 'O Homem e a Biosfera' (MAB) da UNESCO, organizam-se espacialmente em três zonas concêntricas com funções integradas. Essas zonas e suas respectivas finalidades são:", "alternativas": {"A": "Zona Industrial, Zona Urbana e Zona Rural.", "B": "Zona Núcleo (proteção estrita da biodiversidade), Zona de Amortecimento (atividades compatíveis com a conservação e pesquisa) e Zona de Transição (desenvolvimento socioeconômico sustentável e moradia).", "C": "Zona Militar, Zona Comercial e Zona Portuária.", "D": "Zona de Queimada, Zona de Reflorestamento e Zona de Mineração.", "E": "Zona Exclusiva de Pesca, Zona de Turismo de Luxo e Zona Desértica."}, "resposta_correta": "B", "justificativa": "O modelo da UNESCO estrutura a paisagem em: Zona Núcleo (preservação estrita), Zona de Amortecimento (pesquisa, ecoturismo e manejo suave) e Zona de Transição (práticas produtivas sustentáveis e comunidades).", "possui_imagem": true},
  {"id": 193, "uid": "CIEN-9-193", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Acidificação dos Oceanos e Perda de Biodiversidade Coralínea", "dificuldade": "Difícil", "enunciado": "O aumento da queima de combustíveis fósseis elevou a concentração de CO2 atmosférico, que é absorvido pelos oceanos formando ácido carbônico [CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3-]. Esse processo químico reduz o pH e a disponibilidade de íons carbonato (CO3^2-), provocando diretamente:", "alternativas": {"A": "Aumento acelerado da calcificação e crescimento de conchas de moluscos e recifes de corais.", "B": "Dificuldade severa de calcificação e dissolução dos esqueletos de carbonato de cálcio (CaCO3) de corais e moluscos, ameaçando os recifes que sustentam 25% da biodiversidade marinha.", "C": "Transformação da água do mar em água doce potável.", "D": "Diminuição da salinidade dos oceanos devido à formação de sal de cozinha insolúvel.", "E": "Aumento da temperatura de congelamento da água polar para 50 °C."}, "resposta_correta": "B", "justificativa": "A acidificação oceânica reduz a saturação de íons carbonato livres no mar, dificultando a biomineralização de esqueletos calcários de corais e organismos bentônicos, desestruturando os recifes.", "possui_imagem": false},
  {"id": 194, "uid": "CIEN-9-194", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Ameaça Genética: Depressão por Endocruzamento", "dificuldade": "Difícil", "enunciado": "Em populações extremamente reduzidas de espécies ameaçadas (como o mico-leão-preto em fragmentos isolados no interior de São Paulo), o cruzamento frequente entre indivíduos aparentados provoca a 'depressão por endocruzamento' (inbreeding depression). O mecanismo genético responsável pela perda de aptidão adaptativa e declínio populacional nesse cenário é:", "alternativas": {"A": "O aumento da heterozigose na progênie gerada.", "B": "O aumento da homozigose de alelos recessivos deletérios e a perda da variabilidade genética geral necessária para responder a patógenos.", "C": "A conversão de células somáticas em células tronco mutantes.", "D": "A inativação de todos os ribossomos celulares.", "E": "A duplicação imediata do número de cromossomos sexuais."}, "resposta_correta": "B", "justificativa": "O endocruzamento eleva a probabilidade de manifestação fenotípica de alelos deletérios em homozigose (recessivos prejudiciais), reduzindo a fertilidade, sobrevivência e vigor híbrido da população.", "possui_imagem": false},
  {"id": 195, "uid": "CIEN-9-195", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Serviços Ecossistêmicos e a Pandemia de Zoonoses", "dificuldade": "Difícil", "enunciado": "Estudos epidemiológicos e ecológicos modernos (abordagem 'Saúde Única' ou 'One Health') demonstram que florestas tropicais intactas fornecem um serviço ecossistêmico de regulação vital na contenção de patógenos (efeito de diluição). A degradação dessas matas e o tráfico de animais silvestres aumentam o risco de pandemias porque:", "alternativas": {"A": "Eliminam todos os vírus da natureza, deixando o sistema imune humano enfraquecido.", "B": "Quebram as barreiras ecológicas naturais e aproximam patógenos silvestres de populações humanas e criações domésticas, facilitando o 'transbordamento' (spillover) de vírus zoonóticos.", "C": "Aumentam a radiação ultravioleta que esteriliza os solos florestais.", "D": "Aceleram a evolução de animais herbívoros carnívoros.", "E": "Tornam a água dos rios imprópria para morcegos e primatas."}, "resposta_correta": "B", "justificativa": "Ecossistemas íntegros amortecem patógenos pela diversidade de hospedeiros (efeito diluição). A invasão e destruição florestal aumentam o contato humano com reservatórios silvestres, catalisando spillovers zoonóticos.", "possui_imagem": false},
  {"id": 196, "uid": "CIEN-9-196", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Manejo Florestal Sustentável vs. Corte Raso", "dificuldade": "Difícil", "enunciado": "Em Unidades de Conservação de Uso Sustentável, como as Florestas Nacionais (FLONAs), admite-se o Manejo Florestal Sustentável de madeira. Os princípios técnicos que diferenciam o Manejo Florestal Sustentável do corte raso convencional incluem:", "alternativas": {"A": "Corte de 100% da vegetação seguido de queima total da área a cada 2 anos.", "B": "Inventário florestal prévio, corte seletivo com taxa de extração compatível com a regeneração natural da mata, manutenção de árvores matrizes porta-sementes e ciclos de corte rotativos (ex.: 25 a 30 anos).", "C": "Substituição completa das espécies nativas por soja transgênica com colheita anual.", "D": "Utilização de venenos químicos para matar cipós e arbustos de sub-bosque.", "E": "Proibição da presença de qualquer engenheiro florestal ou fiscal público."}, "resposta_correta": "B", "justificativa": "O manejo florestal sustentável emprega corte seletivo de indivíduos adultos selecionados, preserva matrizes reprodutivas e respeita o ciclo de descanso e recomposição volumétrica da floresta.", "possui_imagem": false},
  {"id": 197, "uid": "CIEN-9-197", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Pegada Hídrica e Comércio de Água Virtual", "dificuldade": "Difícil", "enunciado": "O conceito de 'água virtual' refere-se ao volume de água doce consumido ou poluído direta e indiretamente ao longo de toda a cadeia produtiva de um bem ou serviço. Quando o Brasil exporta commodities como soja, carne bovina ou celulose, ele está paralelamente:", "alternativas": {"A": "Importando água doce de países do Oriente Médio.", "B": "Exportando gigantescos volumes de 'água virtual' incorporada na produção agrícola e agropecuária, transferindo pressões hídricas sobre seus próprios biomas e bacias hidrográficas.", "C": "Purificando as águas fluviais de países desenvolvidos sem custos operacionais.", "D": "Eliminando o ciclo hidrológico de suas próprias regiões produtoras.", "E": "Substituindo a água líquida dos aquíferos por compostos gasosos inertes."}, "resposta_correta": "B", "justificativa": "A produção agropecuária de exportação exige milhares de litros de água por quilo de produto (água virtual). Sua comercialização internacional reflete uma transferência indireta de recursos hídricos do país exportador.", "possui_imagem": false},
  {"id": 198, "uid": "CIEN-9-198", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Estratégia Nacional para Conservação de Espécies Ameaçadas (PAN)", "dificuldade": "Difícil", "enunciado": "No âmbito do Instituto Chico Mendes de Conservação da Biodiversidade (ICMBio), os Planos de Ação Nacional para a Conservação de Espécies Ameaçadas de Extinção (PAN) são políticas públicas que:", "alternativas": {"A": "Autorizam a caça comercial de espécies em perigo para arrecadar fundos.", "B": "Pactuam metas, cronogramas e ações coordenadas entre governos, ONGs e academia para mitigar ameaças, recuperar habitats e evitar a extinção de espécies ameaçadas em determinado território.", "C": "Determinam a eliminação de populações silvestres doentes por eutanásia em massa.", "D": "Transferem todas as espécies ameaçadas do Brasil para cativeiro na Europa.", "E": "Substituem as unidades de conservação por áreas de mineração privada."}, "resposta_correta": "B", "justificativa": "Os PANs são instrumentos de gestão participativa que estabelecem estratégias e ações prioritárias para combater as ameaças às espécies em risco de extinção e promover sua recuperação.", "possui_imagem": false},
  {"id": 199, "uid": "CIEN-9-199", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Critérios da Lista Vermelha da IUCN", "dificuldade": "Difícil", "enunciado": "A União Internacional para a Conservação da Natureza (IUCN) avalia o risco de extinção de espécies biológicas por meio de categorias baseadas em critérios científicos estritos. A sequência ordenada que reflete graus crescentes de gravidade de ameaça antes da extinção na natureza é:", "alternativas": {"A": "Extinta (EX) → Menos Preocupante (LC) → Vulnerável (VU).", "B": "Vulnerável (VU) → Em Perigo (EN) → Criticamente em Perigo (CR).", "C": "Criticamente em Perigo (CR) → Em Perigo (EN) → Quase Ameaçada (NT).", "D": "Dados Insuficientes (DD) → Extinta na Natureza (EW) → Vulnerável (VU).", "E": "Extinta na Natureza (EW) → Quase Ameaçada (NT) → Vulnerável (VU)."}, "resposta_correta": "B", "justificativa": "As categorias oficiais da IUCN para espécies ameaçadas (em ordem crescente de gravidade) são: Vulnerável (VU), Em Perigo (EN) e Criticamente em Perigo (CR), culminando em Extinta na Natureza (EW) e Extinta (EX).", "possui_imagem": false},
  {"id": 200, "uid": "CIEN-9-200", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 18: Biodiversidade, Serviços Ecossistêmicos e Unidades de Conservação - SNUC", "tema": "Economia Circular vs. Economia Linear", "dificuldade": "Difícil", "enunciado": "O modelo econômico tradicional baseia-se na lógica linear 'extrair, produzir, consumir e descartar', gerando acelerada exaustão de recursos e montanhas de resíduos. Em contrapartida, a 'Economia Circular' propõe uma transição paradigmática fundamentada em:", "alternativas": {"A": "Aumentar a velocidade de descarte de produtos eletrônicos para movimentar o comércio.", "B": "Projetar produtos duráveis e regenerativos, dissociando o desenvolvimento econômico do consumo de recursos finitos por meio da redução, reutilização, remanufatura e reciclagem contínua em ciclos fechados.", "C": "Despejar todo o lixo industrial no espaço sideral para despoluir a Terra.", "D": "Impedir qualquer inovação tecnológica ou industrialização no planeta.", "E": "Substituir a moeda corrente por créditos florestais de papel."}, "resposta_correta": "B", "justificativa": "A Economia Circular busca manter produtos, materiais e recursos em seu mais alto valor de utilidade o tempo todo, eliminando resíduos e poluição desde o ecodesign do produto.", "possui_imagem": false},
  {"id": 201, "uid": "CIEN-9-201", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O que é uma Estrela?", "dificuldade": "Fácil", "enunciado": "As estrelas são corpos celestes fascinantes que se diferenciam dos planetas e luas fundamentalmente por:", "alternativas": {"A": "Refletirem a luz solar que atinge suas superfícies sólidas e rochosas.", "B": "Serem esferas gasosas e plasmáticas que produzem sua própria luz e calor por meio de reações de fusão nuclear em seus núcleos.", "C": "Serem compostas exclusivamente de ferro sólido imerso em oceanos de água líquida.", "D": "Orbitarem satélites artificiais lançados pela humanidade.", "E": "Não possuírem força gravitacional própria."}, "resposta_correta": "B", "justificativa": "Estrelas são esferas de plasma autogravitantes sustentadas por reações de fusão nuclear em seus núcleos, que emitem radiação eletromagnética própria (luz e calor).", "possui_imagem": true},
  {"id": 202, "uid": "CIEN-9-202", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Berçários Estelares: Nebulosas", "dificuldade": "Fácil", "enunciado": "As estrelas nascem a partir de gigantescas nuvens interestelares formadas principalmente por gás hidrogênio e poeira cósmica. Essas nuvens são denominadas:", "alternativas": {"A": "Cometas.", "B": "Nebulosas.", "C": "Constelações.", "D": "Asteroides.", "E": "Buracos negros."}, "resposta_correta": "B", "justificativa": "Nebulosas são imensas nuvens de gás e poeira no meio interestelar consideradas os verdadeiros berçários de estrelas do Universo.", "possui_imagem": true},
  {"id": 203, "uid": "CIEN-9-203", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Combustível Nuclear Principal", "dificuldade": "Fácil", "enunciado": "Durante a maior parte da vida de uma estrela (fase de Sequência Principal), o processo nuclear fundamental que gera sua energia é a transformação de:", "alternativas": {"A": "Ferro em chumbo.", "B": "Hidrogênio em hélio por fusão nuclear.", "C": "Urânio em tório por fissão atômica.", "D": "Oxigênio em gás carbônico por combustão.", "E": "Água em vapor por aquecimento solar."}, "resposta_correta": "B", "justificativa": "Na fase estável da estrela (Sequência Principal), quatro núcleos de hidrogênio (prótons) fundem-se em um núcleo de hélio, liberando quantidades colossais de energia.", "possui_imagem": true},
  {"id": 204, "uid": "CIEN-9-204", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Equilíbrio Hidrostático", "dificuldade": "Fácil", "enunciado": "Uma estrela mantém seu tamanho e forma esférica relativamente estáveis ao longo de bilhões de anos graças ao equilíbrio entre duas forças opostas:", "alternativas": {"A": "A força magnética da Lua e o atrito dos ventos solares.", "B": "A gravidade (que tenta colapsar a estrela para dentro) e a pressão térmica da radiação gerada pela fusão nuclear (que empurra para fora).", "C": "A força centrífuga da Terra e as marés oceânicas.", "D": "A energia elétrica das nuvens e a pressão atmosférica dos cometas.", "E": "O vácuo espacial e o peso dos asteroides vizinhos."}, "resposta_correta": "B", "justificativa": "O equilíbrio hidrostático é a igualdade exata entre a atração gravitacional (colapso para dentro) e a pressão da radiação térmica gerada no núcleo (expansão para fora).", "possui_imagem": true},
  {"id": 205, "uid": "CIEN-9-205", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O Sol como Estrela", "dificuldade": "Fácil", "enunciado": "O Sol, estrela central do nosso Sistema Solar, é classificado pelos astrônomos como uma estrela:", "alternativas": {"A": "Supergigante azul no estágio final de colapso.", "B": "De massa intermediária (anã amarela), atualmente na fase estável de Sequência Principal.", "C": "Anã branca que já encerrou todas as suas reações nucleares.", "D": "Estrela de nêutrons em rotação ultraveloz.", "E": "Protoestrela que ainda não iniciou a queima de hidrogênio."}, "resposta_correta": "B", "justificativa": "O Sol é uma estrela de massa média com cerca de 4,6 bilhões de anos, situada no meio de sua vida estável na Sequência Principal fundindo hidrogênio em hélio.", "possui_imagem": true},
  {"id": 206, "uid": "CIEN-9-206", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Fase de Gigante Vermelha", "dificuldade": "Fácil", "enunciado": "Quando o hidrogênio no núcleo de uma estrela semelhante ao Sol se esgota, seu núcleo se contrai e suas camadas externas se expandem enormemente, resfriando-se na superfície. Essa fase é conhecida como:", "alternativas": {"A": "Supernova.", "B": "Gigante Vermelha.", "C": "Pulsar.", "D": "Buraco de minhoca.", "E": "Anã azul."}, "resposta_correta": "B", "justificativa": "Ao esgotar o hidrogênio central, a estrela expande suas camadas externas centenas de vezes, assumindo coloração avermelhada e tornando-se uma Gigante Vermelha.", "possui_imagem": true},
  {"id": 207, "uid": "CIEN-9-207", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Destino Final do Sol: Nebulosa Planetária e Anã Branca", "dificuldade": "Fácil", "enunciado": "Ao final de sua evolução, uma estrela com a massa do nosso Sol ejetará suas camadas externas para o espaço, formando uma bela nuvem colorida denominada nebulosa planetária, enquanto seu núcleo remanescente resfriará lentamente como uma:", "alternativas": {"A": "Supernova hipermassiva.", "B": "Anã Branca.", "C": "Estrela de Nêutrons.", "D": "Buraco Negro supermassivo.", "E": "Estrela de bário."}, "resposta_correta": "B", "justificativa": "Estrelas de baixa e média massa terminam ejetando uma nebulosa planetária, deixando para trás um núcleo denso e quente composto de carbono e oxigênio chamado Anã Branca.", "possui_imagem": true},
  {"id": 208, "uid": "CIEN-9-208", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O que é uma Anã Branca?", "dificuldade": "Fácil", "enunciado": "Uma Anã Branca é caracterizada por:", "alternativas": {"A": "Ser uma estrela gigantesca e muito rarefeita com fusão nuclear acelerada de ferro.", "B": "Ser um remanescente estelar extremamente denso, quente e compacto (aproximadamente do tamanho da Terra), que brilha apenas pelo calor residual acumulado.", "C": "Ser um corpo celeste líquido que vaga entre planetas do Sistema Solar.", "D": "Ser um planeta rochoso que capturou uma lua de gelo.", "E": "Ser uma nuvem de poeira que nunca iniciou fusão nuclear."}, "resposta_correta": "B", "justificativa": "A Anã Branca tem massa comparável à do Sol comprimida no volume aproximado da Terra, sem reações de fusão ativas, brilhando pelo calor residual remanescente.", "possui_imagem": true},
  {"id": 209, "uid": "CIEN-9-209", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Estrelas Massivas", "dificuldade": "Fácil", "enunciado": "Estrelas que possuem massas muito maiores que a do Sol (mais de 8 a 10 vezes a massa solar) têm uma vida muito diferente da do Sol porque:", "alternativas": {"A": "Vivem trilhões de anos sem gastar combustível nuclear.", "B": "Consomem seu combustível nuclear em ritmo frenético e terminam suas vidas em explosões cósmicas cataclísmicas.", "C": "Nunca realizam fusão nuclear de hidrogênio.", "D": "Transformam-se diretamente em cometas de gelo.", "E": "Não possuem força gravitacional suficiente para reter seus gases."}, "resposta_correta": "B", "justificativa": "Estrelas massivas geram pressões e temperaturas nucleares tão elevadas que consomem seu hidrogênio em poucos milhões de anos, terminando em explosões violentas de supernova.", "possui_imagem": true},
  {"id": 210, "uid": "CIEN-9-210", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Explosão de Supernova", "dificuldade": "Fácil", "enunciado": "A espetacular explosão que marca a morte violenta de uma estrela massiva, brilhando temporariamente tanto quanto uma galáxia inteira, é chamada de:", "alternativas": {"A": "Aurora boreal.", "B": "Supernova.", "C": "Eclipse solar total.", "D": "Solstício galáctico.", "E": "Cometa Halley."}, "resposta_correta": "B", "justificativa": "A supernova é a explosão colossal decorrente do colapso gravitacional do núcleo de uma estrela massiva ou da detonação termonuclear de uma anã branca.", "possui_imagem": true},
  {"id": 211, "uid": "CIEN-9-211", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Remanescente de Supernova: Estrela de Nêutrons", "dificuldade": "Fácil", "enunciado": "Após a explosão de uma supernova de uma estrela massiva, o núcleo remanescente ultradenso, onde prótons e elétrons foram comprimidos até formarem quase exclusivamente nêutrons, passa a ser chamado de:", "alternativas": {"A": "Estrela de Nêutrons.", "B": "Planeta gasoso gigante.", "C": "Meteoroide.", "D": "Anã Marrom.", "E": "Nebulosa de emissão."}, "resposta_correta": "A", "justificativa": "Sob a pressão esmagadora do colapso, elétrons fundem-se a prótons gerando nêutrons, formando uma Estrela de Nêutrons com densidade nuclear inimaginável.", "possui_imagem": false},
  {"id": 212, "uid": "CIEN-9-212", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Buraco Negro - Conceito Básico", "dificuldade": "Fácil", "enunciado": "Quando uma estrela de massa extremamente gigantesca colapsa ao final de sua vida, sua gravidade torna-se tão intensa que nem mesmo a luz consegue escapar de seu campo de atração. Essa região do espaço-tempo é chamada de:", "alternativas": {"A": "Cinturão de Kuiper.", "B": "Buraco Negro.", "C": "Nuvem de Oort.", "D": "Anã Amarela.", "E": "Protoestrela."}, "resposta_correta": "B", "justificativa": "O Buraco Negro é uma região do espaço-tempo com campo gravitacional tão extremo que a velocidade de escape supera a velocidade da luz.", "possui_imagem": false},
  {"id": 213, "uid": "CIEN-9-213", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Origem dos Elementos Químicos: 'Poeira de Estrelas'", "dificuldade": "Fácil", "enunciado": "A famosa frase do astrônomo Carl Sagan, 'Somos feitos de poeira de estrelas', tem fundamento científico real porque:", "alternativas": {"A": "Nossos corpos absorvem poeira do solo quando caminhamos.", "B": "Todos os elementos químicos mais pesados que o hélio presentes em nosso corpo (como carbono, oxigênio, cálcio e ferro) foram forjados no interior de estrelas e espalhados por supernovas.", "C": "O Sol atrai átomos da Terra diariamente através dos ventos solares.", "D": "As estrelas são feitas de carne e ossos cósmicos.", "E": "A vida na Terra surgiu a partir de naves espaciais alienígenas."}, "resposta_correta": "B", "justificativa": "Com exceção de H e parte de He formados no Big Bang, todos os elementos que compõem nosso planeta e nossos corpos foram produzidos por nucleossíntese estelar e dispersos por explosões estelares.", "possui_imagem": false},
  {"id": 214, "uid": "CIEN-9-214", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Cores das Estrelas e Temperatura", "dificuldade": "Fácil", "enunciado": "Ao observar o céu noturno, percebe-se que as estrelas apresentam cores diferentes. Essa diferença de coloração está diretamente relacionada a:", "alternativas": {"A": "Sua velocidade de translação em torno da Lua.", "B": "Sua temperatura superficial (estrelas azuladas são mais quentes, enquanto avermelhadas são mais frias).", "C": "A quantidade de água e vegetação presente em sua superfície.", "D": "A distância exata que elas estão dos satélites de GPS.", "E": "A poluição visual das cidades terrestres apenas."}, "resposta_correta": "B", "justificativa": "Pela física da radiação de corpo negro, a cor de uma estrela reflete sua temperatura superficial: estrelas azuis/brancas têm temperaturas elevadíssimas (> 10.000 K), enquanto estrelas vermelhas são mais frias (~ 3.000 K).", "possui_imagem": true},
  {"id": 215, "uid": "CIEN-9-215", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Anãs Marrons: Estrelas que Não Vingaram", "dificuldade": "Fácil", "enunciado": "Corpos celestes que se formam pelo colapso de gás, mas não possuem massa suficiente para atingir a temperatura e pressão internas necessárias para iniciar a fusão nuclear estável de hidrogênio em seus núcleos, são denominados:", "alternativas": {"A": "Anãs Marrons.", "B": "Supergigantes Vermelhas.", "C": "Galáxias espirais.", "D": "Quasares.", "E": "Supernovas."}, "resposta_correta": "A", "justificativa": "Anãs marrons têm massa intermediária entre planetas gigantes e estrelas (cerca de 13 a 80 massas de Júpiter), insuficiente para sustentar fusão contínua de hidrogênio-1.", "possui_imagem": false},
  {"id": 216, "uid": "CIEN-9-216", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Tempo de Vida das Estrelas e Massa", "dificuldade": "Fácil", "enunciado": "A relação fundamental entre a massa inicial de uma estrela e sua expectativa de vida no Universo é:", "alternativas": {"A": "Quanto maior a massa da estrela, mais tempo ela vive, pois tem mais combustível.", "B": "Quanto maior a massa da estrela, menor é o seu tempo de vida, pois consome seu combustível nuclear em ritmo exponencialmente mais rápido.", "C": "Todas as estrelas vivem exatamente 10 bilhões de anos, independentemente da massa.", "D": "Estrelas sem massa não morrem nunca.", "E": "A massa não tem nenhuma relação com a evolução estelar."}, "resposta_correta": "B", "justificativa": "Estrelas supermassivas possuem pressões e temperaturas nucleares tão titânicas que queimam seu combustível milhões de vezes mais rápido que estrelas pequenas, vivendo apenas alguns milhões de anos, contra bilhões de anos das estrelas menores.", "possui_imagem": false},
  {"id": 217, "uid": "CIEN-9-217", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Diagrama de Hertzsprung-Russell (H-R)", "dificuldade": "Médio", "enunciado": "O Diagrama Hertzsprung-Russell (H-R) é uma ferramenta gráfica crucial da astrofísica que relaciona duas propriedades fundamentais das estrelas:", "alternativas": {"A": "Massa estelar versus distância da Terra em anos-luz.", "B": "Luminosidade (ou magnitude absoluta) versus temperatura superficial (ou tipo espectral/cor).", "C": "Velocidade angular versus número de planetas orbitantes.", "D": "Composição percentual de ferro versus quantidade de água líquida.", "E": "Volume estelar versus idade dos satélites naturais."}, "resposta_correta": "B", "justificativa": "O diagrama H-R mapeia a luminosidade das estrelas em função de sua temperatura superficial/tipo espectral, permitindo visualizar os diferentes grupos evolutivos (Sequência Principal, Gigantes, Supergigantes e Anãs Brancas).", "possui_imagem": true},
  {"id": 218, "uid": "CIEN-9-218", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "A Linha da Sequência Principal no Diagrama H-R", "dificuldade": "Médio", "enunciado": "Cerca de 90% das estrelas observadas no Universo encontram-se na faixa diagonal contínua do Diagrama H-R conhecida como 'Sequência Principal'. A razão física pela qual a imensa maioria das estrelas está nessa faixa é que:", "alternativas": {"A": "Elas estão se deslocando em direção ao centro da Via Láctea.", "B": "Essa faixa corresponde à fase de fusão nuclear estável de hidrogênio no núcleo, que é a etapa mais longa e energeticamente eficiente de toda a vida estelar.", "C": "Todas as estrelas da Sequência Principal já explodiram como supernovas.", "D": "Elas não sofrem ação da gravidade estelar.", "E": "São estrelas mortas que não emitem radiação."}, "resposta_correta": "B", "justificativa": "A conversão de H em He no núcleo sustenta a estrela durante a maior fração de sua existência (cerca de 90% de sua vida ativa), razão pela qual a maioria das estrelas observadas encontra-se na Sequência Principal.", "possui_imagem": false},
  {"id": 219, "uid": "CIEN-9-219", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Ciclo Próton-Próton vs. Ciclo CNO", "dificuldade": "Médio", "enunciado": "A fusão de hidrogênio em hélio no núcleo estelar ocorre principalmente por duas vias nucleares distintas: a cadeia Próton-Próton (p-p) e o ciclo Carbono-Nitrogênio-Oxigênio (CNO). Em estrelas como o Sol e em estrelas muito mais massivas, predominam respectivamente:", "alternativas": {"A": "Ciclo CNO no Sol e cadeia p-p nas estrelas massivas.", "B": "Cadeia Próton-Próton no Sol e ciclo CNO nas estrelas massivas (com temperaturas centrais superiores a 15-20 milhões de Kelvin).", "C": "Fusão de urânio no Sol e de tório nas massivas.", "D": "Ambas realizam exclusivamente fissão nuclear de hélio.", "E": "Cadeia p-p em ambas sem nenhuma diferença térmica."}, "resposta_correta": "B", "justificativa": "O Sol (T_central ~ 15 milhões K) produz energia principalmente pela cadeia p-p. Em estrelas mais massivas, o núcleo atinge temperaturas muito mais altas, onde o ciclo CNO torna-se dominante e supereficiente.", "possui_imagem": false},
  {"id": 220, "uid": "CIEN-9-220", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O 'Flash de Hélio' em Gigantes Vermelhas", "dificuldade": "Médio", "enunciado": "Em estrelas de massa semelhante à do Sol, após a fase de queima de hidrogênio em casca ao redor de um núcleo inerte de hélio degenerado, a ignição da fusão do hélio ocorre de maneira quase explosiva e instantânea. Esse fenômeno é conhecido na astrofísica como:", "alternativas": {"A": "Colapso de Schwarzschild.", "B": "Flash de Hélio (reação triplo-alfa explosiva em matéria eletronicamente degenerada).", "C": "Erupção coronal da Sequência Principal.", "D": "Detonação de oxigênio primordial.", "E": "Emissão pulsar periódica."}, "resposta_correta": "B", "justificativa": "No núcleo degenerado de baixa massa, a pressão não depende da temperatura. Quando a fusão de He se inicia (processo triplo-alfa), a temperatura sobe sem que o núcleo se expanda, gerando uma ignição nuclear descontrolada chamada flash de hélio.", "possui_imagem": false},
  {"id": 221, "uid": "CIEN-9-221", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Processo Triplo-Alfa", "dificuldade": "Médio", "enunciado": "No interior de estrelas gigantes vermelhas, três núcleos de hélio-4 (partículas alfa) fundem-se sucessivamente para formar um núcleo atômico estável de:", "alternativas": {"A": "Hidrogênio-1.", "B": "Carbono-12.", "C": "Ferro-56.", "D": "Chumbo-208.", "E": "Urânio-235."}, "resposta_correta": "B", "justificativa": "O processo triplo-alfa consiste na fusão de dois núcleos de He-4 formando Berílio-8 instável, que captura um terceiro He-4 para formar Carbono-12 estável [3 4He → 12C + energia].", "possui_imagem": false},
  {"id": 222, "uid": "CIEN-9-222", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Pressão de Degenerescência Eletrônica", "dificuldade": "Médio", "enunciado": "Uma Anã Branca não colapsa sob sua própria gravidade devastadora mesmo após ter esgotado todo o seu combustível nuclear. O mecanismo quântico responsável por impedir o colapso gravitacional de uma anã branca é:", "alternativas": {"A": "A pressão de radiação da queima de ferro.", "B": "A pressão de degenerescência eletrônica, fundamentada no Princípio de Exclusão de Pauli.", "C": "A repulsão magnética de seus oceanos superficiais.", "D": "A gravidade externa da Lua e dos cometas.", "E": "O calor de combustão de compostos orgânicos."}, "resposta_correta": "B", "justificativa": "O Princípio de Exclusão de Pauli impede que dois elétrons ocupem o mesmo estado quântico simultaneamente. Essa compressão extrema gera uma pressão de degenerescência que equilibra a gravidade da anã branca.", "possui_imagem": false},
  {"id": 223, "uid": "CIEN-9-223", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Limite de Chandrasekhar", "dificuldade": "Médio", "enunciado": "O astrofísico indiano Subrahmanyan Chandrasekhar calculou a massa máxima teórica que uma Anã Branca pode suportar antes que sua pressão de degenerescência eletrônica sucumba à gravidade. Esse limite crítico (Limite de Chandrasekhar) vale aproximadamente:", "alternativas": {"A": "0,1 massas solares.", "B": "1,44 massas solares.", "C": "10 massas solares.", "D": "50 massas solares.", "E": "100 massas solares."}, "resposta_correta": "B", "justificativa": "O Limite de Chandrasekhar (~ 1,44 massas solares) define a fronteira superior de estabilidade de uma anã branca. Acima dessa massa, ela colapsa em estrela de nêutrons ou sofre supernova tipo Ia.", "possui_imagem": false},
  {"id": 224, "uid": "CIEN-9-224", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Supernova Tipo Ia vs. Tipo II", "dificuldade": "Médio", "enunciado": "Diferencie as origens astrofísicas de uma Supernova Tipo Ia e de uma Supernova Tipo II:\nI. A Supernova Tipo Ia ocorre em sistemas binários quando uma Anã Branca acreta massa de sua companheira e ultrapassa o Limite de Chandrasekhar, detonando termonuclearmente.\nII. A Supernova Tipo II decorre do colapso gravitacional catastrófico do núcleo de ferro de uma estrela única massiva.\nSobre essas afirmações:", "alternativas": {"A": "Apenas a I é verdadeira.", "B": "Apenas a II é verdadeira.", "C": "Ambas são verdadeiras.", "D": "Ambas são falsas.", "E": "As definições estão invertidas."}, "resposta_correta": "C", "justificativa": "Ambas as afirmações são rigorosamente exatas: supernovas termonucleares (Tipo Ia) envolvem anãs brancas em sistemas binários; supernovas de colapso de núcleo (Tipo II) ocorrem em estrelas massivas isoladas.", "possui_imagem": false},
  {"id": 225, "uid": "CIEN-9-225", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Estrutura 'Casca de Cebola' em Estrelas Supermassivas", "dificuldade": "Médio", "enunciado": "Nos estágios avançados que antecedem a morte de uma estrela supermassiva, seu interior desenvolve uma estrutura concêntrica apelidada de 'casca de cebola'. As camadas de queima nuclear se organizam da periferia para o centro em ordem de elementos cada vez mais pesados, culminando em um núcleo inerte de:", "alternativas": {"A": "Hélio.", "B": "Carbono.", "C": "Oxigênio.", "D": "Ferro.", "E": "Ouro."}, "resposta_correta": "D", "justificativa": "Estrelas supermassivas realizam fusões sucessivas em camadas concêntricas (H → He → C → Ne → O → Si), depositando no centro um núcleo terminal inerte de Ferro (Fe-56).", "possui_imagem": false},
  {"id": 226, "uid": "CIEN-9-226", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Por que a Fusão Encerra no Ferro-56?", "dificuldade": "Médio", "enunciado": "O núcleo de Ferro-56 (e Níquel-56) representa o limite termonuclear final da fusão em estrelas massivas porque:", "alternativas": {"A": "O ferro é um gás que evapora imediatamente do núcleo.", "B": "O núcleo de Ferro-56 possui uma das maiores energias de ligação nuclear por núcleon da natureza; fundir ferro é um processo endotérmico (consome energia em vez de liberar), cessando a pressão térmica sustentadora.", "C": "O ferro atrai elétrons transformando-se em hidrogênio novamente.", "D": "Não existem átomos de ferro no espaço.", "E": "A fusão de ferro resfria a estrela a zero absoluto instantaneamente."}, "resposta_correta": "B", "justificativa": "A fusão nuclear só é exotérmica até a região do pico do ferro (Fe-56). A fusão de núcleos de ferro absorve energia do núcleo estelar, privando a estrela de sua sustentação térmica contra a gravidade.", "possui_imagem": false},
  {"id": 227, "uid": "CIEN-9-227", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O que são Pulsares?", "dificuldade": "Médio", "enunciado": "Muitas estrelas de nêutrons recém-formadas em supernovas emitem feixes estreitos e contínuos de radiação eletromagnética a partir de seus polos magnéticos. Quando esses feixes varrem periodicamente a linha de visada da Terra devido à rápida rotação da estrela, são detectados como pulsos rítmicos regulares chamados:", "alternativas": {"A": "Exoplanetas.", "B": "Pulsares.", "C": "Quasares ópticos.", "D": "Nebulosas escuras.", "E": "Eclipses estelares."}, "resposta_correta": "B", "justificativa": "Pulsares são estrelas de nêutrons altamente magnetizadas que giram rapidamente sobre seu eixo, emitindo feixes de radiação que agem como um farol cósmico periódico.", "possui_imagem": false},
  {"id": 228, "uid": "CIEN-9-228", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Horizonte de Eventos de um Buraco Negro", "dificuldade": "Médio", "enunciado": "Em relação à física de um Buraco Negro, o 'horizonte de eventos' representa:", "alternativas": {"A": "A superfície sólida onde pousam naves espaciais.", "B": "A fronteira limite ao redor da singularidade a partir da qual a velocidade de escape iguala a velocidade da luz no vácuo, tornando impossível qualquer matéria ou informação retornar ao Universo exterior.", "C": "A camada externa de gás que queima hidrogênio.", "D": "O centro exato onde o tempo passa duas vezes mais rápido.", "E": "Uma névoa de poeira que reflete a luz das galáxias vizinhas."}, "resposta_correta": "B", "justificativa": "O horizonte de eventos é o ponto de não retorno: qualquer objeto ou fóton que cruzar essa fronteira estará inexoravelmente destinado a atingir a singularidade central.", "possui_imagem": false},
  {"id": 229, "uid": "CIEN-9-229", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Raio de Schwarzschild", "dificuldade": "Médio", "enunciado": "O raio do horizonte de eventos de um buraco negro estático e esférico (sem rotação) é denominado Raio de Schwarzschild [Rs = 2GM/c²]. Se a massa do Sol (cerca de 2 × 10^30 kg) fosse magicamente comprimida até virar um buraco negro, seu Raio de Schwarzschild seria de aproximadamente:", "alternativas": {"A": "3 quilômetros.", "B": "3.000 quilômetros.", "C": "6.400 quilômetros (o raio da Terra).", "D": "150 milhões de quilômetros.", "E": "Zero metros (desapareceria no vácuo)."}, "resposta_correta": "A", "justificativa": "Substituindo a massa do Sol na fórmula Rs = 2GM/c², obtém-se aproximadamente 2,95 km (~ 3 km). Toda a massa solar precisaria caber numa esfera de apenas 6 km de diâmetro.", "possui_imagem": false},
  {"id": 230, "uid": "CIEN-9-230", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Nucleossíntese dos Elementos mais Pesados que o Ferro", "dificuldade": "Médio", "enunciado": "Como a fusão no interior de estrelas estáveis só produz elementos até o ferro, elementos mais pesados (como cobre, prata, ouro, platina e urânio) são forjados no Universo principalmente por:", "alternativas": {"A": "Fotossíntese em exoplanetas rochosos.", "B": "Processos de captura de nêutrons rápidos e lentos (processo r e processo s) durante explosões catastróficas de supernovas e colisões de estrelas de nêutrons (quilonovas).", "C": "Resfriamento térmico de cometas na Nuvem de Oort.", "D": "Fusão a frio nos oceanos primitivos da Terra.", "E": "Fricção entre placas tectônicas continentais."}, "resposta_correta": "B", "justificativa": "Elementos mais pesados que o ferro exigem fluxos intensíssimos de nêutrons livres capturados por núcleos sementes (processos s e r), gerados durante supernovas e fusões colisionais de estrelas de nêutrons (quilonovas).", "possui_imagem": false},
  {"id": 231, "uid": "CIEN-9-231", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Evolução do Sol e o Destino da Terra", "dificuldade": "Médio", "enunciado": "Daqui a aproximadamente 5 bilhões de anos, quando o Sol atingir o ápice de sua fase de Gigante Vermelha, o cenário astrofísico esperado para o Sistema Solar interior é:", "alternativas": {"A": "O Sol congelará e se transformará em um cometa de gelo seco.", "B": "As camadas externas solares se expandirão a ponto de engolir os planetas Mercúrio e Vênus, e possivelmente a órbita da Terra, vaporizando oceanos e tornando a vida terrestre inviável muito antes disso.", "C": "O Sol explodirá em uma supernova devastadora destruindo a Via Láctea.", "D": "Júpiter e Saturno serão atraídos para o centro da Lua.", "E": "O Sol se fundirá com a estrela Proxima Centauri."}, "resposta_correta": "B", "justificativa": "A expansão solar na fase de Gigante Vermelha alcançará ~ 1 Unidade Astronômica, engolindo os planetas internos e dessecando completamente a biosfera terrestre.", "possui_imagem": false},
  {"id": 232, "uid": "CIEN-9-232", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Nebulosa Planetária: O que é de Fato?", "dificuldade": "Médio", "enunciado": "O termo histórico 'nebulosa planetária' foi cunhado no século XVIII por astrônomos como William Herschel porque, nos telescópios da época, esses objetos se assemelhavam visualmente a discos de planetas gigantes gasosos (como Urano). Fisicamente, contudo, uma nebulosa planetária nada tem a ver com planetas; ela consiste em:", "alternativas": {"A": "Um enxame de asteroides colidindo com cometas.", "B": "Camadas gasosas ionizadas e ricas em carbono/oxigênio ejetadas suavemente por uma estrela gigante vermelha moribunda, iluminadas pela radiação ultravioleta da anã branca central.", "C": "Uma nuvem de poeira que está prestes a formar um planeta habitável.", "D": "Um anel de poeira e gelo que orbita planetas como Saturno.", "E": "Uma tempestade magnética na atmosfera de Vênus."}, "resposta_correta": "B", "justificativa": "Nebulosas planetárias são envelopes gasosos desprendidos pelas pulsações térmicas finais de gigantes vermelhas, iluminados pela anã branca remanescente no centro.", "possui_imagem": false},
  {"id": 233, "uid": "CIEN-9-233", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "A Velocidade da Luz como 'Máquina do Tempo'", "dificuldade": "Médio", "enunciado": "Quando os astrônomos apontam telescópios espaciais (como Hubble ou James Webb) para galáxias situadas a 10 bilhões de anos-luz de distância, eles estão observando esses objetos celestes:", "alternativas": {"A": "Exatamente como eles são no presente momento em tempo real.", "B": "Como eles eram há 10 bilhões de anos, quando o Universo era jovem, devido ao tempo finito que a luz levou para viajar pelo cosmos até nossos detectores.", "C": "No futuro, prevendo o que acontecerá daqui a 10 bilhões de anos.", "D": "Apenas como ilusões de ótica geradas pela atmosfera terrestre.", "E": "Como se fossem estrelas do Sistema Solar interior."}, "resposta_correta": "B", "justificativa": "Como a velocidade da luz é finita (c ~ 300.000 km/s), olhar para objetos distantes significa olhar para o passado cósmico, revelando a história evolutiva das primeiras estrelas e galáxias.", "possui_imagem": false},
  {"id": 234, "uid": "CIEN-9-234", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Massa de Jeans e Colapso Gravitacional", "dificuldade": "Difícil", "enunciado": "O colapso gravitacional de uma nuvem de gás interestelar só se inicia quando sua massa total excede um valor crítico teórico formulado pelo físico James Jeans (Massa de Jeans). Fisicamente, o critério de instabilidade de Jeans estabelece que o colapso ocorrerá se:", "alternativas": {"A": "A energia cinética térmica interna das partículas de gás da nuvem for insuficiente para contrabalançar a atração gravitacional própria da nuvem.", "B": "A temperatura da nuvem subir para mais de 1 bilhão de graus Celsius.", "C": "A nuvem for composta por 100% de átomos de ferro sólido.", "D": "A velocidade de rotação da nuvem superar a velocidade da luz.", "E": "A nuvem se chocar contra a crosta de um planeta rochoso."}, "resposta_correta": "B", "justificativa": "A instabilidade de Jeans ocorre quando a força de atração gravitacional mútua supera a pressão térmica do gás (energia potencial gravitacional > 2 × energia cinética térmica, pelo Teorema do Virial).", "possui_imagem": false},
  {"id": 235, "uid": "CIEN-9-235", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Limite de Oppenheimer-Volkoff (TOV)", "dificuldade": "Difícil", "enunciado": "Assim como o Limite de Chandrasekhar rege a massa máxima de uma anã branca, o Limite de Tolman-Oppenheimer-Volkoff (TOV) estabelece o limite superior de massa para que uma Estrela de Nêutrons seja sustentada pela pressão de degenerescência de nêutrons. Se o remanescente estelar colapsado superar o limite TOV (estimado entre 2,1 e 3 massas solares), o destino inevitável do objeto é:", "alternativas": {"A": "Expandir-se instantaneamente em uma nova Gigante Vermelha estável.", "B": "Colapsar gravitacionalmente sem barreiras físicas conhecidas, culminando na formação de uma singularidade no interior de um Buraco Negro.", "C": "Explodir em pó de cometa e desaparecer da Via Láctea.", "D": "Transformar-se em um planeta rochoso rico em diamantes.", "E": "Retornar ao estágio de protoestrela da Sequência Principal."}, "resposta_correta": "B", "justificativa": "Acima do limite TOV, nem mesmo a pressão de degenerescência de nêutrons consegue frear a atração gravitacional extrema, resultando no colapso inevitável para um buraco negro.", "possui_imagem": false},
  {"id": 236, "uid": "CIEN-9-236", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "A Linha de Hayashi e Contração Pré-Sequência Principal", "dificuldade": "Difícil", "enunciado": "Durante a fase de contração de uma protoestrela a caminho da Sequência Principal, ela se desloca no Diagrama H-R ao longo de trajetórias evolutivas conhecidas como 'Trilhas de Hayashi' e 'Trilhas de Henyey'. A característica fundamental de uma protoestrela na Trilha de Hayashi é:", "alternativas": {"A": "Estar em equilíbrio convectivo quase completo com luminosidade decrescente e temperatura superficial praticamente constante.", "B": "Estar fundindo ferro em seu núcleo a temperaturas de 1 trilhão de Kelvin.", "C": "Ter atingido o equilíbrio térmico de uma estrela de nêutrons.", "D": "Ser invisível a telescópios de infravermelho por falta de calor.", "E": "Orbita satélites de chumbo."}, "resposta_correta": "A", "justificativa": "Na trilha de Hayashi, a protoestrela é totalmente convectiva; à medida que colapsa gravitacionalmente, seu raio diminui, fazendo sua luminosidade cair enquanto sua temperatura efetiva permanece quase inalterada.", "possui_imagem": false},
  {"id": 237, "uid": "CIEN-9-237", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Teorema do Virial Aplicado a Estrelas", "dificuldade": "Difícil", "enunciado": "De acordo com o Teorema do Virial aplicado a um sistema esférico autogravitante de gás ideal em equilíbrio estático, a energia potencial gravitacional (U) e a energia cinética térmica interna (K) relacionam-se por 2K + U = 0. Uma consequência fundamental desse teorema para a contração gravitacional de uma protoestrela é:", "alternativas": {"A": "Toda a energia liberada na contração se perde como ondas de rádio.", "B": "Exatamente metade da energia potencial gravitacional liberada na contração é convertida em energia térmica interna (aquecendo o núcleo) e a outra metade é irradiada para o espaço na forma de luz.", "C": "A contração resfria a estrela até transformá-la em gelo.", "D": "A energia total da estrela torna-se positiva e ela se dispersa.", "E": "O calor do núcleo atrai planetas interestelares para a sua atmosfera."}, "resposta_correta": "B", "justificativa": "Pelo Teorema do Virial, ΔK = -1/2 ΔU e a energia irradiada é L = -1/2 ΔU. Metade da energia gravitacional aquece o núcleo até alcançar os ~ 10-15 milhões de K necessários para a ignição da fusão nuclear.", "possui_imagem": false},
  {"id": 238, "uid": "CIEN-9-238", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Degenerescência de Nêutrons e Força Nuclear Forte Repulsiva", "dificuldade": "Difícil", "enunciado": "Em uma estrela de nêutrons, a matéria atinge densidades nucleares da ordem de 10^14 g/cm³ (uma colher de chá pesaria centenas de milhões de toneladas). O suporte contra o colapso decorre não apenas da pressão de degenerescência de nêutrons (mecanismo quântico), mas também:", "alternativas": {"A": "Da atração eletrostática entre prótons vizinhos.", "B": "Da componente repulsiva de curto alcance da força nuclear forte entre núcleons a distâncias extremamente diminutas.", "C": "Da gravidade negativa de partículas de antimatéria.", "D": "Do atrito térmico dos fótons de micro-ondas.", "E": "Da perda contínua de elétrons para o vácuo quântico."}, "resposta_correta": "B", "justificativa": "A distâncias subnucleares ultra-apertadas (< 0,7 fm), a força nuclear forte torna-se fortemente repulsiva, fornecendo a rigidez necessária para equilibrar a colossal gravidade de uma estrela de nêutrons.", "possui_imagem": false},
  {"id": 239, "uid": "CIEN-9-239", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Espaguetificação e Forças de Maré Próximo a Buracos Negros", "dificuldade": "Difícil", "enunciado": "Um astronauta hipotético que caísse em direção ao horizonte de eventos de um buraco negro de massa estelar sofreria o efeito extremo de 'espaguetificação'. O princípio da física gravitacional que rege essa deformação extrema é:", "alternativas": {"A": "O atrito violento contra a atmosfera gasosa do buraco negro.", "B": "A diferença brutal na intensidade da força gravitacional exercida sobre partes distintas do corpo (gradiente de maré gravitacional), esticando o astronauta longitudinalmente na direção da queda e comprimindo-o lateralmente.", "C": "A atração magnética de átomos de ferro em sua roupa espacial.", "D": "A queima instantânea por reações de combustão química de hidrogênio.", "E": "O congelamento pelo vácuo absoluto a zero Kelvin."}, "resposta_correta": "B", "justificativa": "A espaguetificação resulta de forças de maré gravitacionais diferenciais extremas: a aceleração da gravidade nos pés é incomparavelmente maior do que na cabeça, esticando o corpo ao longo da direção radial.", "possui_imagem": false},
  {"id": 240, "uid": "CIEN-9-240", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Desvio para o Vermelho Gravitacional (Gravitational Redshift)", "dificuldade": "Difícil", "enunciado": "Segundo a Teoria da Relatividade Geral de Albert Einstein, a luz emitida pela superfície de um corpo celeste ultradenso (como uma anã branca ou estrela de nêutrons) sofre 'desvio para o vermelho gravitacional'. Esse fenômeno físico ocorre porque:", "alternativas": {"A": "A estrela está se afastando da Terra em velocidade relativística.", "B": "Os fótons perdem energia ao subir contra o intenso poço de potencial gravitacional do astro, o que diminui sua frequência e aumenta seu comprimento de onda (deslocando a luz para o vermelho).", "C": "A atmosfera da estrela contém poeira vermelha de óxido de ferro.", "D": "A velocidade da luz diminui para metade no campo gravitacional.", "E": "A gravidade altera a carga elétrica dos elétrons na estrela."}, "resposta_correta": "B", "justificativa": "Para escapar de um campo gravitacional intenso, a radiação eletromagnética realiza trabalho contra a gravidade, perdendo energia. Como E = hf, a redução de frequência acarreta aumento do comprimento de onda (redshift gravitacional).", "possui_imagem": false},
  {"id": 241, "uid": "CIEN-9-241", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Emissão de Ondas Gravitacionais por Binárias Compactas", "dificuldade": "Difícil", "enunciado": "A detecção histórica de ondas gravitacionais pelo observatório LIGO/Virgo (como no evento GW150914 e GW170817) confirmou previsões teóricas sobre a evolução de sistemas binários de objetos compactos. A fusão de duas estrelas de nêutrons (quilonova):", "alternativas": {"A": "Consiste em um fenômeno puramente óptico sem emissão mecânica do espaço-tempo.", "B": "Provoca ondulações no próprio tecido do espaço-tempo que se propagam à velocidade da luz, acompanhadas da síntese maciça de elementos químicos pesados por processo r de captura rápida de nêutrons.", "C": "Destrói a Via Láctea criando um novo Big Bang.", "D": "Gera apenas gás oxigênio e água pura no vácuo.", "E": "Cessa para sempre a expansão acelerada do cosmos."}, "resposta_correta": "B", "justificativa": "A coalescência de binárias de estrelas de nêutrons deforma o espaço-tempo emitindo ondas gravitacionais de alta frequência e sintetiza enormes quantidades de elementos pesados (ouro, platina) via processo r.", "possui_imagem": false},
  {"id": 242, "uid": "CIEN-9-242", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Radiação de Hawking em Buracos Negros", "dificuldade": "Difícil", "enunciado": "Proposta pelo físico britânico Stephen Hawking em 1974, a 'Radiação de Hawking' prevê que buracos negros não são completamente negros, mas emitem radiação térmica e podem evaporar ao longo de escalas de tempo cosmológicas. O fundamento da mecânica quântica por trás dessa emissão é:", "alternativas": {"A": "A explosão contínua de bombas atômicas no interior da singularidade.", "B": "A flutuação quântica do vácuo próxima ao horizonte de eventos, onde pares virtuais partícula-antipartícula são criados; uma das partículas cai no buraco negro com energia negativa, enquanto a outra escapa para o infinito com energia real positiva.", "C": "A colisão de asteroides com o disco de acreção brilhante.", "D": "A queima química de combustíveis fósseis no horizonte de eventos.", "E": "O reflexo da luz solar nas bordas do espaço-tempo."}, "resposta_correta": "B", "justificativa": "Flutuações quânticas no vácuo geram pares virtuais no horizonte. A partícula que cai com energia negativa reduz a massa do buraco negro, enquanto a parceira externa escapa como radiação Hawking térmica.", "possui_imagem": false},
  {"id": 243, "uid": "CIEN-9-243", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O Paradoxo da Informação em Buracos Negros", "dificuldade": "Difícil", "enunciado": "O 'Paradoxo da Informação em Buracos Negros' representa um dos maiores dilemas teóricos da física contemporânea porque coloca em conflito direto dois pilares fundamentais da ciência:", "alternativas": {"A": "A Lei de Lavoisier e a teoria da evolução de Darwin.", "B": "A Relatividade Geral (segundo a qual a matéria que cai no buraco negro é destruída na singularidade e se perde para sempre) e a Mecânica Quântica (segundo a qual a evolução temporal é unitária e a informação quântica jamais pode ser destruída).", "C": "A termodinâmica clássica e a óptica geométrica de Newton.", "D": "A teoria celular e a geologia das placas tectônicas.", "E": "A astronomia maia e o calendário gregoriano moderno."}, "resposta_correta": "B", "justificativa": "A mecânica quântica exige conservação estrita da informação (unitariedade). Se a radiação Hawking for puramente térmica e o buraco negro evaporar completamente sem deixar rastros, a informação inicial teria sido destruída, violando a mecânica quântica.", "possui_imagem": false},
  {"id": 244, "uid": "CIEN-9-244", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Fotodesintegração e Captura Eletrônica no Colapso do Núcleo", "dificuldade": "Difícil", "enunciado": "No instante que desencadeia a explosão de uma Supernova Tipo II, a temperatura central atinge ~ 5 × 10^9 K e a densidade ultrapassa 10^9 g/cm³. Dois processos nucleares críticos causam a queda abrupta da pressão de suporte e aceleram o colapso livre do núcleo de ferro em milissegundos:", "alternativas": {"A": "A evaporação da água e a queima de nitrogênio atmosférico.", "B": "A fotodesintegração nuclear (fótons gama de alta energia quebram núcleos de ferro em partículas alfa e nêutrons) e a captura eletrônica (elétrons combinam-se com prótons formando nêutrons e emitindo neutrinos, retirando elétrons degenerados).", "C": "A fusão de hidrogênio em hélio acelerada.", "D": "A condensação do ferro em diamantes gigantescos.", "E": "A formação de moléculas orgânicas de DNA estelar."}, "resposta_correta": "B", "justificativa": "A fotodesintegração é endotérmica (rouba energia térmica do núcleo) e a captura eletrônica elimina os elétrons livres responsáveis pela pressão de degenerescência. Sem suporte, o núcleo entra em colapso gravitacional em queda livre.", "possui_imagem": false},
  {"id": 245, "uid": "CIEN-9-245", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "O Papel dos Neutrinos na Explosão de Supernovas", "dificuldade": "Difícil", "enunciado": "Durante o colapso do núcleo de uma estrela massiva formando uma estrela de nêutrons, cerca de 99% de toda a colossal energia liberada no evento de supernova (mais de 10^46 Joules) é emitida na forma de:", "alternativas": {"A": "Luz visível e raios laser ópticos.", "B": "Neutrinos de todos os sabores eletrônicos, muônicos e tauônicos.", "C": "Ondas sonoras que viajam pelo vácuo espacial.", "D": "Campos magnéticos estáticos terrestres.", "E": "Vapor de água superaquecido."}, "resposta_correta": "B", "justificativa": "A neutronização massiva do núcleo emite uma torrente incomensurável de neutrinos, que transportam 99% da energia de ligação gravitacional liberada no colapso do núcleo.", "possui_imagem": false},
  {"id": 246, "uid": "CIEN-9-246", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Disco de Acreção e Emissão em Raios-X", "dificuldade": "Difícil", "enunciado": "Quando um buraco negro ou estrela de nêutrons faz parte de um sistema binário próximo, ele extrai gás de sua estrela companheira. Esse gás espirala em direção ao objeto compacto formando um 'disco de acreção'. A razão pela qual esses discos emitem intensamente na faixa de raios-X é:", "alternativas": {"A": "A presença de lâmpadas de xenônio alienígenas no disco.", "B": "O atrito viscoso extremo e a perda de energia potencial gravitacional que aquecem o gás do disco a temperaturas de milhões de graus Kelvin, emitindo radiação eletromagnética de altíssima energia (raios-X).", "C": "O reflexo da luz lunar na superfície fria do disco.", "D": "A queima incompleta de monóxido de carbono no espaço.", "E": "A atração gravitacional de raios solares infravermelhos."}, "resposta_correta": "B", "justificativa": "A conversão de energia potencial gravitacional em calor por viscosidade no disco de acreção atinge milhões de Kelvins, fazendo o plasma irradiar fortemente na faixa de raios-X.", "possui_imagem": false},
  {"id": 247, "uid": "CIEN-9-247", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Evolução Química Galáctica e Populações Estelares", "dificuldade": "Difícil", "enunciado": "Em astrofísica galáctica, as estrelas são classificadas em População I (estrelas jovens ricas em metais, como o Sol), População II (estrelas velhas pobres em metais) e População III (estrelas primordiais hipotéticas formadas logo após o Big Bang). Essa variação na 'metalicidade' das estrelas demonstra que:", "alternativas": {"A": "O Universo está perdendo matéria a cada segundo que passa.", "B": "As sucessivas gerações de estrelas enriquecem progressivamente o meio interestelar com elementos pesados (metais) sintetizados por fusão e supernovas, de modo que estrelas mais jovens nascem de nuvens quimicamente mais enriquecidas.", "C": "Estrelas antigas eram feitas de ouro e as modernas são feitas de hidrogênio.", "D": "A composição química das estrelas independe de sua época de formação.", "E": "O Big Bang produziu todos os elementos da tabela periódica em quantidades iguais."}, "resposta_correta": "B", "justificativa": "A evolução química galáctica é cumulativa: cada geração de estrelas sintetiza metais e os ejeta no meio interestelar por ventos e supernovas, aumentando a metalicidade das gerações estelares subsequentes.", "possui_imagem": false},
  {"id": 248, "uid": "CIEN-9-248", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Mecanismo de Enriquecimento por Ventos Estelares em Gigantes AGB", "dificuldade": "Difícil", "enunciado": "Estrelas no Ramo Assintótico das Gigantes (estrelas AGB, estágio final de estrelas de massa intermediária) realizam dragagens térmicas periódicas ('dredge-up') que trazem carbono e elementos do processo s do núcleo para a atmosfera estelar. A ejeção desses gases por ventos estelares lentos é a fonte primária cósmica de:", "alternativas": {"A": "Ferro e níquel que compõem o núcleo da Terra.", "B": "Grãos de poeira interestelar ricos em carbono e fuligem que semeiam futuras nuvens moleculares e viabilizam a formação de moléculas orgânicas no cosmos.", "C": "Água oxigenada pura e ácido sulfúrico estelar.", "D": "Campos gravitacionais de matéria escura bariônica.", "E": "Raios cósmicos que aceleram a velocidade da luz."}, "resposta_correta": "B", "justificativa": "As estrelas AGB são as maiores 'fábricas de poeira cósmica' de carbono do Universo, expelindo grãos carbonáceos essenciais para a química pré-biótica em discos protoplanetários.", "possui_imagem": false},
  {"id": 249, "uid": "CIEN-9-249", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "Singularidade Gravitacional: Limite da Física Conhecida", "dificuldade": "Difícil", "enunciado": "No modelo clássico da Relatividade Geral de Einstein, o centro de um buraco negro abriga uma 'singularidade gravitacional'. A natureza física de uma singularidade e o motivo pelo qual ela desafia a física contemporânea residem no fato de que:", "alternativas": {"A": "Ela é uma esfera de fogo perfeitamente compreendida pelas leis de Newton.", "B": "Trata-se de um ponto (ou anel, em buracos negros com rotação de Kerr) onde a densidade de massa e a curvatura do espaço-tempo tendem matematicamente ao infinito, indicando que a Relatividade Geral atinge seu limite de validade e exige uma teoria unificada de Gravitação Quântica para ser descrita.", "C": "Ela é uma porta dimensional para planetas habitados da galáxia de Andrômeda.", "D": "Ela cancela todas as leis da matemática conhecidas por seres humanos.", "E": "Ela é composta de água em temperatura negativa."}, "resposta_correta": "B", "justificativa": "Na singularidade, a relatividade geral clássica prevê densidade e curvatura infinitas, sinalizando a quebra da teoria e a necessidade indispensável de uma Gravitação Quântica ainda não estabelecida.", "possui_imagem": false},
  {"id": 250, "uid": "CIEN-9-250", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "9º Ano", "ano": "9º Ano", "modulo": "Módulo 19: Astronomia e Evolução Estelar", "tema": "A Linha do Tempo Cósmica e o Destino Final do Universo Estelar", "dificuldade": "Difícil", "enunciado": "De acordo com os modelos astrofísicos da Era Estelar (Stelliferous Era), daqui a cerca de 100 trilhões de anos (10^14 anos), a formação de novas estrelas no Universo cessará definitivamente devido à exaustão de nuvens de gás hidrogênio. A partir desse ponto, os últimos corpos estelares a brilharem fracamente no cosmos por trilhões de anos antes do resfriamento total serão as:", "alternativas": {"A": "Supergigantes azuis hiperluminosas.", "B": "Anãs Vermelhas de baixíssima massa, que queimam hidrogênio de forma extremamente lenta e eficiente por convecção total.", "C": "Supernovas de galáxias vizinhas.", "D": "Anãs Brancas de ferro líquido.", "E": "Nebulosas moleculares primordiais."}, "resposta_correta": "B", "justificativa": "Anãs vermelhas de massa mínima (~ 0,08 massas solares) são totalmente convectivas e fundem quase 100% de seu hidrogênio em ritmo ultra-lento, possuindo vidas estelares estimadas em até 10 a 17 trilhões de anos.", "possui_imagem": false}
];
